window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["人生"]=[{"uid":"06203cef-1dc5-4d60-9ef7-a4bf4306c730","title":"送裴补阙入河南幕","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎然青琐客，何事动行轩。","苦节酬知己，清吟去掖垣。","秋城临海树，寒月上营门。","邹鲁诗书国，应无鼙鼓喧。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"b693eaa3-5152-47da-bb89-56ac4b2d11cd","title":"杂曲歌辞 古别离二首 二","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老母别爱子，少妻送征郎。","血流既四面，乃亦断二肠。","不愁寒无衣，不怕饥无粮。","惟恐征战不还乡，母化为鬼妻为孀。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["离别","伤感"],"人物":["母亲"],"人生":["战争"]},"theme_conf":0.618},{"uid":"0eaa8b3b-92d7-413b-ad72-8c9ac3bd4f80","title":"梦后吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["醉中还有梦，身外已无心。","明镜唯知老，青山何处深。"],"theme":"游仙梦幻","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["酒","山"],"cats":{"人生":["梦想"]},"theme_conf":1.0},{"uid":"321a1b75-4cdf-48c7-8f57-047300fa7f50","title":"杂曲歌辞 水调 歌第一","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["平沙落日大荒西，陇上明星高复低。","孤山几处看烽火，壮士连营候鼓鼙。"],"theme":"边塞征战","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["战争"]},"theme_conf":0.506},{"uid":"ecec07dc-9a38-48ac-8454-7124346a047c","title":"江行无题一百首 七十九","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["身世比行舟，无风亦暂休。","敢言终破浪，唯愿稳乘流。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江","舟"],"cats":{"人生":["励志"]},"theme_conf":0.65},{"uid":"4bb52f17-5109-4d2a-93b9-7e1074dbb45b","title":"酬鸿胪裴主簿雨后睢阳北楼见赠之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮霞照新晴，归云犹相逐。","有怀晨昏暇，相见登眺目。","问礼侍彤襜，题诗访茅屋。","高楼多古今，陈事满陵谷。","地久微子封，台余孝王筑。","裴回顾霄汉，豁达俯川陆。","远水对秋城，长天向乔木。","公门何清净，列戟森已肃。","不叹携手稀，恒思着鞭速。","终当拂羽翰，轻举随鸿鹄。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","旷达"],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"人生":["梦想"],"动物":["写鸟"]},"theme_conf":0.8},{"uid":"93d82a12-5e4d-45c2-b837-d0c54447fba3","title":"与高适薛据慈恩寺浮图","author":"岑参","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塔势如涌出，孤高耸天宫。","登临出世界，磴道盘虚空。","突兀压神州，峥嵘如鬼工。","四角碍白日，七层摩苍穹。","下窥指高鸟，俯听闻惊风。","连山若波涛，奔凑似朝东。","青槐夹驰道，宫馆何玲珑。","秋色从西来，苍然满关中。","五陵北原上，万古青蒙蒙。","净理了可悟，胜因夙所宗。","誓将挂冠去，觉道资无穷。"],"theme":"题画咏艺","theme2":["哲理悟道"],"style":"雄浑","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.615},{"uid":"6326d175-7980-4cbc-9237-62120d12a482","title":"献荥阳公诗五十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑驿骑翩翩，丘门子弟贤。","文翁开学日，正礼骋途年。","骏骨黄金买，英髦绛帐延。","趋风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","凤攒题字扇，鱼落讲经筵。","盛气河包济，贞姿岳柱天。","臯夔当五百，邹鲁重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗缀夜珠联。","逸礼多心匠，焚书旧口传。","陈遵修尺牍，阮瑀让飞牋。","中的颜初启，抽毫踵未旋。","森罗万木合，属对百花全。","词海跳波涌，文星拂坐悬。","戴冯遥避席，祖逖后施鞭。","西蜀凌云赋，东阳咏月篇。","劲芟鼇足断，精贯虱心穿。","浩汗神弥王，鹞飏兴欲仙。","冰壶通皓雪，绮树眇晴烟。","驱驾雷霆走，铺陈锦绣鲜。","情机登穾奥，流韵溢山川。","墨客膺潜服，谈宾膝误前。","张鳞定摧败，折角反矜怜。","句句推琼玉，声声播管弦。","纤新撩造化，澒洞斡陶甄。","卫磬琤鍧极，齐竽僭滥偏。","空虚慙炙輠，点窜许怀铅。","惫色秋来草，哀吟雨后蝉。","自伤魂惨沮，何暇思幽玄。","喜到樽罍侧，愁亲几案边。","菁华知竭矣，胏腑尚求旃。","抵滞浑成醉，徘徊转慕膻。","老叹才渐少，闲苦病相煎。","瓦砾难追琢，刍荛分弃捐。","漫劳成恳恳，那得美娟娟。","拙劣仍非速，迂愚且异专。","移时停笔砚，挥景乏戈鋋。","仪舌忻犹在，舒帷誓不褰。","会将连献楚，深耻谬游燕。","蒲有临书叶，韦充读易编。","沙须披见宝，经拟带耕田。","入雾长期闰，持朱本望研。","轮辕呈曲直，凿枘取方圆。","呼吸宁徒尔，沾濡岂浪然。","过箫资响亮，随水涨沦涟。","惜日看圭短，偷光恨壁坚。","勤勤雕朽木，细细导蒙泉。","传癖今应甚，头风昨已痊。","丹青公旧物，一为变蚩妍。"],"theme":"应制干谒","theme2":["山水田园","应制干谒","羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["酒","雪","冬","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.98},{"uid":"cp55185352520840","title":"洞仙歌","author":"李元膺","dynasty":"宋","section":"宋词","form":"词","paragraphs":["雪云散尽，放晓晴池院。","杨柳于人便青眼。","更风流多处，一点梅心、相映远。","约略轻笑浅。","一年春好处，不在浓芳，小艳疏香最娇软。","到清明时候，百紫千红花正乱。","已失春风一半。","蚤占取韶光，共追游，但莫管春寒，醉红自暖。"],"theme":"咏怀抒感","theme2":["游仙梦幻"],"style":"清新","style2":["婉约","旷达"],"mood":"欢愉","mood2":[],"scene":["花","清明","园林","春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.74},{"uid":"f4227169-1e61-4208-aaeb-ebea6439eec0","title":"秋日送僧志幽归山寺","author":"秦系","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禅室绳床在翠微，松间荷笠一僧归。","磬声寂历宜秋夜，手冷灯前自衲衣。"],"theme":"送别","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.97},{"uid":"f7c5a05e-436c-4fd9-b093-3886e90cd529","title":"酬裴杰秀才新樱桃","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["新果真琼液，来应宴紫兰。","圆疑窃龙颔，色已夺鸡冠。","远火微微辨，残星隐隐看。","茂先知味易，曼倩恨偷难。","忍用烹骍骆，从将玩玉盘。","流年如可驻，何必九华丹。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["清新","旷达"],"mood":"愁怨","mood2":["欢愉"],"scene":[],"cats":{"人生":["时光"],"植物":["桃花"]},"theme_conf":0.86},{"uid":"918eefe5-fd66-441d-ac06-01ad799fb485","title":"绛州过夏留献郑尚书","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝朝沈醉引金船，不觉西风满树蝉。","光景暗消银烛下，梦魂长寄玉轮边。","因循每被时流诮，奋发须由国士怜。","明月客肠何处断，绿槐风里独扬鞭。"],"theme":"应制干谒","theme2":["应制干谒","送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月"],"cats":{"抒情":["思乡","孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["励志"]},"theme_conf":0.95},{"uid":"133359e4-c7c2-4a43-9adc-e5e8ea4e2e41","title":"杂曲歌辞 少年行四首 三","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["弓背霞明劒照霜，秋风走马出咸阳。","未收天子河湟地，不拟回头望故乡。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.517},{"uid":"939b6cc6-63cf-4c88-a5bf-7396fac69fb1","title":"题青龙寺镜公房","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一室意何有，闲门为我开。","炉香寒自灭，履雪饭初回。","窗迥孤山入，灯残片月来。","禅心方此地，不必访天台。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪","月","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"e3bf5676-319c-460e-b5b2-e53daad7f6d0","title":"秋行官张请督促东渚耗稻向毕清晨遣女奴阿稽竖子阿段往问","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东渚雨今足，伫闻稉稻香。","上天无偏颇，蒲稗各自长。","人情见非类，田家戒其荒。","功夫竞搰搰，除草置岸旁。","谷者命之本，客居安可忘。","青春具所务，勤垦免乱常。","吴牛力容易，竝驱动莫当。","丰苗亦已穊，云水照方塘。","有生固蔓延，静一资隄防。","督领不无人，提携颇在纲。","荆扬风土暖，肃肃候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢仆，寄语逾崇冈。","西成聚必散，不独陵我仓。","岂要仁里誉，感此乱世忙。","北风吹蒹葭，蟋蟀近中堂。","荏苒百工休，郁纡迟暮伤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.688},{"uid":"ddf67260-7dcb-405a-824e-f11c3c9fea2f","title":"鼓吹曲辞 凯歌六首 六","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["暮雨旌旗湿未干，胡尘白草日光寒。","昨日将军连晓战，蕃军只见马空鞍。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"人生":["战争"]},"theme_conf":1.0},{"uid":"6cc5782f-97e4-4f04-970a-d56618e8edf9","title":"杂曲歌辞 少年行三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["击筑饮美酒，劒歌易水湄。","经过燕太子，结托幷州儿。","少年负壮气，奋烈自有时。","因声鲁句践，争情勿相欺。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"ab812eee-9ec2-43c1-8f1e-98ccbe583ede","title":"郊庙歌辞 禅社首乐章 太和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["昭昭有唐，天俾万国。","列祖应命，四宗顺则。","申锡无疆，宗我同德。","曾孙继序，享神配极。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":1.0},{"uid":"b2898783-b22c-4ded-b6c0-492b879a3b2d","title":"横吹曲辞 出塞","author":"马戴","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金带连环束战袍，马头冲雪度临洮。","卷旗夜劫单于帐，乱斫胡兵缺宝刀。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"0a9b2767-706e-40b9-a423-2097e5f97d10","title":"避暑摩诃池上作","author":"后蜀嗣主孟昶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["冰肌玉骨清无汗，水殿风来暗香暖。","帘开明月独窥人，敧枕钗横云鬓乱。","起来琼户寂无声，时见疎星渡河汉。","屈指西风几时来，只恐流年暗中换。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月","园林"],"cats":{"抒情":["孤独","闺怨"],"四季":["夏天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":1.0},{"uid":"5197293d-6d7e-48f7-9387-f992e9c3a2ee","title":"七月十五日题章敬寺","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["招提迩皇邑，复道连重城。","法筵会早秋，驾言访禅扃。","尝闻大仙教，清净宗无生。","七物匪吾宝，万行先求成。","名相既双寂，繁华奚所荣。","金风扇微凉，远烟凝翠晶。","松院静苔色，竹房深磬声。","境幽真虑恬，道胜外物轻。","意适本非说，含毫空复情。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"ead3046a-4747-487f-a645-2695cd744c3d","title":"杂曲歌辞 长安少年行十首 八","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年高殿上，始见有光辉。","玉鴈排方带，金鹅立仗衣。","酒深和椀赐，马疾打珂飞。","朝下人争看，香街意气归。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"节日":["春节"]},"theme_conf":1.0},{"uid":"e10bd711-4a4e-40e6-85a7-bcec617b61c0","title":"批叶翘谏书纸尾","author":"闽王王继鹏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春色曾看紫陌头，乱红飞尽不禁愁。","人情自厌芳华歇，一叶随风落御沟。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春"],"植物":["叶子"]},"theme_conf":0.67},{"uid":"77659827-473d-4602-9888-f305d9c70273","title":"杂曲歌辞 少年行二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西陵侠年少，送客过长亭。","青槐夹两路，白马如流星。","闻道羽书急，单于寇井陉。","气高轻赴难，谁顾燕山铭。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人生":["青春"]},"theme_conf":0.41},{"uid":"21bf8b8a-d5c1-4146-b572-31d2372a6474","title":"杂曲歌辞 少年行三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["五陵年少金市东，银鞍白马度春风。","落花踏尽游何处？笑入胡姬酒肆中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":1.0},{"uid":"9b51ca3b-92b6-4a73-b382-201a23ac190f","title":"柏学士茅屋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["碧山学士焚银鱼，白马却走身岩居。","古人已用三冬足，年少今开万卷余。","晴云满户团倾盖，秋水浮阶溜决渠。","富贵必从勤苦得，男儿须读五车书。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬","秋"],"cats":{"四季":["秋天","冬天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"0201eede-b035-4751-a5b5-e2bfbdc6caa2","title":"别崔潩因寄薛据孟云卿","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["志士惜妄动，知深难固辞。","如何久磨砺，但取不磷缁。","夙夜听忧主，飞腾急济时。","荆州过薛孟，为报欲论诗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["离别"],"人生":["励志"]},"theme_conf":1.0},{"uid":"56f2dfa5-3d19-4b8f-a6da-8323290985ba","title":"杂诗","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["百花结成子，春物舍我去。","流年惜不得，独坐空闺暮。","心自有所待，甘为物华悮。","未必千黄金，买得一人顾。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"339d2c0a-8297-464b-b37c-4755924c0a56","title":"江行无题一百首 八十七","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["幸有烟波兴，宁辞笔砚劳。","缘情无怨刺，却似反离骚。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"人生":["读书"]},"theme_conf":0.65},{"uid":"cp7755e2bdab1251","title":"解佩环・疏影","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江空不渡，恨蘼芜杜若，零落无数。","远道荒寒，婉娩流年，望望美人迟暮。","风烟雨雪阴晴晚，更何须，春风千树。","尽孤城、落木萧萧，日夜江声流去。","日晏山深闻笛，恐他年流落，与子同赋。","事阔心违，交淡媒劳，蔓草沾衣多露。","汀洲窈窕馀醒寐，遗浮沈沣浦。","有白鸥淡月，微波寄语，逍遥容与。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜"],"cats":{"抒情":["孤独"],"人物":["女子"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.5},{"uid":"3585a5ca-2533-4780-aa25-d7a7484f4d49","title":"拟古三首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽居盼天造，胡息运行机。","春葩妍既荣，秋叶瘁以飞。","滔滔川之逝，日没月光辉。","所贵法干健，于道悟入微。","任彼声势徒，得志方夸毗。"],"theme":"哲理悟道","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"人生":["哲理"]},"theme_conf":0.88},{"uid":"d1f63af2-2b60-4ca1-bbb5-9c0d65cf44df","title":"晚楼寓怀","author":"刘兼","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["薄暮疎林宿鸟还，倚楼垂袂复凭栏。","月沈江底珠轮净，云锁峰头玉叶寒。","刘毅暂贫虽壮志，冯唐将老自低颜。","无言独对秋风立，拟把朝簪换钓竿。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["慷慨"],"scene":["楼"],"cats":{"抒情":["孤独"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"151b748b-c973-46df-9c3a-6ce7a9ab53e0","title":"杂曲歌辞 汉宫少年行","author":"李益","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见上宫警夜营八屯，冬冬街鼓朝朱轩。","玉阶霜仗拥未合，少年排入铜龙门。","暗闻弦管九天上，宫漏沈沈清吹繁。","才明走马绝驰道，呼鹰挟弹通缭垣。","玉笼金琐养黄口，探雏取卵伴王孙。","分曹六博快一掷，迎欢先意笑语喧。","巧为柔媚学优孟，儒衣嬉戏冠沐猨。","晚来香街经柳市，行过倡市宿桃根。","相逢杯酒一言失，回朱点白闻至尊。","金张许史伺颜色，王侯将相莫敢论。","岂知人事无定势，朝欢暮戚如掌翻。","椒房宠移子爱夺，一夕秋风生戾园。","徒用黄金将买赋，宁知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老张丞相，南山如天不可上。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"欢愉","mood2":[],"scene":["夜","酒","秋","冬"],"cats":{"抒情":["闺怨","怀古"],"四季":["秋天","冬天"],"人生":["青春"]},"theme_conf":0.513},{"uid":"629687ee-7e6f-4b7a-8c3d-2034d5e752da","title":"远游联句","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别肠车轮转，一日一万周。","离思春冰泮，澜漫不可收。","驰光忽以迫，飞辔谁能留。","取之讵灼灼，此去信悠悠。","楚客宿江上，夜魂栖浪头。","晓日生远岸，水芳缀孤舟。","村饮泊好木，野蔬拾新柔。","独含凄凄别，中结郁郁愁。","人忆旧行乐，鸟吟新得俦。","灵瑟时窅窅，霠猨夜啾啾。","愤涛气尚盛，恨竹泪空幽。","长怀绝无已，多感良自尤。","即路涉献岁，归期眇凉秋。","两欢日牢落，孤悲坐绸缪。","观怪忽荡漾，叩奇独冥搜。","海鲸吞明月，浪岛没大沤。","我有一寸钩，欲钓千丈流。","良知忽然远，壮志郁无抽。","魍魅暂出没，蛟螭互蟠蟉。","昌言拜舜禹，举颿凌斗牛。","怀糈餽贤屈，乘桴追圣丘。","飘然天外步，岂肯区中囚。","楚些待谁吊，贾辞缄恨投。","翳明弗可晓，秘魂安所求。","气毒放逐域，蓼杂芳菲畴。","当春忽凄凉，不枯亦飕飗。","貉谣众猥款，巴语相咿嚘。","默誓去外俗，嘉愿还中州。","江生行既乐，躬辇自相勠。","饮醇趣明代，味腥谢荒陬。","驰深鼓利檝，趋险惊蜚𬨎。","系石沈靳尚，开弓射𫛝吺。","路暗执屏翳，波惊戮阳侯。","广泛信缥缈，高行恣浮游。","外患萧萧去，中悒稍稍瘳。","振衣造云阙，跪坐陈清猷。","德风变谗巧，仁气销戈矛。","名声照西海，淑问无时休。","归哉孟夫子，归去无夷犹。"],"theme":"送别","theme2":["边塞征战","羁旅思乡","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"愁怨","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.83},{"uid":"a6e5e21e-44a8-4e30-b824-ef6344e9d531","title":"相和歌辞 猛虎行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["朝作猛虎行，暮作猛虎吟。","肠断非关陇头水，泪下不为雍门琴。","旌旗缤纷两河道，战鼓惊山欲倾倒。","秦人半作燕地囚，胡马飜衔洛阳草。","一输一失关下兵，朝降夕叛幽蓟城。","巨鼇未斩海水动，鱼龙奔走安得宁。","颇似楚汉时，飜覆无定止。","朝过博浪沙，暮入淮阴市。","张良未遇韩信贫，刘项存亡在两臣。","暂到下邳受兵略，来投漂母作主人。","贤哲栖栖古如此，今时亦弃青云士。","有策不敢犯龙鳞，窜身南国避胡尘。","宝书长劒挂高阁，金鞍骏马散故人。","昨日方为宣城客，掣铃交通二千石。","有时六博快壮心，绕床三帀呼一掷。","楚人每道张旭奇，心藏风云世莫知。","三吴邦伯多顾盼，四海雄侠皆相推。","萧曹曾作沛中吏，攀龙附凤当有时。","溧阳酒楼三月春，杨花漠漠愁杀人。","胡人绿眼吹玉笛，吴歌白纻飞梁尘。","丈夫相见且为乐，槌牛挝鼓会众宾。","我从此去钓东海，得鱼笑寄情相亲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":["欢愉","慷慨"],"scene":["楼","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":0.41},{"uid":"d171c992-eedc-4dda-9f9d-4b4088ff29df","title":"宿山中僧","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["不𦶟香炉烟，蒲团坐如铁。","尝想同夜禅，风堕松顶雪。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬","雪","夜"],"cats":{"人生":["哲理"]},"theme_conf":0.86},{"uid":"15274300-bd45-4898-ab14-9a3dead4b620","title":"送僧归日本","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上国随缘住，来途若梦行。","浮天沧海远，去世法舟轻。","水月通禅观，鱼龙听梵声。","惟怜一灯影，万里眼中明。"],"theme":"送别","theme2":["哲理悟道"],"style":"豪放","style2":["旷达"],"mood":"惆怅","mood2":[],"scene":["舟","月","江"],"cats":{"人生":["哲理"]},"theme_conf":0.498},{"uid":"b86dfe06-639c-446e-ac96-298a1403d16e","title":"同群公秋登琴台","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古迹使人感，琴台空寂寥。","静然顾遗尘，千载如昨朝。","临眺自兹始，群贤久相邀。","德与形神高，孰知天地遥。","四时何倏忽，六月鸣秋蜩。","万象归白帝，平川横赤霄。","犹是对夏伏，几时有凉飙。","燕雀满簷楹，鸿鹄抟扶摇。","物性各自得，我心在渔樵。","兀然还复醉，尚握尊中瓢。"],"theme":"咏史怀古","theme2":["闲适隐逸","山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.408},{"uid":"bcf6124b-d0ca-48b1-9b9a-c62824a7d759","title":"严氏溪放歌行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天下甲马未尽销，岂免沟壑常漂漂。","劒南岁月不可度，边头公卿仍独骄。","费心姑息是一役，肥肉大酒徒相要。","呜呼古人已粪土，独觉志士甘渔樵。","况我飘转无定所，终日慽慽忍羁旅。","秋宿霜溪素月高，喜得与子长夜语。","东游西还力实倦，从此将身更何许。","知子松根长茯苓，迟暮有有意来同煮。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["秋","夜","月","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.529},{"uid":"0a988f56-b22d-48cb-94f1-fc75e2532eab","title":"长相思","author":"刘复","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长相思，在桂林，苍梧山远潇湘深。","秋堂零泪倚金瑟，朱颜摇落随光阴。","长宵嘹唳鸿命侣，河汉苍苍隔牛女。","宁知一水不可渡，况复万山修且阻。","彩丝织绮文双鸳，昔时赠君君可怜。","何言一去瓶落井，流尘歇灭金炉前。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约","雄浑"],"mood":"相思","mood2":[],"scene":["七夕","秋","山"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人生":["时光"],"节日":["七夕节"]},"theme_conf":0.705},{"uid":"232b2330-be81-492f-ab96-52be310cd64d","title":"杂曲歌辞 少年乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["芳草落花如锦地，二十长游醉乡里。","红缨不重白马骄，垂柳金丝香拂水。","吴娥未笑花不开，绿鬓耸堕兰云起。","陆郎倚醉牵罗袂，夺得宝钗金翡翠。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"e80bca1f-12ef-4187-b623-b614aa6bee78","title":"寄李十二白二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年有狂客，号尔谪仙人。","笔落惊风雨，诗成泣鬼神。","声名从此大，汩没一朝伸。","文彩承殊渥，流传必绝伦。","龙舟移櫂晚，兽锦夺袍新。","白日来深殿，青云满后尘。","乞归优诏许，遇我宿心亲。","未负幽栖志，兼全宠辱身。","剧谈怜野逸，嗜酒见天真。","醉舞梁园夜，行歌泗水春。","才高心不展，道屈善无邻。","处士祢衡俊，诸生原宪贫。","稻粱求未足，薏苡谤何频。","五岭炎蒸地，三危放逐臣。","几年遭𫛳鸟，独泣向麒麟。","苏武先还汉，黄公岂事秦。","楚筵辞醴日，梁狱上书辰。","已用当时法，谁将此义陈。","老吟秋月下，病起暮江滨。","莫怪恩波隔，乘槎与问津。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","雨","端午","舟","春","秋"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人生":["梦想"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"9322a025-9168-4abc-a815-1d4a235cee67","title":"相和歌辞 襄阳曲二首 一","author":"崔国辅","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["蕙草娇红蕚，时光舞碧鸡。","城中美年少，相见白铜鞮。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人生":["时光"]},"theme_conf":0.7},{"uid":"c0f1c8ed-bbf8-4ace-ac86-91e5e57d8ece","title":"鼓吹曲辞 战城南","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["去年战桑干源，今年战葱河道。","洗兵条支海上波，放马天山雪中草。","万里长征战，三军尽衰老。","匈奴以杀戮为耕作，古来唯见白骨黄沙田。","秦家筑城备胡处，汉家还有烽火然。","烽火然不息，征战无已时。","野战格鬬死，败马号鸣向天悲。","乌鸢啄人肠，衔飞上挂枯树枝。","士卒涂草莽，将军空尔为。","乃知兵者是凶器，圣人不得已而用之。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":0.753},{"uid":"24eec460-2dda-41a7-8104-e590096f3e03","title":"相和歌辞 长歌行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["桃李得日开，荣华照当年。","东风动百物，草木尽欲言。","枯枝无丑叶，涸水吐清泉。","大力运天地，羲和无停鞭。","功名不早著，竹帛将何宣？","桃李务青春，谁能贯白日。","富贵与神仙，蹉跎成两失。","金石犹销铄，风霜无久质。","畏落日月后，强欢歌与酒。","秋霜不惜人，倏忽侵蒲柳。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"天气":["太阳"],"人生":["青春"]},"theme_conf":1.0},{"uid":"e475a182-9775-4dcb-9087-4abb71fc6476","title":"杂曲歌辞 少年子","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青云少年子，挟弹章台左。","鞍马四边开，突如流星过。","金丸落飞鸟，夜入琼楼卧。","夷齐是何人？独守西山饿。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","夜"],"cats":{"抒情":["孤独"],"人生":["青春"]},"theme_conf":1.0},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"a3c6b2bf-35cf-40dc-bbcf-cfb5efa9f82e","title":"送褚大落第东归","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["离琴弹苦调，美人惨向隅。","顷来荷策干明主，还复扁舟归五湖。","汉家侧席明扬久，岂意遗贤在林薮。","玉堂金马隔青云，墨客儒生皆白首。","昨梦芳洲采白苹，归期且喜故园春。","稚子只思陶令至，文君不厌马卿贫。","剡中风月久相忆，池上旧游应再得。","酒熟宁孤芳杜春，诗成不枉青山色。","念此那能不羡归，长杨谏猎事皆违。","他日东流一乘兴，知君为我扫荆扉。"],"theme":"送别","theme2":["羁旅思乡"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":["欢愉","孤寂"],"scene":["舟","园林","江","春"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["春天"],"人物":["女子","儿童"],"人生":["梦想"]},"theme_conf":0.361},{"uid":"1f4dfb15-6a50-428f-8ce8-121b853cce12","title":"送柳判官赴振武","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["边庭汉仪重，旌甲似云中。","虏地山川壮，单于鼓角雄。","关寒塞榆落，月白胡天风。","君逐嫖姚将，麒麟有战功。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["塞外","月","园林","山"],"cats":{"人生":["战争"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"a8ad6062-6360-4804-8a85-e123e41c7058","title":"上元日梦王母献白玉环","author":"张佐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梦中朝上日，阙下拜天颜。","仿佛瞻王母，分明献玉环。","灵姿趋甲帐，悟道契玄关。","似见霜姿白，如看月彩弯。","霓裳归物外，凤历晓人寰。","仙圣非相远，昭昭寤寐间。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"人生":["梦想"],"节日":["春节","元宵节"]},"theme_conf":0.97},{"uid":"cpe8a61267f2054a","title":"定风波","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["自春来、惨绿愁红，芳心是事可可。","日上花梢，莺穿柳带，犹压香衾卧。","暖酥消，腻云。","终日厌厌倦梳裹。","无那。","恨薄情一去，音书无个。","早知恁么。","悔当初、不把雕鞍锁。","向鸡窗、只与蛮笺象管，拘束教吟课。","镇相随，莫抛躲。","针线闲拈伴伊坐。","和我。","免使年少，光阴虚过。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"bbe30e55-8238-495c-bcf9-8144fe363439","title":"自淇涉黄河途中作十三首 六","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日登滑台，台高秋已暮。","独行既未惬，怀土怅无趣。","晋宋何萧条，羌胡散驰骛。","当时无战略，此地即边戍。","兵革徒自勤，山河孰云固。","乘闲喜临眺，感物伤游寓。","惆怅落日前，飘飖远帆处。","北风吹万里，南雁不知数。","归意方浩然，云沙更廻互。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["孤寂","欢愉"],"scene":["江","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河","黄河"],"人生":["战争"]},"theme_conf":1.0},{"uid":"d0788381-649d-4d28-814f-f448f3cfef9a","title":"咏大慈寺斋头鲜于阇梨","author":"陈裕","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["酒肉终朝没阙时，高堂大舍养肥尸。","行婆满院多为妇，童子成行半是儿。","面折掇斋穷措大，笑迎搽粉阿尼师。","一朝若也无常至，剑树刀山不放伊。"],"theme":"哲理悟道","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","园林","山"],"cats":{"人生":["哲理"],"植物":["梨花"]},"theme_conf":0.507},{"uid":"3e58f1b4-21c8-4f73-a641-cc0366ab1efd","title":"寄上兵部韩侍郎奉呈李户部卢刑部杜三侍郎","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["道路五千里，门阑三十年。","当时携手人，今日无半全。","咏题官舍内，赋韵僧房前。","公登略彴桥，况榜龙{舟卬}船。","远寺吐朱阁，春潮浮绿烟。","鹓鸿翔邓林，沙鸨飞吴田。","诸子纷出祖，中宵久留连。","坐客三千人，皆称主人贤。","国士分如此，家臣亦依然。","身在薜萝中，头刺文案边。","故吏已重叠，门生从联翩。","得罪为何名，无阶问皇天。","出门多岐路，命驾无由缘。","伏承诸侍郎，顾念犹迍邅。","圣代逢三宥，营魂空九迁。"],"theme":"应制干谒","theme2":["应制干谒","哲理悟道"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"人物":["老师"],"人生":["战争"],"生活":["写桥"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"8c70f0e2-8df5-42da-975b-927f7093a3d0","title":"灵岩寺","author":"薛令之","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["草堂栖在灵山谷，勤苦诗书向灯烛。","柴门半掩寂无人，惟有白云相伴宿。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.521},{"uid":"dcb153ef-db2d-4222-b72e-f762b9f6ef6d","title":"拟古三首 三","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["颓光无淹晷，逝水有迅流。","绿苔纷易歇，红颜不再求。","歌笑当及春，无令壮志秋。","弱年仕关辅，簃门豁御沟。","敷愉东城际，婉娈南陌头。","荷花娇绿水，杨叶暖青楼。","中有绮罗人，可怜名莫愁。","画屏绕金膝，珠帘悬玉钩。","纤指调宝琴，泠泠哀且柔。","赠君鸳鸯带，因以鹔鹴裘。","窗晓吟日坐，闺夕秉烛游。","无作北门客，咄咄怀百忧。"],"theme":"咏怀抒感","theme2":["悼亡挽歌","送别","山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","秋"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天","秋天"],"人生":["励志","梦想"]},"theme_conf":0.7},{"uid":"c698e805-b9af-4674-9526-4cfe5df6217c","title":"资圣寺贲法师晚春茶会","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虚室昼常掩，心源知悟空。","禅庭一雨后，莲界万花中。","时节流芳暮，人天此会同。","不知方便理，何路出樊笼。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花"],"cats":{"四季":["春天"],"人生":["哲理"],"食物":["写茶"]},"theme_conf":0.96},{"uid":"130ff9df-d0d9-4812-8ae2-cba09ed87050","title":"岁暮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁暮远为客，边隅还用兵。","烟尘犯雪岭，鼓角动江城。","天地日流血，朝廷谁请缨。","济时敢爱死，寂寞壮心惊。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["雪","江"],"cats":{"抒情":["孤独","爱国"],"人生":["战争"]},"theme_conf":0.776},{"uid":"3c19217c-7f07-45f9-b317-3744725dc11c","title":"郊庙歌辞 禅社首乐章 福和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["穆穆天子，告成岱宗。","大裘如濡，执珽有颙。","乐以平志，礼以和容。","上帝临我，云胡肃邕。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"人生":["哲理"]},"theme_conf":0.692},{"uid":"06bd32a2-f9f5-4bfe-a55e-fadd67afc789","title":"相和歌辞 饮马长城窟行","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄迹未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["相思","悲怆"],"scene":[],"cats":{"抒情":["思念","思乡","伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.631},{"uid":"ad596df7-559f-4f97-81d3-7cba94b371c5","title":"杂曲歌辞 相府莲","author":"不详","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["夜闻邻妇泣，切切有余哀。","即问缘何事，征人战未回。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"人生":["战争"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"7c1f0ae4-dada-485d-a817-cc932bb685d7","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 六","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹如晕，更复（京本作「或」）似弓形。","有若白虹形断续，兼之五六见城营，皆主血光成（京本作「生」。","京本注：「或见五六月」）。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"f76dcec1-ab9d-432e-a10c-da58ae8ad0b1","title":"送窦九归成都","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["文章亦不尽，窦子才纵横。","非尔更苦节，何人符大名。","读书云阁观，问绢锦官城。","我有浣花竹，题诗须一行。"],"theme":"送别","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"人生":["读书"]},"theme_conf":1.0},{"uid":"3ab356ea-69fc-43ff-b74c-4ece4a0b8277","title":"杂曲歌辞 长安少年行十首 一","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["金紫少年郎，绕街鞍马光。","身从左中尉，官属右春坊。","刬戴扬州帽，重熏异国香。","垂鞭踏青草，来去杏园芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["清明","花","春","园林"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"8522b687-c845-4d15-9e44-b60c3df77707","title":"元日喜闻大礼寄上翰林四学士中书六舍人二十韵","author":"窦牟","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有事郊坛毕，无私日月临。","岁华春更早，天瑞雪犹深。","玉辇回时令，金门降德音。","翰飞鸳别侣，藂植桂为林。","粉泽资鸿笔，薰和本素琴。","礼成戎器下，恩彻鬼方沈。","麟爵来称纪，官师退绝箴。","道风黄阁静，祥景紫垣阴。","寿酒朝时献，农书夜直寻。","国香煴翠幄，庭燎赩红衾。","汉魏文章盛，尧汤雨露霃。","密辞投水石，精义出沙金。","宸扆亲唯敬，钧衡近匪侵。","疾驱千里骏，清唳九霄禽。","庆赐迎新服，斋庄弃旧簪。","忽思班女怨，遥听越人吟。","末路甘贫病，流年苦滞淫。","梦中青琐闼，归处碧山岑。","窃抃闻韶濩，观光想韎任。","大哉环海晏，不笇子牟心。"],"theme":"应制干谒","theme2":["送别","山水田园"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"愁怨","mood2":["欢愉","相思"],"scene":["雪","月","夜","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.86},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"67cea0fa-4c7b-456a-ae5d-574d1dc8a878","title":"晚投江泽浦即事呈柳兵曹泥","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日过重霞，轻烟上远沙。","移舟冲荇蔓，转浦入芦花。","断岸迂来客，连波漾去槎。","故乡何处在，更道向天涯。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡"],"人生":["战争"],"植物":["柳树"]},"theme_conf":0.719},{"uid":"1168c377-42c2-4c1f-a283-1ba089165dab","title":"秋日荆南述怀三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔承推奖分，媿匪挺生材。","迟暮宫臣忝，艰危衮职陪。","扬镳随日驭，折槛出云台。","罪戾宽犹活，干戈塞未开。","星霜玄鸟变，身世白驹催。","伏枕因超忽，扁舟任往来。","九钻巴噀火，三蛰楚祠雷。","望帝传应实，昭王问不回。","蛟螭深作横，豺虎乱雄猜。","素业行已矣，浮名安在哉？","琴乌曲怨愤，庭鹤舞摧颓。","秋雨漫湘水，阴风过岭梅。","苦摇求食尾，常曝报恩顋。","结舌防谗柄，探肠有祸胎。","苍茫步兵哭，展转仲宣哀。","饥籍家家米，愁征处处杯。","休为贫士叹，任受众人咍。","得丧初难识，荣枯划易该。","差池分组冕，合沓起蒿莱。","不必伊周地，皆知屈宋才。","汉庭和异域，晋史坼中台。","霸业寻常体，忠臣忌讳灾。","群公纷戮力，圣虑窅裴回。","数见铭钟鼎，真宜法斗魁。","愿闻锋镝铸，莫使栋梁摧。","盘石圭多翦，凶门毂少推。","垂旒资穆穆，祝网但恢恢。","赤雀飜然至，黄龙讵假媒。","贤非梦傅野，隐类凿颜坯。","自古江湖客，冥心苦死灰。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏史怀古","讽喻刺世"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","园林","舟"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"人生":["时光","战争"]},"theme_conf":0.95},{"uid":"160c5168-d55c-4a4c-ba73-ae1596f4b900","title":"杂曲歌辞 行路难三首 三","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见少年头上如云发，少壮如云老如雪。","岂知灌顶有醍醐，能使清凉头不热。","吕梁之水挂飞流，鼋鼍蛟蜃不敢游。","少年恃险若平地，独倚长劒凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"],"人生":["青春"]},"theme_conf":0.65},{"uid":"fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"theme":"咏史怀古","theme2":["哲理悟道","边塞征战","羁旅思乡"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["秋","江"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.242},{"uid":"72fc17eb-8b81-4de1-b38e-eb035f412a2b","title":"横吹曲辞 后出塞五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["男儿生世间，及壮当封侯。","战伐有功业，焉能守旧丘。","召募赴蓟门，军动不可留。","千金买马鞭，百金装刀头。","闾里送我行，亲戚拥道周。","斑白居上列，酒酣进庶羞。","少年别有赠，含笑看吴钩。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.615},{"uid":"4506e47c-d89b-45ca-a9c5-8f9c457409b6","title":"奉酬睢阳李太守","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["公族称王佐，朝经允帝求。","本枝疆我李，盘石冠诸刘。","礼乐光辉盛，山河气象幽。","系高周柱史，名重晋阳秋。","华省膺推择，青云宠宴游。","握兰多具美，前席有嘉谋。","赋得黄金赐，言皆白璧酬。","着鞭驱驷马，操刃解全牛。","出镇兼方伯，承家复列侯。","朝瞻孔北海，时用杜荆州。","广固才登陟，毘陵忽阻修。","三台冀入梦，四岳尚分忧。","郡邑连京口，山川望石头。","海门当建节，江路引鸣驺。","俗见中兴理，人逢至道休。","先移白额横，更息赭衣偷。","梁国歌来晚，徐方怨不留。","岂伊齐政术，将以变浇浮。","讼简知能吏，刑宽察要囚。","坐堂风偃草，行县雨随辀。","地是蒙庄宅，城遗阏伯丘。","孝王余井径，微子故田畴。","冬至招摇转，天寒䗖𬟽收。","猿岩飞雨雪，兔苑落梧楸。","列戟霜侵户，褰帏月在钩。","好贤常解榻，乘兴每登楼。","逸足横千里，高谈注九流。","诗题青玉案，衣赠黑貂裘。","穷巷轩车静，闲斋耳目愁。","未能方管乐，翻欲慕巢由。","讲德良难敌，观风岂易俦。","寸心仍有适，江海一扁舟。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["楼","舟","冬","山","秋"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"d1c29cbc-5e59-4332-8a20-033c7524e3d0","title":"杂曲歌辞 少年行三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见淮南少年游侠客，白日毬猎夜拥掷。","呼卢百万终不惜，报讐千里如咫尺。","少年游侠好经过，浑身装束皆绮罗。","兰蕙相随喧妓女，风光去处满笙歌。","骄矜自言不可有，侠士堂中养来久。","好鞍好马乞与人，十千五千旋沽酒。","赤心用尽为知己，黄金不惜栽桃李。","桃李栽来几度春，一回花落一回新。","府县尽为门下客，王侯皆是平交人。","男儿百年且乐命，何须徇书受贫病。","男儿百年且荣身，何须徇节甘风尘。","衣冠半是征战士，穷儒浪作林泉民。","遮莫枝根长百丈，不如当代多还往。","遮莫姻亲连帝城，不如当身自簪缨。","看取富贵眼前者，何用悠悠身后名。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["友情","思乡"],"四季":["春天"],"人生":["青春","战争"]},"theme_conf":0.441},{"uid":"47c36bbc-9c5d-474e-a665-96380be371b7","title":"言行相顾","author":"吴叔达","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣人垂政教，万古请常传。","立志言为本，修身行乃先。","相须宁得阙，相顾在无偏。","荣辱当于己，忠贞必动天。","大名如副宝，至道亦通玄。","千里犹能应，何云迩者焉。"],"theme":"羁旅思乡","theme2":[],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["励志"]},"theme_conf":0.65},{"uid":"9fcb6791-4b0f-4a32-84f9-fbebc30dd9c5","title":"问正上人疾","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["医王犹有疾，妙理竞难穷。","饵药应随病，观身转悟空。","地闲花欲雨，窗冷竹生风。","几日东林去，门人待远公。"],"theme":"哲理悟道","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.377},{"uid":"18970206-4b28-4c5e-974f-a9ef44cbc9a7","title":"得山中道友书寄苗銭二员外","author":"李端","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["有谋皆𫐘轲，非病亦迟回。","壮志年年减，驰晖日日催。","还山不及伴，到阙又无媒。","高卧成长策，微官称下才。","诗人识何谢，居士别宗雷。","迹向尘中隐，书从谷口来。","药栏遭鹿践，涧户被猿开。","野鹤巢云窦，游龟上水苔。","新欢追易失，故思渺难裁。","自有归期在，劳君示劫灰。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["友情"],"人生":["励志","梦想"]},"theme_conf":0.88},{"uid":"888e21ea-f3bc-4453-83b8-2048410e3b91","title":"杂曲歌辞 蓟门行","author":"李希仲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旄头有精芒，胡骑猎秋草。","羽檄南渡河，边庭用兵早。","汉家爱征战，宿将今已老。","辛苦羽林儿，从戎榆关道。","一身救边速，烽火连蓟门。","前军鸟飞断，格鬬尘沙昏。","寒日鼓声急，单于夜火奔。","当须徇忠义，身死报国恩。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["爱国"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.864},{"uid":"8aec2246-5d1e-4a0d-87f5-69d4ec66321f","title":"山居即事","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下泊降茅仙，萧闲隐洞天。","杨君闲上法，司命驻流年。","崦合桃花水，窗分柳谷烟。","抱孙堪种树，倚杖问耘田。","世事休相扰，浮名任一边。","由来谢安石，不解饮灵泉。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人生":["时光"]},"theme_conf":0.467},{"uid":"d5d66aff-b6ae-48cc-9160-16b096d4ea49","title":"老将行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["少年十五二十时，步行夺得胡马射。","射杀中山白额虎，肯数邺下黄须儿。","一身转战三千里，一劒曾当百万师。","汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。","衞青不败由天幸，李广无功缘数奇。","自从弃置便衰朽，世事磋跎成白首。","昔时飞箭无全目，今日垂杨生左肘。","路傍时卖故侯瓜，门前学种先生柳。","苍茫古木连穷巷，寥落寒山对虚牖。","誓令疏勒出飞泉，不似颍川空使酒。","贺兰山下阵如云，羽檄交驰日夕闻。","节使三河募年少，诏书五道出将军。","试拂铁衣如雪色，聊持宝劒动星文。","愿得燕弓射天将，耻令越甲鸣吴军。","莫嫌旧日云中守，犹堪一战取功勋。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["冲淡","幽峭"],"mood":"慷慨","mood2":["孤寂"],"scene":["江南","雪","山","酒"],"cats":{"人生":["战争"]},"theme_conf":0.857},{"uid":"9d974ae6-2223-4fa3-bb66-15a079adec68","title":"送孔巢父赴河南军","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江城相送阻烟波，况复新秋一雁过。","闻道全师征北虏，更言诸将会南河。","边心杳杳乡人绝，塞草青青战马多。","共许陈琳工奏记，知君名宦未蹉跎。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","塞外","秋"],"cats":{"四季":["秋天"],"山水":["江河"],"人物":["父亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"65d1fa84-153c-4a45-95da-f90cb66f36a5","title":"寄禅师寺华上人次韵三首 三","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["德士名难避，风流学济颠。","礼罗加璧至，荐鹗与云连。","尘世休飞锡，松林且枕泉。","近闻离讲席，听雨半山眠。"],"theme":"哲理悟道","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","山"],"cats":{"人物":["老师"],"人生":["哲理"]},"theme_conf":0.524},{"uid":"6382d668-2787-4a30-b0f2-c58a3b3b9f25","title":"相和歌辞 从军行","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["向夕临大荒，朔风轸归虑。","平沙万里余，飞鸟宿何处？","虏骑猎长原，翩翩傍河去。","边声摇白草，海气生黄雾。","百战苦风尘，十年履霜露。","虽投定远笔，未坐将军树。","早知行路难，悔不理章句。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["写风"],"人生":["战争"]},"theme_conf":0.854},{"uid":"bea6f283-8f90-49b5-8842-1cb906816548","title":"古从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里无城郭，雨雪纷纷连大漠。","胡鴈哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲桃入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.765},{"uid":"473617e8-f2d2-4f2a-a26d-df696f3c9890","title":"题藏公院","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古院林公住，疎篁近井桃。","俗年人见少，禅地自知高。","药草诚多喻，沧溟在一毫。","仍悲次宗辈，尘事日为劳。"],"theme":"佛道禅颂","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"212bf433-f47a-4f05-84d1-172804896869","title":"三川观水涨二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我经华原来，不复见平陆。","北上唯土山，连山走穷谷。","火云无时出，飞电常在目。","自多穷岫雨，行潦相豗蹙。","蓊匌川气黄，群流会空曲。","清晨望高浪，忽谓阴崖踣。","恐泥窜蛟龙，登危聚麋鹿。","枯查卷拔树，礧磈共充塞。","声吹鬼神下，势阅人代速。","不有万穴归，何以尊四渎。","及观泉源涨，反惧江海覆。","漂沙坼岸去，漱壑松柏秃。","乘陵破山门，回斡裂地轴。","交洛赴洪河，及关岂信宿。","应沈数州没，如听万室哭。","秽浊殊未清，风涛怒犹蓄。","何时通舟车，阴气不黪黩。","浮生有荡汨，吾道正羁束。","人寰难容身，石壁滑侧足。","云雷此不已，艰险路更跼。","普天无川梁，欲济愿水缩。","因悲中林士，未脱众鱼腹。","举头向苍天，安得骑鸿鹄。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["雄浑"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.579},{"uid":"f40cb6c3-66e9-4a83-a497-124d085ed298","title":"杂曲歌辞 缓歌行","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["小来托身攀贵游，倾财破产无所忧。","暮拟经过石渠署，朝将出入铜龙楼。","结交杜陵轻薄子，谓言可生复可死。","一沈一浮会有时，弃我翻然如脱屣。","男儿立身须自彊，十五闭户颍水阳。","业就功成见明主，击钟鼎食坐华堂。","二八蛾眉梳堕马，美酒清歌曲房下。","文昌宫中赐锦衣，长安陌上退朝归。","五侯宾从莫敢视，三省官僚揖者稀。","早知今日读书是，悔作从来任侠非。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":1.0},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"0ed53ef4-30ca-41ac-a629-d778e5cc2bfa","title":"相和歌辞 从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野营万里无城郭，雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲萄入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.748},{"uid":"4d6d713f-e241-4cc9-b332-733225339044","title":"平胡","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杂虏忽猖狂，无何敢乱常。","羽书朝继入，烽火夜相望。","将出凶门勇，兵因死地强。","蒙轮皆突骑，按劒尽鹰扬。","鼓角雄山野，龙蛇入战场。","流膏润沙漠，溅血染锋铓。","雾扫清玄塞，云开静朔方。","武功今已立，文德愧前王。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":["恬淡"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"5bc37c7b-af6e-4a86-9d48-c558c25293a8","title":"墙阴歌","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["白日左右浮天潢，朝晡影入东西墙。","昔为儿童在阴戏，当时意小觉日长。","东邻侯家吹笙簧，随阴促促移象床。","西邻田舍乏糟糠，就影汲汲舂黄粱。","因思九州四海外，家家只占墙阴内。","莫言墙阴数尺间，老却主人如等闲。","君看眼前光阴促，中心莫学太行山。"],"theme":"哲理悟道","theme2":[],"style":"豪放","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["儿童"],"人生":["时光"]},"theme_conf":0.86},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"cp1eb7d5610773cc","title":"水龙吟","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚天千里清秋，水随天去秋无际。","遥岑远目，献愁供恨，玉簪螺髻。","落日楼头，断鸿声里，江南游子。","把吴钩看了，栏干拍遍，无人会、登临意。","休说鲈鱼堪。","尽西风、季鹰归未。","求田问舍，怕应羞见，刘郎才气。","可惜流年，忧愁风雨，树犹如此。","倩何人，唤取盈盈翠袖，英雄泪。"],"theme":"闺情宫怨","theme2":["亲情"],"style":"婉约","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":["江南","秋","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.588},{"uid":"edc07822-6fcc-44f0-836f-956c0ad2d4e8","title":"进秋隼","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岂悟因罗者，迎霜献紫微。","夕阳分素臆，秋色上花衣。","举翅云天近，回眸燕雀稀。","应随明主意，百中有光辉。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":1.0},{"uid":"78f6ebbf-396a-4980-bbf1-0c14d80d384d","title":"二灵寺守岁","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["守岁山房迥绝缘，灯光香灺共萧然。","无人更献椒花颂，有客同参栢子禅。","已悟化城非乐界，不知今夕是何年。","忧心悄悄浑忘寐，坐待扶桑日丽天。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["除夕"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["春节"]},"theme_conf":0.76},{"uid":"cp157df1f3a98fb8","title":"夜游宫","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["叶下斜阳照水。","卷轻浪、沈沈千里。","桥上酸风射眸子。","立多时，看黄昏，灯火市。","古屋寒窗底。","听几片、井桐飞坠。","不恋单衾再三起。","有谁知，为萧娘，书一纸。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人生":["读书"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"63c586ff-dfa2-4c4e-88fe-4f017c9b52bb","title":"酬翰林白学士代书一百韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔岁俱充赋，同年遇有司。","八人称迥拔，两郡滥相知。","逸骥初翻步，鞲鹰暂脱羁。","远途忧地窄，高视觉天卑。","并入红兰署，偏亲白玉规。","近朱怜冉冉，伐木愿偲偲。","鱼鲁非难识，铅黄自嬾持。","心轻马融帐，谋夺子房帷。","秀发幽岩电，清澄隘岸陂。","九霄排直上，万里整前期。","勇赠栖鸾句，慙当古井诗。","多闻全受益，择善颇相师。","脱俗殊常调，潜工大有为。","还醇凭酎酒，运智托围棋。","情会招车胤，闲行觅戴逵。","僧餐月灯阁，醵宴劫灰池。","胜概争先到，篇章竞出奇。","输赢论破的，点窜肯容丝。","山岫当街翠，墙花拂面枝。","莺声爱娇小，燕翼玩逶迤。","辔为逢车缓，鞭缘趂伴施。","密携长上乐，偷宿静坊姬。","僻性慵朝起，新晴助晚嬉。","相欢常满目，别处鲜开眉。","翰墨题名尽，光阴听话移。","绿袍因醉典，乌帽逆风遗。","暗插轻筹箸，仍提小屈巵。","本弦才一举，下口已三迟。","逃席冲门出，归倡借马骑。","狂歌繁节乱，醉舞半衫垂。","散漫纷长薄，邀遮守隘岐。","几遭朝士笑，兼任巷童随。","苟务形骸达，浑将性命[推]。","何曾爱官序，不省计家资。","忽悟成虚掷，翻然叹未宜。","使回躭乐事，坚赴策贤时。","寝食都忘倦，园庐遂绝闚。","劳神甘戚戚，攻短过孜孜。","叶怯穿杨箭，囊藏透颕锥。","超遥望云雨，摆落占泉坻。","略削荒凉苑，搜求激直词。","那能作牛后，更拟助洪基。","唱第听鸡集，趋朝忘马疲。","内人舆御案，朝景丽神旗。","首被呼名姓，多慙冠等衰。","千官容眷盼，五色照离披。","鹓侣从兹洽，鸥情转自縻。","分张殊品命，中外却驱驰。","出入称金籍，东西侍碧墀。","鬬班云汹涌，开扇雉参差。","切愧寻常质，亲瞻咫尺姿。","日轮光照耀，龙服瑞葳蕤。","誓欲通愚謇，生憎效喔咿。","佞存真妾妇，谏死是男儿。","便殿承偏召，权臣惧挠私。","庙堂虽稷契，城社有狐貍。","似锦言应巧，如弦数易欺。","敢嗟身暂黜，所恨政无毗。","谬辱良由此，升腾亦在斯。","再令陪宪禁，依旧履阽危。","使蜀常緜远，分台更崄巇。","匿奸劳发掘，破党恶持疑。","斧刃迎皆碎，盘牙老未萎。","乍能还帝笏，讵忍折吾支。","虎尾元来险，圭文却类疵。","浮荣齐壤芥，闲气咏江蓠。","阙下殷勤拜，樽前啸傲辞。","飘沈委蓬梗，忠信敌蛮夷。","戏诮青云驿，讥题皓发祠。","贪过谷隐寺，留读岘山碑。","草没章台阯，隄横楚泽湄。","野莲侵稻陇，亚柳压城陴。","遇物伤凋换，登楼思漫弥。","金攒嫩橙子，瑿泛远鸬鹚。","仰竹藤缠屋，苫茆荻补篱。","面梨通蔕朽，火米带芒炊。","苇笋针筒束，𫚣鱼箭羽鬐。","芋羹真底可，鲈鲙漫劳思。","北渚销魂望，南风著骨吹。","度梅衣色渍，食稗马蹄羸。","院榷和泥碱，官酤小曲醨。","讹音烦缴绕，轻俗丑威仪。","树罕贞心柏，畦丰卫足葵。","坳洼饶尰矮，游惰压庸缁。","病赛乌称鬼，巫占瓦代龟。","连阴蛙张王，瘴疟雪治医。","我正穷于是，君宁念及兹。","一篇从日下，双鲤送天涯。","坐捧迷前席，行吟忘结綦。","匡床铺错绣，几案踊灵芝。","形影同初合，参商喻此离。","扇因秋弃置，镜异月盈亏。","壮志诚难夺，良辰岂复追。","宁牛终夜永，潘鬓去年衰。","溟渤深那测，穹苍意在谁。","驭方轻騕褭，车肯重辛夷。","卧辙希濡沫，低颜受颔颐。","世情焉足怪，自省固堪悲。","溷鼠虚求洁，笼禽方讶饥。","犹胜忆黄犬，幸得早图之。"],"theme":"寄赠酬答","theme2":["山水田园","闲适隐逸"],"style":"绮丽","style2":["清新","豪放"],"mood":"欢愉","mood2":["愁怨","慷慨"],"scene":["酒","山","楼","园林","夜"],"cats":{"抒情":["离别","伤感"],"人生":["励志","时光","梦想"]},"theme_conf":0.95},{"uid":"252b4e33-b8d1-462d-a8e9-55a9766df5cf","title":"送惠师","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惠师浮屠者，乃是不羇人。","十五爱山水，超然谢朋亲。","脱冠翦头发，飞步遗踪尘。","发迹入四明，梯空上秋旻。","遂登天台望，众壑皆嶙峋。","夜宿最高顶，举头看星辰。","光芒相照烛，南北争罗陈。","兹地绝翔走，自然严且神。","微风吹木石，澎湃闻韶钧。","夜半起下视，溟波衔日轮。","鱼龙惊踊跃，呌啸成悲辛。","怪气或紫赤，敲磨共轮囷。","金鸦既腾翥，六合俄清新。","常闻禹穴奇，东去窥瓯闽。","越俗不好古，流传失其真。","幽踪邈难得，圣路嗟长堙。","回临浙江涛，屹起高峨岷。","壮志死不息，千年如隔晨。","是非竟何有，弃去非吾伦。","凌江诣庐岳，浩荡极游巡。","崔崒没云表，陂陀浸湖沦。","是时雨初霁，悬瀑垂天绅。","前年往罗浮，步戛南海漘。","大哉阳德盛，荣茂恒留春。","鹏𬸣堕长翮，鲸戏侧修鳞。","自来连州寺，曾未造城𬮱。","日携青云客，探胜穷崖滨。","太守邀不去，群官请徒频。","囊无一金资，翻谓富者贫。","昨日忽不见，我令访其隣。","奔波自追及，把手问所因。","顾我却兴欢，君宁异于民。","离合自古然，辞别安足珍。","吾闻九疑好，夙志今欲伸。","斑竹啼舜妇，清湘沈楚臣。","衡山与洞庭，此固道所循。","寻崧方抵洛，历华遂之秦。","浮游靡定处，偶往即通津。","吾言子当去，子道非吾遵。","江鱼不池活，野鸟难笼驯。","吾非西方教，怜子狂且醇。","吾嫉惰游者，怜子愚且谆。","去矣各异趣，何为浪沾巾。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭","豪放"],"mood":"悲怆","mood2":["慷慨","欢愉"],"scene":["江","山"],"cats":{"抒情":["离别","伤感"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.619},{"uid":"c012d2aa-e678-491c-aa1d-d201ed7d6e2a","title":"寄李白","author":"任华","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古来文章有能奔逸气，耸高格。","清人心神，惊人魂魄。","我闻当今有李白，大猎赋，鸿猷文，嗤长卿，笑子云。","班张所作琐细不入耳，未知卿云得在嗤笑限。","登庐山，观瀑布，海风吹不断，江月照还空。","余爱此两句：登天台，望渤海云垂大鹏飞，山压巨鳌背，斯言亦好在。","至于他作多不拘常律，振摆超腾，既俊且逸。","或醉中操纸，或兴来走笔。","手下忽然片云飞，眼前划见孤峰出。","而我有时白日忽欲睡，睡觉歘然起攘臂。","任生知有君，君也知有任生未。","中间闻道在长安，及余戾止。","君已江东访元丹，邂逅不得见君面。","每常把酒，向东望良久。","见说往年在翰林，胸中矛戟何森森。","新诗传在宫人口，佳句不离明主心。","身骑天马多意气，目送飞鸿对豪贵。","承恩召入凡几回，待诏归来仍半醉。","权臣妬盛名，群犬多吠声。","有勅放君却归隐沦处，高歌大笑出关去。","且向东山为外臣，诸侯交迓驰朱轮。","白璧一双买交者，黄金百镒相知人。","平生傲岸其志不可测，数十年为客，未尝一日低颜色。","八咏楼中坦腹眠，五侯门下无心忆。","繁花越台上，细柳吴宫侧。","绿水青山知有君，白云明月偏相识。","养高兼养闲，可望不可攀。","庄周万物外，范蠡五湖间。","人传访道沧海上，丁令王乔每往还。","蓬莱径是曾到来，方丈岂唯方一丈。","伊余每欲乘兴往相寻，江湖拥隔劳寸心。","今朝忽遇东飞翼，寄此一章表胸臆。","傥能报我一片言，但访任华有人识。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新","旷达"],"mood":"恬淡","mood2":["欢愉","慷慨"],"scene":["山","江","月","酒"],"cats":{"山水":["庐山","瀑布"],"天气":["写云","月亮"],"人生":["哲理","梦想"]},"theme_conf":0.95},{"uid":"9ca5eb72-69e6-47f0-a27d-06034645217d","title":"酬裴员外以诗代书","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少时方浩荡，遇物犹尘埃。","脱略身外事，交游天下才。","单车入燕赵，独立心悠哉。","宁知戎马间，忽展平生怀。","且欣清论高，岂顾夕阳颓。","题诗碣石馆，纵酒燕王台。","北望沙漠垂，漫天雪皑皑。","临边无策略，览古空裴回。","乐毅吾所怜，拔齐翻见猜。","荆卿吾所悲，适秦不复廻。","然诺多死地，公忠成祸胎。","与君从此辞，每恐流年催。","如何俱老大，始复忘形骸。","兄弟真二陆，声名连八裴。","乙未将星变，贼臣候天灾。","胡骑犯龙山，乘舆经马嵬。","千官无倚着，万姓徒悲哀。","诛吕鬼神动，安刘天地开。","奔波走风尘，倏忽值云雷。","拥旄出淮甸，入幕征楚材。","誓当剪鲸鲵，永以竭驽骀。","小人胡不仁，谗我成死灰。","赖得日月明，照耀无不该。","留司洛阳宫，詹府唯蒿莱。","是时扫氛祲，尚未歼渠魁。","背河列长围，师老将亦乖。","归军剧风火，散卒争椎埋。","一夕瀍洛空，生灵悲曝腮。","衣冠投草莽，予欲驰江淮。","登顿宛叶下，栖遑襄邓隈。","城池何萧条，邑屋更崩摧。","纵横荆棘丛，但见瓦砾堆。","行人无血色，战骨多青苔。","遂除彭门守，因得朝玉阶。","激昂仰鹓鹭，献替欣盐梅。","驱传及远蕃，忧思郁难排。","罢人纷争讼，赋税如山崖。","所思在畿甸，曾是鲁宓侪。","自从拜郎官，列宿焕天街。","那能访遐僻，还复寄琼瓌。","金玉本高价，埙箎终易谐。","朗咏临清秋，凉风下庭槐。","何意寇盗间，独称名义偕。","辛酸陈侯诔，叹息季鹰杯。","白日屡分手，青春不再来。","卧看中散论，愁忆太常斋。","酬赠徒为尔，长歌还自咍。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨","豪放"],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["酒","雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"人生":["青春","时光","战争"]},"theme_conf":0.94},{"uid":"0222bb09-1f03-473b-b3d7-bd41709a2643","title":"朱陈村","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["徐州古丰县，有村曰朱陈。","去县百余里，桑麻青氛氲。","机梭声札札，牛驴走纭纭。","女汲涧中水，男采山上薪。","县远官事少，山深人俗淳。","有财不行商，有丁不入军。","家家守村业，头白不出门。","生为村之民，死为村之尘。","田中老与幼，相见何欣欣。","一村唯两姓，世世为婚姻。","亲疎居有族，少长游有群。","黄鸡与白酒，欢会不隔旬。","生者不远别，嫁娶先近邻。","死者不远葬，坟墓多绕村。","既安生与死，不苦形与神。","所以多寿考，往往见玄孙。","我生礼义乡，少小孤且贫。","徒学辨是非，祗自取辛勤。","世法贵名教，士人重冠婚。","以此自桎梏，信为大谬人。","十岁解读书，十五能属文。","二十举秀才，三十为谏臣。","下有妻子累，上有君亲恩。","承家与事国，望此不肖身。","忆昨旅游初，迨今十五春。","孤舟三适楚，羸马四经秦。","昼行有饥色，夜寝无安魂。","东西不暂住，来往若浮云。","离乱失故乡，骨肉多散分。","江南与江北，各有平生亲。","平生终日别，逝者隔年闻。","朝忧卧至暮，夕哭坐达晨。","悲火烧心曲，愁霜侵鬓根。","一生苦如此，长羡村中民。"],"theme":"山水田园","theme2":["羁旅思乡","悼亡挽歌"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思乡","伤感","悼亡"],"人物":["老师"],"人生":["读书"],"生活":["乡村","田野"]},"theme_conf":0.301},{"uid":"8ac1fb39-17d3-4dae-b046-94dfd282aa77","title":"相和歌辞 善哉行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["大鹏刷翮谢溟渤，青云万层高突出。","下视秋涛空渺弥，旧处鱼龙皆细物。","人生在世何容易，眼浊心昏信生死。","愿除嗜欲待身轻，携手同寻列仙事。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.65},{"uid":"c680a907-39d1-4968-b638-3bdb6c97eb9b","title":"相和歌辞 燕歌行","author":"陶翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["请君留楚调，听我吟燕歌。","家在辽水头，边风意气多。","出身为汉将，正值戎未和。","雪中凌天山，冰上渡交河。","大小百余战，封侯竟蹉跎。","归来霸陵下，故旧无相过。","雄劒委尘匣，空门唯雀罗。","玉𥮾还赵女，宝瑟付齐娥。"],"theme":"边塞征战","theme2":["羁旅思乡","哲理悟道"],"style":"清新","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡"],"人生":["战争"],"动物":["写鸟"]},"theme_conf":0.403},{"uid":"a4c287ae-d6f5-414a-a05b-f69d7baff4a0","title":"水阁朝霁奉简严云安","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城抱春岑，江阁邻石面。","崔嵬晨云白，朝旭射芳甸。","雨槛卧花丛，风床展书卷。","钩帘宿鹭起，丸药流莺啭。","呼婢取酒壶，绩儿诵文选。","晚交严明府，矧此数相见。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","酒"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["读书"]},"theme_conf":0.9},{"uid":"1558a170-9f05-4a1a-b907-b9f6061f4772","title":"饯济阴梁明府各探一物得荷叶","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荷叶生幽渚，芳华信在兹。","朝朝空此地，采采欲因谁。","但恐星霜改，还将蒲稗衰。","怀君美人别，聊以赠心期。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人物":["女子"],"人生":["青春"],"植物":["荷花","叶子"]},"theme_conf":0.799},{"uid":"53e02f22-5213-4ef0-8258-451dfe9d5052","title":"江州赴忠州至江陵已来舟中示舍弟五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔作咸秦客，常思江海行。","今来仍尽室，此去又专城。","典午犹为幸，分忧固是荣。","箳篂州乘送，艛艓驿船迎。","共载皆妻子，同游即弟兄。","宁辞浪迹远，且贵赏心幷。","云展帆高挂，飙驰櫂迅征。","溯流从汉浦，循路转荆衡。","山逐时移色，江随地改名。","风光近东早，水木向南清。","夏口烟孤起，湘川雨半晴。","日煎红浪沸，月射白砂明。","北渚寒留雁，南枝暖待莺。","骈朱桃露萼，点翠柳含萌。","亥市鱼盐聚，神林鼓笛鸣。","壶浆椒叶气，歌曲竹枝声。","系缆怜沙静，垂纶爱岸平。","水飡红粒稻，野茹紫花菁。","瓯泛茶如乳，台黏酒似饧。","脍长抽锦缕，藕脆削琼英。","容易来千里，斯须进一程。","未曾劳气力，渐觉有心情。","卧稳添春睡，行迟带酒酲。","忽愁牵世网，便欲濯尘缨。","早接文场战，曾争翰苑盟。","掉头称俊造，翘足取公卿。","且昧随时义，徒输报国诚。","众排恩易失，偏压势先倾。","虎尾忧危切，鸿毛性命轻。","烛蛾谁救活，蚕茧自缠萦。","歛手辞双阙，回眸望两京。","长沙抛贾谊，漳浦卧刘桢。","𫛸鴂鸣还歇，蟾蜍破又盈。","年光同激箭，乡思极摇旌。","潦倒亲知笑，衰羸旧识惊。","乌头因感白，鱼尾为劳頳。","劒学将何用，丹烧竟不成。","孤舟萍一叶，双鬓雪千茎。","老见人情尽，闲思物理精。","如汤探冷热，似博鬬输赢。","险路应须避，迷途莫共争。","此心知止足，何物要经营。","玉向泥中洁，松经雪后贞。","无妨隐朝市，不必谢寰瀛。","但在前非悟，期无后患婴。","多知非景福，少语是元亨。","晦即全身药，明为伐性兵。","昏昏随世俗，蠢蠢学黎甿。","鸟以能言{构木=糸}，龟缘入梦烹。","知之一何晚，犹足保余生。"],"theme":"亲情","theme2":["山水田园","闲适隐逸"],"style":"沉郁","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":["慷慨","恬淡"],"scene":["舟","江"],"cats":{"抒情":["伤感","爱国"],"山水":["江河"],"人生":["战争"]},"theme_conf":0.85},{"uid":"17cc0659-dfef-47e7-a538-bd689b2b8c2b","title":"题邵公禅院","author":"刘得仁","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无事门多掩，阴阶竹扫苔。","劲风吹雪聚，渴鸟啄冰开。","树向寒山得，人从瀑布来。","终期天目老，擎锡逐云回。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","冬","雪"],"cats":{"山水":["瀑布"],"人生":["哲理"]},"theme_conf":0.63},{"uid":"4b20b87c-18e6-4769-b07e-72665771fd11","title":"相和歌辞 饮马长城窟行","author":"袁朗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动秋草，清跸长安道。","长城连不穷，所以隔华戎。","规模惟圣作，荷负晓成功。","鸟庭已向内，龙荒更凿空。","玉关尘卷静，金微路已通。","汤征随北怨，舜咏起南风。","画野功初立，绥边事云集。","朝服践狼居，凯歌旋马邑。","山响传凤吹，霜华藻琼钑。","属国拥节归，单于款关入。","日落寒云起，惊沙被原隰。","零落叶已寒，河流清且急。","四时徭役尽，千载干戈戢。","太平今若斯，汗马竟无施。","惟当事笔研，归去草封禅。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.522},{"uid":"fae577a5-da28-4672-83ff-94c97ae2a4a4","title":"晚次鄂州","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["云开远见汉阳城，犹是孤帆一日程。","估客昼眠知浪静，舟人夜语觉潮生。","三湘衰鬓逢秋色，万里归心对月明。","旧业已随征战尽，更堪江上鼓鼙声。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":["恬淡"],"scene":["舟","江","夜"],"cats":{"抒情":["思乡","孤独"],"人生":["战争"]},"theme_conf":0.412},{"uid":"c480c5e2-1052-4bdc-9fca-44d38c5a2fda","title":"相和歌辞 从军行二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百战沙场碎铁衣，城南已合数重围。","突营射杀呼延将，独领残兵千骑归。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.909},{"uid":"b2883592-eaf5-47a2-bd3d-7ded35fda71a","title":"谢友生遗端溪砚瓦","author":"李咸用","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["寻常濡翰次，恨不到端溪。","得自新知己，如逢旧解携。","玩余轻照乘，谢欲等悬黎。","静对胜凡客，闲窥忆好题。","娲天补剩石，昆剑切来泥。","著指痕犹湿，停旬水未低。","呵云润柱础，笔彩饮虹霓。","鹆眼工谙谬，羊肝士乍刲。","连澌光比镜，囚墨腻于䃜。","书信成池黑，吟须到日西。","正夸忧盗窃，将隐怯攀跻。","捧受同交印，矜持过秉珪。","草颠终近旭，嬾癖必无嵇。","用合缘鹦鹉，珍应负会稽。","贞姿还落落，寒韵或凄凄。","风月情相半，烟花思岂迷。","宜从方袋挈，枉把短行批。","浅小金为斗，泓澄玉作堤。","遇人依我惜，想尔与天齐。","□□□□□，行时秪独赍。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":["恬淡"],"scene":[],"cats":{"抒情":["友情","感恩"],"天气":["彩虹"],"人生":["读书"]},"theme_conf":0.748},{"uid":"5849dc58-0b5b-4181-ad61-285eb6ca25f5","title":"秋思","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋室浩烟雾，风柳怨寒蜩。","机杼夜声切，蕙兰芳意消。","美人湘水曲，桂檝洞庭遥。","常恐时光谢，蹉跎红艳凋。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["女子"],"人生":["时光"]},"theme_conf":1.0},{"uid":"a349dddb-7734-4ba3-a1c9-4bc836bb2ca3","title":"南塘二首 二","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["塘东白日驻红雾，早鱼翻光落碧浔。","画舟兰棹欲破浪，恐畏惊动莲花心。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["舟"],"cats":{"人生":["励志"]},"theme_conf":0.9},{"uid":"8aa6132d-c61e-4218-af24-5d9009e6795d","title":"春日书情寄元校书伯和相国元子","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["数岁平津邸，诸生出门时。","羇孤力行早，疎贱托身迟。","芳草看无厌，青山到未期。","贫居悲老大，春日上茅茨。","卫玠琼瑶色，玄成鼎鼐姿。","友朋汉相府，兄弟谢家诗。","律合声虽应，劳歌调自悲。","流年不可住，惆怅镜中丝。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.88},{"uid":"ccf1691d-8325-4d04-9eda-9d8608216ba7","title":"周平西墓","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["英威今寂寞，陈迹对崇丘。","壮志清风在，荒坟白日愁。","穷泉那复晓，乔木不知秋。","岁岁寒塘侧，无人水自流。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","冬"],"cats":{"抒情":["孤独","怀古"],"四季":["秋天","冬天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"16aeb267-54a8-4c49-9d94-3306022db14d","title":"东兵长句十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上党争为天下脊，邯郸四十万秦坑。","狂童何者欲专地，圣主无私岂玩兵。","玄象森罗摇北落，诗人章句咏东征。","雄如马武皆弹劒，少似终军亦请缨。","屈指庙堂无失策，垂衣尧舜待升平。","羽林东下雷霆怒，楚甲南来组练明。","即墨龙文光照曜，常山蛇阵势纵横。","落雕都尉万人敌，黑矟将军一鸟轻。","渐见长围云欲合，可怜穷垒带犹萦。","凯歌应是新年唱，便逐春风浩浩声。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"],"人生":["战争"],"节日":["春节"]},"theme_conf":1.0},{"uid":"451fc40e-4dad-47ec-88e7-bb54fbc6bb60","title":"东平留赠狄司马","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人无宿诺，兹道以为难。","万里赴知己，一言诚可叹。","马蹄经月窟，劒术指楼兰。","地出北庭尽，城临西海寒。","森然瞻武库，则是弄儒翰。","入幕绾银绶，乘轺兼铁冠。","练兵日精锐，杀敌无遗残。","献捷见天子，论功俘可汗。","激昂丹墀下，顾盼青云端。","谁谓纵横策，翻为权势干。","将军既坎𡒄，使者亦辛酸。","耿介挹三事，羇离从一官。","知君不得意，他日会鹏抟。"],"theme":"寄赠酬答","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["友情"],"人生":["梦想"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.86},{"uid":"ee595e38-1cc8-4833-bcae-8bea127dcd6f","title":"南溪始泛三首 一","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["榜舟南山下，上上不得返。","幽事随去多，孰能量近远。","阴沈过连树，藏昂抵横坂。","石麤肆磨砺，波恶厌牵挽。","或倚偏岸渔，竟就平洲饭。","点点暮雨飘，梢梢新月偃。","余年懔无几，休日怆已晚。","自是病使然，非由取高蹇。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","雨","月"],"cats":{"人生":["励志"]},"theme_conf":0.728},{"uid":"cp896ca043fc2d77","title":"次韵苏如圭乞猫","author":"周紫芝","dynasty":"宋","section":"宋诗","form":"五言古诗","paragraphs":["苏侯家四壁，每饭歌权舆。","庾郎鲑菜盘，三韭罗春蔬。","饥鼠窜旁舍，不复劳驱除。","何为走老黥，贯鱼乞狸奴。","颇知红锦囊，万卷家多书。","我时醉着帽，过子城南居。","手擎乌丝栏，棐几自卷舒。","寒具久不设，趸尾亦足娱。","犹恐遭咬啮，备豫须不虞。","狸奴当努力，鼠辈勤诛锄。","无为幸一饱，高卧依寒垆。"],"theme":"民生疾苦","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["江南","春"],"cats":{"四季":["春天"],"人生":["读书"],"动物":["写猫"]},"theme_conf":1.0},{"uid":"382c265b-130c-43b1-b500-f49215b85f2e","title":"岭南江行","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["瘴江南去入云烟，望尽黄茆是海边。","山腹雨晴添象迹，潭心日暖长蛟涎。","射工巧伺游人影，飓母偏惊旅客船。","从此忧来非一事，岂容华髪待流年。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["愁怨"],"scene":["江","山","江南"],"cats":{"抒情":["思乡"],"山水":["江河"],"人生":["时光"]},"theme_conf":0.531},{"uid":"d7890db1-28cc-4cc4-b81a-90b6f9d68568","title":"酬乐天早春闲游西湖颇多野趣恨不得与微之同赏因思在越官重事殷镜湖之游或恐未暇因成十八韵见寄乐天前篇到时适会予亦宴镜湖南亭因述目前所睹以成酬荅末章亦示暇诚则势使之然亦欲粗为恬养之赠耳","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雁思欲回宾，风声乍变新。","各携红粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳条黄大带，茭葑绿文茵。","雪尽才通屐，汀寒未有苹。","向阳偏晒羽，依岸小游鳞。","浦屿崎岖到，林园次第巡。","墨池怜嗜学，丹井羡登真。","雅叹游方盛，聊非意所亲。","白头辞北阙，沧海是东邻。","问俗烦江界，搜畋想渭津。","故交音讯少，归梦往来频。","独喜同门旧，皆为列郡臣。","三刀连地轴，一苇碍车轮。","尚阻青天雾，空瞻白玉尘。","龙因雕字识，犬为送书驯。","胜事无穷境，流年有限身。","嬾将闲气力，争鬬野塘春。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["恬淡"],"scene":["江","江南","春"],"cats":{"四季":["春天"],"山水":["西湖"],"人生":["时光"]},"theme_conf":0.9},{"uid":"0167687e-8325-48bf-8da4-3749c9ce0a74","title":"横吹曲辞 关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"1b9b8047-2410-47ae-a24c-aad7342b338f","title":"石鼓歌","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["张生手持石鼓文，劝我试作石鼓歌。","少陵无人谪仙死，才薄将奈石鼓何。","周纲陵迟四海沸，宣王愤起挥天戈。","大开明堂受朝贺，诸侯劒佩鸣相磨。","搜于岐阳骋雄俊，万里禽兽皆遮罗。","镌功勒成告万世，凿石作鼓隳嵯峨。","从臣才艺咸第一，拣选撰刻留山阿。","雨淋日炙野火燎，鬼物守护烦㧑呵。","公从何处得纸本，毫发尽备无差讹。","辞严义密读难晓，字体不类隶与科。","年深岂免有缺画，快劒斫断生蛟鼍。","鸾翔凤翥众僊下，珊瑚碧树交枝柯。","金绳铁索锁纽壮，古鼎跃水龙腾梭。","陋儒编诗不收入，二雅褊迫无委蛇。","孔子西行不到秦，掎摭星宿遗羲娥。","嗟予好古生苦晚，对此涕泪双滂沱。","忆昔初蒙博士徴，其年始改称元和。","故人从军在右辅，为我度量掘臼科。","濯冠沐浴告祭酒，如此至宝存岂多。","氊包席裹可立致，十鼓祗载数骆驼。","荐诸太庙比郜鼎，光价岂止百倍过。","圣恩若许留太学，诸生讲解得切磋。","观经鸿都尚填咽，坐见举国来奔波。","剜苔剔藓露节角，安置妥帖平不颇。","大厦深簷与盖覆，经历久远期无佗。","中朝大官老于事，讵肯感激徒媕婀。","牧童敲火牛砺角，谁复著手为摩挲。","日销月铄就埋没，六年西顾空吟哦。","羲之俗书趁姿媚，数纸尚可博白鹅。","继周八代争战罢，无人收拾理则那。","方今太平日无事，柄任儒术崇丘轲。","安能以此上论列，愿借辨口如悬河。","石鼓之歌止于此，呜呼吾意其蹉跎。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.562},{"uid":"b9811b91-7522-46d2-ae55-63d63968adca","title":"自淇涉黄河途中作十三首 十二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝景入平川，川长复垂柳。","遥看魏公墓，突兀前山后。","忆昔大业时，群雄角奔走。","伊人何电迈，独立风尘首。","传檄举敖仓，拥兵屯洛口。","连营一百万，六合如可有。","方项终比肩，乱隋将假手。","力争固难恃，骄战曷能久。","若使学萧曹，功名当不朽。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["孤独","悼亡"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.552},{"uid":"9d8d3ee1-81f4-4938-8797-5dcd5be1f720","title":"李云南征蛮诗","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["圣人赫斯怒，诏伐西南戎。","肃穆庙堂上，深沈节制雄。","遂令感激士，得建非常功。","料死不料敌，顾恩宁顾终。","鼓行天海外，转战蛮夷中。","梯𪩘近高鸟，穿林经毒虫。","鬼门无归客，北户多南风。","蜂虿隔万里，云雷随九攻。","长驱大浪破，急击群山空。","饷道忽已远，悬军垂欲穷。","精诚动白日，愤薄连苍穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地弥西东。","临事耻苟免，履危能饬躬。","将星独照耀，边色何溟蒙。","泸水夜可涉，交州今始通。","归来长安道，召见甘泉宫。","廉蔺若未死，孙吴知暗同。","相逢论意气，慷慨谢深衷。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨","悲怆"],"scene":[],"cats":{"抒情":["孤独"],"天气":["写云"],"人生":["战争"]},"theme_conf":0.589},{"uid":"8a2266dd-ed4e-4168-8464-ec32d966daaa","title":"校猎义成喜逢大雪率题九韵以示群官","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["弧矢威天下，旌旗游近县。","一面施鸟罗，三驱教人战。","暮云成积雪，晓色开行殿。","皓然原隰同，不觉林野变。","北风勇士马，东日华组练。","触地银麞出，连山缟鹿见。","月兔落高矰，星狼下急箭。","既欣盈尺兆，复忆磻谿便。","岁丰将遇贤，俱荷皇天眷。"],"theme":"边塞征战","theme2":["边塞征战","咏物","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雪"],"cats":{"天气":["写雪"],"人生":["战争"]},"theme_conf":0.55},{"uid":"70adc79e-eace-4cd8-a20e-1e8b609ab8eb","title":"杂曲歌辞 少年行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["少年从出猎长杨，禁中新拜羽林郎。","独到辇前射双虎，君王手赐黄金铛。","日日鬬鸡都市里，赢得宝刀重刻字。","百里报讐夜出城，平明还在倡楼醉。","遥闻虏到平陵下，不待诏书行上马。","斩得名王献桂宫，封侯起第一日中。","不为六郡良家子，百战始取边城功。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","楼"],"cats":{"抒情":["思乡","孤独"],"人生":["青春","战争"]},"theme_conf":0.613},{"uid":"c53ae26b-4d36-4eaa-9ff4-004c922bee79","title":"梦寻西山准上人","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["别处秋泉声，至今犹在耳。","何尝梦魂去，不见雪山子。","新月隔林时，千峰翠微里。","言忘心更寂，迹灭云自起。","觉来缨上尘，如洗功德水。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"人生":["梦想"]},"theme_conf":0.561},{"uid":"862104e5-cfeb-4843-9e5f-8bdff6294563","title":"感春","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["看花泪尽知春尽，魂断看花秪恨春。","名位未沾身欲老，诗书宁救眼前贫。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"12cabe5b-f212-401c-bcd7-fc940a5870b6","title":"立春后休沐","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["心与青春背，新年亦掩扉。","渐穷无相学，惟避不材讥。","积病攻难愈，衔恩报转微。","定知书课日，优诏许辞归。"],"theme":"咏怀抒感","theme2":[],"style":"旷达","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["春节"]},"theme_conf":0.78},{"uid":"f85f5813-4fa8-4ce8-be2d-a6664da153ee","title":"鼓吹曲辞 战城南","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["城南征战多，城北无饥鵶。","白骨马蹄下，谁言皆有家。","城前水声苦，倏忽流万古。","莫争城外地，城里有闲土。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["雄浑"],"mood":"悲怆","mood2":["恬淡"],"scene":[],"cats":{"人生":["战争"]},"theme_conf":0.673},{"uid":"c48a91ea-6d94-42d1-8466-f5a9f42cc1d6","title":"送兵到蓟北","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["积雪与天迥，屯军连塞愁。","谁知此行迈，不为觅封侯。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.529},{"uid":"c620865d-0ff1-4861-9847-114e33be2f18","title":"青云干吕 一","author":"彭伉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["祥辉上干吕，郁郁又纷纷。","远示无为化，将明至道君。","势凝千里静，色向九霄分。","已见从龙意，宁知触石文。","状烟殊散漫，捧日更氛氲。","自使来宾国，西瞻仰瑞云。"],"theme":"应制干谒","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":[],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"cf0bd1f5-19cd-4465-944c-b1eda8c18787","title":"送任先生任唐山丞","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["再命果良愿，几年勤说诗。","上公频握发，才子共垂帷。","琢玉成良器，出门偏怆离。","腰章佐墨绶，耀锦到茅茨。","树老见家日，潮平归县时。","衣催莲女织，颂听海人词。","鸿鹄志应在，荃兰香未衰。","金门定回音，云路有佳期。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"人生":["梦想"]},"theme_conf":0.659},{"uid":"cp3bf43d6100f34f","title":"满江红","author":"岳飞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怒发冲冠，凭阑处、潇潇雨歇。","抬望眼、仰天长啸，壮怀激烈。","三十功名尘与土，八千里路云和月。","莫等闲、白了少年头，空悲切。","靖康耻，犹未雪。","臣子恨，何时灭。","驾长车踏破，贺兰山缺。","壮志饥餐胡虏肉，笑谈渴饮匈奴血。","待从头、收拾旧山河，朝天阙。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"豪放","style2":["沉郁","悲慨"],"mood":"慷慨","mood2":[],"scene":["雨","江","雪"],"cats":{"抒情":["爱国"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.542},{"uid":"0f7ccc3d-418a-4e51-a5c5-5e22c163b042","title":"刘禅奴弹琵琶歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["乐府只传横吹好，琵琶写出关山道。","羁雁出塞绕黄云，边马仰天嘶白草。","明妃愁中汉使回，蔡琰愁处胡笳哀。","鬼神知妙欲收响，阴风切切四面来。","李陵寄书别苏武，自有生人无此苦。","当时若值霍骠姚，灭尽乌孙夺公主。"],"theme":"题画咏艺","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["哲理"]},"theme_conf":0.397},{"uid":"89799bab-6157-4af8-a292-46807a9ed427","title":"春日即事二首 一","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["诗书成志业，嬾慢致蹉跎。","圣代丹霄远，明时白发多。","浅谋堪自笑，穷巷忆谁过。","寂寞前山暮，归人樵采歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["春"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"888fd3d3-d777-401d-8b4a-e94d3ab3607f","title":"横吹曲辞 入塞曲 二","author":"沈彬","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦战沙间卧箭痕，戍楼闲上望星文。","生希国泽分偏将，死夺河源荅圣君。","鸢覰败兵眠白草，马惊边鬼哭阴云。","功多地远无人纪，汉阁笙歌日又曛。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外","楼"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.877},{"uid":"0a0f9231-d88c-4f81-b941-83b67a736194","title":"长恨歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["夜","楼","山","春","秋","园林"],"cats":{"抒情":["爱情","伤感","孤独","闺怨","感恩"],"四季":["春天","秋天"],"天气":["写雨","星星"],"人物":["老师"],"人生":["梦想"]},"theme_conf":0.85},{"uid":"ffed3e70-8753-466c-ac59-0fdb5894adfd","title":"奉和皇甫大夫夏日游花严寺","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["初第华严会，王家少长行。","到宫龙节驻，礼塔雁行成。","莲界千峰静，梅天一雨清。","禅庭未可恋，圣主寄苍生。"],"theme":"应制干谒","theme2":["哲理悟道"],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.93},{"uid":"cc0d85da-2fc0-4cd0-9163-b23561e07541","title":"横吹曲辞 陇头吟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长安少年游侠客，夜上戍楼看太白。","陇头明月迥临关，陇上行人夜吹笛。","关西老将不胜愁，驻马听之双泪流。","身经大小百余战，麾下偏裨万户侯。","苏武才为典属国，节旄空尽海西头。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人生":["战争"]},"theme_conf":1.0},{"uid":"3db87bc4-ae57-42bb-8741-bb8c8a8499ee","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 二","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兵行次，虹贯日（京本作「路」）边傍。","御（京本作「预」）备伏兵前有阻，且须审细自（京本作「更」）商量，移寨避灾殃（辛本、川本、京本作「终不得开疆」）。","。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"8981911c-da27-4a25-bffb-a8cc1aa7cdfa","title":"舞曲歌辞 独漉篇","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["独漉水中泥，水浊不见月。","不见月尚可，水深行人没。","越鸟从南来，胡鹰亦北度。","我欲弯弓向天射，惜其中道失归路。","落叶别树，飘零随风。","客无所托，悲与此同。","罗帷舒卷，似有人开。","明月直入，无心可猜。","雄劒挂壁，时时龙鸣。","不断犀象，绣涩苔生。","国耻未雪，何由成名。","神鹰梦泽，不顾鸱鸢。","为君一击，抟鹏九天。"],"theme":"边塞征战","theme2":["羁旅思乡","送别"],"style":"悲慨","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"070d66a9-c9a0-44a3-be22-af612fac4861","title":"自澧浦东游江表途出巴丘投员外从公虞","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["短翮后飞者，前攀鸾鹤翔。","力微应万里，矫首空苍苍。","谁昔探花源，考槃西岳阳。","高风动商洛，绮皓无馨香。","一朝下蒲轮，清辉照岩廊。","孤醒立众醉，古道何由昌。","经术震浮荡，国风扫齐梁。","文襟即玄圃，笔下成琳琅。","霞水散吟啸，松筠奉琴觞。","冰壶避皎洁，武库羞锋铓。","小子书代耕，束发颇自强。","艰哉水投石，壮志空摧藏。","十年侣龟鱼，垂头在沅湘。","巴歌揜白雪，鲍肆埋兰芳。","骚雅道未丧，何忧名不彰。","饥寒束困厄，默塞飞星霜。","百志不成一，东波掷年光。","尘生脱粟甑，万里违高堂。","中夜恨火来，焚烧九回肠。","平明梁山泪，缘枕沾匡床。","依泊洞庭波，木叶忽已黄。","哀碪捣秋色，晓月啼寒螀。","复此櫂孤舟，云涛浩茫茫。","朱门待媒势，短褐谁揄扬。","仰羡野陂凫，无心忧稻粱。","不如天边雁，南北皆成行。","男儿白日间，变化未可量。","所希困辱地，剪拂成腾骧。","咋笔话肝肺，咏兹枯鱼章。","何由首西路，目断白云乡。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","酒","月","花","秋","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.367},{"uid":"6ac98d23-849c-4cdc-9c66-72fc3d6c87c7","title":"长门怨","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧爱柏梁台，新宠昭阳殿。","守分辞芳辇，含情泣团扇。","一朝歌舞荣，夙昔诗书贱。","颓恩诚已矣，覆水难重荐。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["闺怨"],"人生":["读书"]},"theme_conf":1.0},{"uid":"2b563a63-b88a-4af9-99f8-d1840f235ce9","title":"赠岑郎中","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["童年未解读书时，诵得郎中数首诗。","四海烟尘犹隔阔，十年魂梦每相随。","虽披云雾逢迎疾，已恨趋风拜德迟。","天下无人鉴诗句，不寻诗伯重寻谁。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.92},{"uid":"d129dc0f-cec9-4073-bb89-cb9312564d9d","title":"轮台歌奉送封大夫出师西征","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["轮台城头夜吹角，轮台城北旄头落。","羽书昨夜过渠黎，单于已在金山西。","戍楼西望烟尘黑，汉兵屯在轮台北。","上将拥旄西出征，平明吹笛大军行。","四边伐鼓雪海涌，三军大呼阴山动。","虏塞兵气连云屯，战场白骨缠草根。","劒河风急雪片阔，沙口石冻马蹄脱。","亚相勤王甘苦辛，誓将报主静边尘。","古来青史谁不见，今见功名胜古人。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"慷慨","mood2":["恬淡"],"scene":["楼"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.762},{"uid":"c5953a86-c1c2-432a-8e73-cfb2ab364071","title":"题道虔上人竹房","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["诗思禅心共竹闲，任他流水向人间。","手持如意高窓里，斜日沿江千万山。"],"theme":"佛道禅颂","theme2":["咏物","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"人生":["哲理"],"植物":["竹子"]},"theme_conf":0.78},{"uid":"0f875d13-f28a-4fb6-8770-c599af4c1909","title":"郊庙歌辞 享章怀太子庙乐章 送文舞迎武舞","author":"不详","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["羽籥崇文礼以毕，干𬭭奋武事将行。","用舍繇来其有致，壮志宣威乐太平。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"66f48ee1-6f1b-4a05-89ae-c904f70ac9b7","title":"杂曲歌辞 少年行四首 四","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一身能臂两雕弧，虏骑千群只似无。","偏坐金鞍调白羽，纷纷射杀五单于。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"人生":["青春"]},"theme_conf":1.0},{"uid":"b54ccce5-156f-4067-8408-a1d8a0d4c180","title":"奉赠萧二十使君","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["惜在严公幕，俱为蜀使臣。","艰危参大府，前后间清尘。","起草鸣先路，乘槎动要津。","王凫聊暂出，萧雉只相驯。","终始任安义，荒芜孟母邻。","联翩匍匐礼，意气死生亲。","张老存家事，嵇康有故人。","食恩慙卤莽，镂骨抱酸辛。","巢许山林志，夔龙廊庙珍。","鹏图乃矫翼，熊轼且移轮。","磊落衣冠地，苍茫土木身。","埙篪鸣自合，金石莹逾新。","重忆罗江外，同游锦水滨。","结欢随过隙，怀旧益沾巾。","旷绝含香舍，稽留伏枕辰。","停骖双阙早，回雁五湖春。","不达长卿病，从来原宪贫。","监河受贷粟，一起辙中鳞。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":["绮丽","旷达"],"mood":"慷慨","mood2":["欢愉"],"scene":["江","春"],"cats":{"抒情":["友情"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.86},{"uid":"f9d02cdb-7dc0-436a-a758-e29b65bb461b","title":"杂曲歌辞 妾薄命","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["薄命妇，良家子，无事从军去万里。","汉家天子平四夷，护羌都尉裹尸归。","念君此行为死别，对君裁缝泉下衣。","与君一日为夫妇，千年万岁亦相守。","君爱龙城征战功，妾愿青楼欢乐同。","人生各各有所欲，讵得将心入君腹。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["闺怨","悼亡"],"人生":["战争"]},"theme_conf":0.409},{"uid":"ef4d4ca2-59ea-4c84-b360-b63252700998","title":"同吉中孚梦桃源 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春雨夜不散，梦中山亦阴。","云中碧潭水，路暗红花林。","花水自深浅，无人知古今。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["花","春","雨","夜","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人生":["梦想"],"植物":["桃花"]},"theme_conf":0.784},{"uid":"de37c5eb-9420-4c1d-a0a8-e9d9a5a118ca","title":"杂曲歌辞 少年行","author":"韦庄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["五陵豪客多，买酒黄金贱。","醉下酒家楼，美人双翠幰。","挥劒邯郸市，走马梁王苑。","乐事殊未央，年华已云晚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["青春"]},"theme_conf":0.654},{"uid":"3c480b6c-f2a8-4726-8cdd-1e4c8c54f2d7","title":"哭灵一上人","author":"严维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一公何不住，空有远公名。","共说岑山路，今时不可行。","旧房松更老，新塔草初生。","经论传缁侣，文章遍墨卿。","禅林枝干折，法宇栋梁倾。","谁复修僧史，应知传已成。"],"theme":"悼亡挽歌","theme2":["哲理悟道"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["悼亡"],"人生":["哲理"]},"theme_conf":0.97},{"uid":"8eeb3273-d271-4674-900b-2057c3f59957","title":"杂曲歌辞 结客少年场行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韩魏多奇节，倜傥遗名利。","共矜然诺心，各负纵横志。","结友一言重，相思千里至。","绿沈明月弦，金络浮云辔。","吹箫入吴市，击筑游燕肆。","寻源博望侯，结客远相求。","少年重一顾，长驱背陇头。","燄燄霜戈动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈行秋。","轻生徇知己，非是为身谋。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["月","冬","秋","夏","雪"],"cats":{"抒情":["友情","思念","思乡"],"四季":["夏天","秋天","冬天"],"天气":["月亮"],"人生":["青春"]},"theme_conf":0.495},{"uid":"6d47c928-e6dd-4417-a9a5-acb7d4272e84","title":"新乐府 陵园妾\t怜幽闭也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["陵园妾，颜色如花命如叶。","命如叶薄将奈何，一奉寝宫年月多。","年月多，时光换，春愁秋思知何限。","青丝发落丛鬓疎，红玉肤销系帬慢。","忆昔宫中被妬猜，因谗得罪配陵来。","老母啼呼趁车别，中官监送鏁门回。","山宫一闭无开日，未死此身不令出。","松门到晓月裴回，柏城尽日风萧瑟。","松门柏城幽闭深，闻蝉听燕感光阴。","眼看菊蘂重阳泪，手把棃花寒食心。","把花掩泪无人见，绿芜墙绕青苔院。","四季徒支妆粉钱，三朝不识君王面。","遥想六宫奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，犹闻不啻三千人。","三千人，我尔君恩何厚薄。","愿令轮转直陵园，三岁一来均苦乐。"],"theme":"闺情宫怨","theme2":["送别","节令风俗"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["园林","重阳"],"cats":{"抒情":["伤感","闺怨"],"人物":["母亲"],"人生":["时光"],"节日":["寒食节","重阳节"]},"theme_conf":0.266},{"uid":"b14af996-a066-4cff-8903-35e2d658155a","title":"送许八拾遗归江宁觐省甫昔时尝客游此县于许生处乞瓦棺寺维摩图样志诸篇末","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["诏许辞中禁，慈颜赴北堂。","圣朝新孝理，祖席倍辉光。","内帛擎偏重，宫衣著更香。","淮阴清夜驿，京口渡江航。","春隔鸡人昼，秋期燕子凉。","赐书夸父老，寿酒乐城隍。","看画曾饥渴，追踪恨淼茫。","虎头金粟影，神妙独难忘。"],"theme":"送别","theme2":["羁旅思乡","送别"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["江","夜"],"cats":{"抒情":["思乡","孤独"],"山水":["江河"],"人生":["梦想"]},"theme_conf":0.94},{"uid":"cpfeda664cad7f2d","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"theme":"送别","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["悲慨","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","春","月"],"cats":{"抒情":["友情","离别","伤感","闺怨"],"四季":["春天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.357},{"uid":"367c97eb-901c-4688-ab45-2ee634454c0a","title":"赠王随","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青云自致晚应遥，朱邸新婚乐事饶。","饮罢更怜双袖舞，试来偏爱五花骄。","帐里炉香春梦晓，堂前烛影早更朝。","更说毬场新雨歇，王孙今日定相邀。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","雨"],"cats":{"四季":["春天"],"人生":["梦想"]},"theme_conf":0.87},{"uid":"a335f6c4-e9df-47d5-879d-9ebd3c1baf5c","title":"北征","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["皇帝二载秋，闰八月初吉。","杜子将北征，苍茫问家室。","维时遭艰虞，朝野少暇日。","顾慙恩私被，诏许归蓬荜。","拜辞诣阙下，怵惕久未出。","虽乏谏诤姿，恐君有遗失。","君诚中兴主，经纬固密勿。","东胡反未已，臣甫愤所切。","挥涕恋行在，道途犹恍惚。","乾坤含疮痍，忧虞何时毕。","靡靡逾阡陌，人烟眇萧瑟。","所遇多被伤，呻吟更流血。","回首凤翔县，旌旗晚明灭。","前登寒山重，屡得饮马窟。","邠郊入地底，泾水中荡潏。","猛虎立我前，苍崖吼时裂。","菊垂今秋花，石戴古车辙。","青云动高兴，幽事亦可悦。","山果多琐细，罗生杂橡栗。","或红如丹砂，或黑如点漆。","雨露之所濡，甘苦齐结实。","缅思桃源内，益叹身世拙。","坡陀望鄜畤，岩谷互出没。","我行已水滨，我仆犹木末。","鸱鸟鸣黄桑，野鼠拱乱穴。","夜深经战场，寒月照白骨。","潼关百万师，往者散何卒。","遂令半秦民，残害为异物。","况我堕胡尘，及归尽华发。","经年至茅屋，妻子衣百结。","恸哭松声回，悲泉共幽咽。","平生所娇儿，颜色白胜雪。","见耶背面啼，垢腻脚不韤。","床前两小女，补绽才过膝。","海图坼波涛，旧绣移曲折。","天吴及紫凤，颠倒在裋褐。","老夫情怀恶，呕泄卧数日。","那无囊中帛，救汝寒凛栗。","粉黛亦解苞，衾裯稍罗列。","瘦妻面复光，痴女头自栉。","学母无不为，晓妆随手抹。","移时施朱铅，狼藉画眉阔。","生还对童穉，似欲忘饥渴。","问事竞挽须，谁能即嗔喝。","飜思在贼愁，甘受杂乱聒。","新归且慰意，生理焉能说。","至尊尚蒙尘，几日休练卒。","仰观天色改，坐觉祅气豁。","阴风西北来，惨澹随回鹘。","其王愿助顺，其俗善驰突。","送兵五千人，驱马一万匹。","此辈少为贵，四方服勇决。","所用皆鹰腾，破敌过箭疾。","圣心颇虚伫，时议气欲夺。","伊洛指掌收，西京不足拔。","官军请深入，蓄锐何俱发。","此举开青徐，旋瞻略恒碣。","昊天积霜露，正气有肃杀。","祸转亡胡岁，势成擒胡月。","胡命其能久，皇纲未宜绝。","忆昨狼狈初，事与古先别。","奸臣竟葅醢，同恶随荡析。","不闻夏殷衰，中自诛褒妲。","周汉获再兴，宣光果明哲。","桓桓陈将军，仗钺奋忠烈。","微尔人尽非，于今国犹活。","凄凉大同殿，寂寞白兽闼。","都人望翠华，佳气向金阙。","园陵固有神，埽洒数不缺。","煌煌太宗业，树立甚宏达。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":["绮丽","悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["秋","山","夜","夏","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天","秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"fa252fae-6e68-425e-b0b3-89acc657b20c","title":"郊庙歌辞 太清宫乐章 序入破第二奏","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虚极仙宗本，希夷象帝先。","百灵朝太上，万法祖重圆。","善贷惟冲德，功成谓自然。","云门达和气，思用合钧天。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":1.0},{"uid":"b6985205-7423-47bf-ad4d-19e2ee4eaed0","title":"夜闻觱篥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜闻觱篥沧江上，衰年侧耳情所向。","邻舟一听多感伤，塞曲三更歘悲壮。","积雪飞霜此夜寒，孤灯急管复风湍。","君知天地干戈满，不见江湖行路难。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["悲怆","慷慨"],"scene":["夜"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"d70d3707-c751-4237-9b57-6f0e897d6c4d","title":"同陈六侍御寒食游禅定藏山上人院","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["年少轻行乐，东城南陌头。","与君寂寞意，共作草堂游。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["寒食节","清明节"]},"theme_conf":0.62},{"uid":"bd57a0b0-28a1-4d53-bc09-51899d2dac38","title":"兵车行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["车辚辚，马萧萧，行人弓箭各在腰。","耶娘妻子走相送，尘埃不见咸阳桥。","牵衣顿足阑道哭，哭声直上干云霄。","道傍过者问行人，行人但云点行频。","或从十五北防河，便至四十西营田。","去时里正与裹头，归来头白还戍边。","边亭流血成海水，武皇开边意未已。","君不闻汉家山东二百州，千村万落生荆杞。","纵有健妇把锄犂，禾生陇亩无东西。","况复秦兵耐苦战，被驱不异犬与鸡。","长者虽有问，役夫敢申恨。","且如今年冬，未休关西卒。","县官急索租，租税从何出？信知生男恶，反是生女好。","生女犹是嫁比邻，生男埋没随百草。","君不见青海头，古来白骨无人收。","新鬼烦冤旧鬼哭，天阴雨湿声啾啾。"],"theme":"边塞征战","theme2":["民生疾苦"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["冬"],"cats":{"四季":["冬天"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"402c5cc0-8255-4a01-8e5e-2641417bf8a2","title":"杂曲歌辞 白马篇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬鸡事万乘，轩盖一何高。","弓摧宜山虎，手接泰山猱。","酒后竞风彩，三杯弄宝刀。","杀人如翦草，剧孟同游遨。","发愤去函谷，从军向临洮。","叱咤万战场，匈奴尽波涛。","归来使酒气，未肯拜萧曹。","羞入原宪室，荒径隐蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":[],"scene":["山","酒","秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.79},{"uid":"3fc8c4c3-b3a0-459b-a497-3b0f2ecfed57","title":"窦朗州见示与澧州元郎中早秋赠荅命同作","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["邻境诸侯同舍郎，芷江兰浦恨无梁。","秋风门外旌旗动，晓露庭中橘柚香。","玉簟微凉宜白昼，金笳入暮应清商。","骚人昨夜闻𫛸鴂，不叹流年惜众芳。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":["沉郁","绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["时光"]},"theme_conf":0.94},{"uid":"9d2bcfb9-1052-40ca-8a14-87ba811aee4e","title":"秋暮言志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝光浮烧野，霜华净碧空。","结浪冰初镜，在迳菊方丛。","约岭烟深翠，分旗霞散红。","抽思滋泉侧，飞想傅岩中。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["秋","山"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"bf7821d0-4630-4e62-8462-c3e189277a4e","title":"三乡驿楼伏覩玄宗望女几山诗小臣斐然有感","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["开元天子万事足，唯惜当时光景促。","三乡陌上望仙山，归作霓裳羽衣曲。","仙心从此在瑶池，三清八景相追随。","天上忽乘白云去，世间空有秋风词。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山","楼"],"cats":{"抒情":["思乡"],"人生":["时光"]},"theme_conf":0.503},{"uid":"f8ec87e7-3074-40dd-8d87-a260dad83ae7","title":"相和歌辞 短歌行二首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曈曈太阳如火色，上行千里下一刻。","出为白昼入为夜，圜转如珠住不得。","住不得，可奈何？为君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君复强饮一杯。","人生不得长欢乐，年少须臾老到来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"天气":["写风"],"人生":["青春"]},"theme_conf":0.65},{"uid":"9f033648-d76a-4de4-ba1d-8c0298fa5c3d","title":"送薛居士和州读书","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤云独鹤共悠悠，万卷经书一叶舟。","楚地巢城民舍少，烟村社树鹭湖秋。","蒿莱织妾晨炊黍，隅落耕童夕放牛。","年少不应辞苦节，诸生若遇亦封侯。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.49},{"uid":"f81acf44-ba49-457e-9735-26292f63ec3b","title":"书志赠畅当","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["少喜神仙术，未去已蹉跎。","壮志一为累，浮生事渐多。","衰颜不相识，岁暮定相过。","请问宗居士，君其奈老何。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["励志","梦想"]},"theme_conf":0.86},{"uid":"f250e306-a578-4bb0-bdef-066a2be420fb","title":"晚发咸阳寄同院遗补","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["征战初休草又衰，咸阳晚眺泪堪垂。","去路全无千里客，秋田不见五陵儿。","秦家故事随流水，汉代高坟对石碑。","回首青山独不语，羡君谈笑万年枝。"],"theme":"咏史怀古","theme2":["悼亡挽歌","边塞征战"],"style":"旷达","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["园林","秋"],"cats":{"抒情":["伤感","孤独","悼亡","怀古"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.96},{"uid":"cpaf5595daded2dc","title":"渔家傲","author":"朱服","dynasty":"宋","section":"宋词","form":"词","paragraphs":["小雨廉纤风细细。","万家杨柳轻烟里。","恋树湿花飞不起。","愁无比。","和春付与西流水。","九十光阴能有几。","金龟解尽留无计。","寄语东城沽酒市。","拼一醉。","而今乐事他年泪。"],"theme":"咏怀抒感","theme2":["羁旅思乡","送别","闲适隐逸"],"style":"婉约","style2":["豪放","沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.88},{"uid":"d8364f1e-c63c-4df1-8772-e856094fef55","title":"台头寺愿上人院古松下有小松裁毫末新生与纤草不辨重其有凌云干霄之志与赵八员外裴十补阙同赋之","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["细草亦全高，秋毫乍堪比。","及至干霄日，何人复居此。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","楼","秋"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.52},{"uid":"2f609657-375a-4d97-b35e-880dbca040b2","title":"杂曲歌辞 少年行三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["巢燕养雏浑去尽，红花结子已无多。","黄衫年少来宜数，不见堂前东逝波。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"人生":["青春"]},"theme_conf":0.86},{"uid":"4058b815-c70e-4e63-8101-481838451b80","title":"送弘志上人归湖州","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山林唯幽静，行住不妨禅。","高月穿松迳，残阳过水田。","诗从宿世悟，法为本师传。","能使南人敬，修持香火缘。"],"theme":"送别","theme2":["哲理悟道","山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江","月","山"],"cats":{"人生":["哲理","梦想"]},"theme_conf":0.446},{"uid":"154bc6b6-be47-4e42-a039-e6f6d22fd447","title":"鼓吹曲辞 战城南","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["将军出紫塞，冒顿在乌贪。","笳喧雁门北，阵翼龙城南。","雕弓夜宛转，铁骑晓参潭。","应须驻白日，为待战方酣。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["塞外","夜","鸟"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"8585ac55-69dd-47ef-92b8-006e47054cc2","title":"长沙九日登东楼观舞 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["慢态不能穷，繁姿曲向终。","低回莲破浪，凌乱雪萦风。","坠珥时流盻，修裾欲溯空。","唯愁捉不住，飞去逐惊鸿。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","重阳","雪"],"cats":{"抒情":["伤感"],"人生":["励志"],"节日":["重阳节"]},"theme_conf":0.553},{"uid":"337b1cbf-675e-490f-a23d-48bee622b21f","title":"萤火","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幸因腐草出，敢近太阳飞。","未足临书卷，时能点客衣。","随风隔幔小，带雨傍林微。","十月清霜重，飘零何处归。"],"theme":"咏物","theme2":["讽喻刺世","羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.373},{"uid":"606d0bd8-31d2-4a7a-97ee-341956e7be60","title":"梦游天姥吟留别","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海客谈瀛洲，烟涛微茫信难求。","越人语天姥，云霓明灭或可覩。","天姥连天向天横，势拔五岳掩赤城。","天台四万八千丈，对此欲倒东南倾。","我欲因之梦吴越，一夜飞度镜湖月。","湖月照我影，送我至剡溪。","谢公宿处今尚在，渌水荡漾清猨啼。","脚著谢公屐，身登青云梯。","半壁见海日，空中闻天鸡。","千岩万转路不定，迷花倚石忽已暝。","熊咆龙吟殷岩泉，栗深林兮惊层巅。","云青青兮欲雨，水澹澹兮生烟。","列缺霹雳，丘峦崩摧。","洞天石扇，訇然中开。","青冥浩荡不见底，日月照耀金银台。","霓为衣兮风为马，云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，仙之人兮列如麻。","忽魂悸以魄动，怳惊起而长嗟。","惟觉时之枕席，失向来之烟霞。","世间行乐亦如此，古来万事东流水。","别君去时何时还，且放白鹿青崖间，须行即骑访名山。","安能摧眉折腰事权贵？使我不得开心颜。"],"theme":"游仙梦幻","theme2":["送别"],"style":"冲淡","style2":["婉约"],"mood":"相思","mood2":["恬淡"],"scene":["江南","山","江","月"],"cats":{"抒情":["离别","思念"],"人生":["梦想"]},"theme_conf":0.397},{"uid":"7a97a451-d5e0-4de9-8762-7ccdf64773dd","title":"杂曲歌辞 少年行三首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["马上谁家白面郎，临阶下马坐人床。","不通姓字麄豪甚，指点银瓶索酒尝。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"57239e87-5c37-4c28-b253-a7bc96649ea4","title":"横吹曲辞 出塞","author":"张易之","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["侠客重恩光，骢马饰金装。","瞥闻传羽檄，驰突救边荒。","转战磨筓地，横行戴斗乡。","将军占太白，小妇怨流黄。","騕褭青丝骑，娉婷红粉妆。","一春莺度曲，八月雁成行。","谁堪坐秋思，罗袖拂空床。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","春","鸟"],"cats":{"四季":["春天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.728},{"uid":"43f8bb74-5673-41a8-96ac-6a5e3a906382","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春生南国瘴，气待北风苏。","向晚霾残日，初宵鼓大𬬻。","爽携卑湿地，声拔洞庭湖。","万里鱼龙伏，三更鸟兽呼。","涤除贪破浪，愁绝付摧枯。","执热沈沈在，凌寒往往须。","且知宽疾胏，不敢恨危途。","再宿烦舟子，衰容问仆夫。","今晨非盛怒，便道即长驱。","隐几看帆席，云州涌坐隅。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["夜","江","舟"],"cats":{"抒情":["伤感"],"天气":["写风"],"人生":["励志"]},"theme_conf":0.72},{"uid":"ed9d64a1-e731-4851-92fa-05556336ef56","title":"奉陪韦润州游鹤林寺","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野寺江城近，双旌五马过。","禅心超忍辱，梵语问多罗。","松林闲僧老，云烟晚日和。","寒塘归路转，清磬隔微波。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","江"],"cats":{"人生":["哲理"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"eaef090a-c731-44fb-8d03-829ed9237e25","title":"柳州罗池庙诗（题拟）","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["荔子丹兮蕉黄（「蕉」下或有「叶」字，或有「子」字），杂肴蔬兮进侯堂。","侯之船兮两旗，度中流兮风泊之，待侯不来兮不知我悲。","侯乘驹兮入庙，慰我民兮不嚬以笑。","鹅之山兮柳之水，桂树团团兮白石齿齿。","侯朝出游兮暮来归，春与猿吟兮秋鹤与飞。","（《唐文粹》及欧阳修所见《韩集》均作「秋与鹤飞」。","《集古录跋尾》卷八录碑文作「秋鹤与飞」，欧疑碑文有误。","沈括《梦溪笔谈》卷十四以为此用《楚辞》相错成文格，今从其说。","）北方之人兮为侯是非，千秋万岁兮侯无我违。","福我兮寿我，驱厉鬼兮山之左。","下无湿兮高无干，秔稌充羡兮蛇蛟结蟠。","我民报事兮无怠其始，自今兮钦于世世。","（同前书卷三一、《唐文粹》卷五二《柳州罗池庙碑》附）（〖1〗《柳州罗池庙碑》云：「三年孟秋辛卯，侯降于州之后堂，欧阳翼等见而拜之。","其夕，梦翼而告之曰：『馆我于罗池。","』其日景辰，庙成，大祭。","过客李仪醉酒，慢侮堂上，得疾，扶出庙门即死。","明年春，魏忠、欧阳翼使谢宁来京师，请书其事于石。","余谓柳侯生能泽其民，死能惊动祸福之，以食其土，可谓灵也已。","作迎享送神诗遗柳民，俾歌以祀焉而幷刻之。","……其词曰〖词略〗。","」《湖南通志·金石》六著录嘉定刻此碑，题作《唐罗池庙享神词碑》，附魏绍芳跋此为享神诗。","《唐诗别裁集》卷七收入。","朱东润师主编《中国历代文学作品选》中编第一册收此诗，题作《柳州罗池庙诗》，解题云：「此庙建成后，韩愈为撰《柳州罗池庙碑》，诗就附在碑文的后面。","诗效《楚辞·九歌》体，作为祭祀中迎神、送神时歌唱之用。","」）。"],"theme":"佛道禅颂","theme2":["咏物","咏史怀古","山水田园"],"style":"绮丽","style2":["幽峭","豪放"],"mood":"悲怆","mood2":[],"scene":["园林","酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人生":["读书"],"植物":["柳树"],"食物":["荔枝"]},"theme_conf":0.75},{"uid":"5a76b6ea-07ee-44b6-ac20-a87d18203810","title":"答侯少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常日好读书，晚年学垂纶。","漆园多乔木，睢水清粼粼。","诏书下柴门，天命敢逡巡。","赫赫三伏时，十日到咸秦。","褐衣不得见，黄绶翻在身。","吏道顿羁束，生涯难重陈。","北使经大寒，关山饶苦辛。","边兵若刍狗，战骨成埃尘。","行矣勿复言，归欤伤我神。","如何燕赵陲，忽遇平生亲。","开馆纳征骑，弹弦娱远宾。","飘飖天地间，一别方兹晨。","东道有佳作，南朝无此人。","性灵出万象，风骨超常伦。","吾党谢王粲，群贤推郄诜。","明时取秀才，落日过蒲津。","节苦名已富，禄微家转贫。","相逢愧薄游，抚己荷陶钧。","心事正堪尽，离居宁太频。","两河归路遥，二月芳草新。","柳接滹沱暗，莺连渤海春。","谁谓行路难，猥当希代珍。","提握每终日，相思犹比邻。","江海有扁舟，丘园有角巾。","君意定何适，我怀知所遵。","浮沈各异宜，老大贵全真。","莫作云霄计，遑遑随缙绅。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":["旷达"],"mood":"相思","mood2":[],"scene":["舟","春","鸟"],"cats":{"抒情":["离别","思念","思乡"],"四季":["春天"],"天气":["太阳"],"人生":["读书","战争"]},"theme_conf":0.96},{"uid":"1dc19ddd-357b-4a1a-b5b2-260954fde2a4","title":"华清宫和杜舍人","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五十年天子，离宫仰峻墙。","登封时正泰，御宇日何长。","上位先名实，中兴事宪章。","起戎轻甲胄，余地复河湟。","道帝玄元祖，儒封孔子王。","因缘百司署，藂会一人汤。","渭水波摇绿，秦郊草半黄。","马驯金勒细，鹰健玉铃锵。","下箭朱弓满，鸣鞭皓腕攘。","畋思获吕望，谏祇避周昌。","兔迹贪前逐，枭心不早防。","几添鹦鹉劝，先赐荔枝尝。","月锁千门静，天吹一笛凉。","细音摇羽珮，轻步宛霓裳。","祸乱基潜结，升平意遽忘。","衣冠逃犬虏，鼙鼓动渔阳。","外戚心殊迫，中途事可量。","血埋妃子艳，刅断禄儿肠。","近侍烟尘隔，前踪辇路荒。","益知迷宠佞，遗恨丧贤良。","北阙尊明主，南宫逊上皇。","禁清余凤吹，池冷睡龙光。","祝寿山犹在，流年水共伤。","杜鹃魂厌蜀，蝴蝶梦悲庄。","雀卵遗雕栱，虫丝罥画粱。","紫苔侵壁润，红树闭门芳。","守吏齐鸳瓦，耕民得翠珰。","登年齐酺乐，讲武旧兵场。","暮草深岩翠，幽花坠径香。","不堪垂白叟，行折御沟杨。"],"theme":"咏史怀古","theme2":["咏史怀古","边塞征战"],"style":"绮丽","style2":["清新","婉约"],"mood":"相思","mood2":["欢愉","悲怆"],"scene":["花","山"],"cats":{"抒情":["伤感","怀古"],"人生":["时光","战争"],"食物":["荔枝"]},"theme_conf":0.97},{"uid":"e9e6425c-6c14-4f69-8694-87a8b96a43de","title":"春望","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["国破山河在，城春草木深。","感时花溅泪，恨别鸟惊心。","烽火连三月，家书抵万金。","白头搔更短，浑欲不胜簪。"],"theme":"咏怀抒感","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"]},"theme_conf":0.7},{"uid":"a93b3a91-73b6-4087-8757-5a8f1c8d4161","title":"山斋读书寄时校书杜叟","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日爱蘅茅下，闲观山海图。","幽人自守朴，穷谷也名愚。","倒岭和溪雨，新泉到户枢。","丛兰齐稚子，蟠木老潜夫。","忆戴差过剡，游仙惯入壶。","濠梁时一访，庄叟亦吾徒。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.441},{"uid":"7b8079ae-910c-4680-883a-6f747712ce0d","title":"行路难二首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见富家翁，旧时贫贱谁比数。","一朝金多结豪贵，万事胜人健如虎。","子孙成行满眼前，妻能管弦妾能舞。","自矜一身忽如此，却笑傍人独愁苦。","东邻少年安所如，席门穷巷出无车。","有才不肯学干谒，何用年年空读书。"],"theme":"讽喻刺世","theme2":["羁旅思乡","闺情宫怨","民生疾苦"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"人生":["读书"]},"theme_conf":0.98},{"uid":"1d413c37-f370-4d3e-ab48-0b6137b83ba8","title":"酬诸公宿镜水宅","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["幸免低头向府中，贵将藜藿与君同。","阳雁呌霜来枕上，寒山映月在湖中。","诗书何德名夫子，草木推年长数公。","闻道汉家偏尚少，此身那此访芝翁。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["月","鸟","山"],"cats":{"人生":["读书"]},"theme_conf":0.95},{"uid":"b323c71f-ed8e-49cd-8baf-42089fa17706","title":"石州城","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈夫心爱横行，报国知嫌命轻。","楼兰径百战，更道戍龙城。","锦字窦车骑，胡笳李少卿。","生离两不见，万古难为情。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","幽峭"],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.828},{"uid":"7cb1e181-617c-4e12-b818-48666992ebf6","title":"饮中八仙歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["知章骑马似乘船，眼花落井水底眠。","汝阳三斗始朝天，道逢曲车口流涎。","恨不移封向酒泉，左相日兴费万钱。","饮如长鲸吸百川，衔杯乐圣称世贤。","宗之潇洒美少年，举觞白眼望青天。","皎如玉树临风前，苏晋长斋绣佛前。","醉中往往爱逃禅，李白一斗诗百篇。","长安市上酒家眠，天子呼来不上船。","自称臣是酒中仙，张旭三杯草圣传。","脱帽露顶王公前，挥毫落纸如云烟。","焦遂五斗方卓然，高谈雄辨惊四筵。"],"theme":"游仙梦幻","theme2":["哲理悟道"],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":["愁怨"],"scene":["酒"],"cats":{"人生":["哲理"]},"theme_conf":0.377},{"uid":"8b41afb4-d737-43e1-9f79-1a8101eaa87e","title":"相和歌辞 从军行","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔从李都尉，双鞬照马蹄。","擒生黑山北，杀敌黄云西。","太白沈虏地，边草复萋萋。","归来邯郸市，百尺青楼梯。","感激然诺重，平生胆力齐。","芳筵暮歌发，艳粉轻鬟低。","半醉秋风起，铁骑门前嘶。","远戍报烽火，孤城严鼓鼙。","挥鞭望尘去，少妇莫含啼。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.858},{"uid":"bad7958c-eafc-4acb-8c6a-663f745cb133","title":"奉和鄜州刘大夫麦秋出师遮虏有怀中朝亲故","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天子爱全才，故人雄外台。","绿油登上将，青绶亚中台。","亭障鸣笳入，风云转斾来。","兰坊分杳杳，麦垅望莓莓。","月向雕弓满，莲依宝劒开。","行师齐鹤列，锡马尽龙媒。","壮志征梁甫，嘉招萃楚材。","千寻推直干，百炼去纤埃。","间阔劳相望，欢言幸早陪。","每联花下骑，几泛竹间杯。","芳讯双鱼远，流年两鬓催。","何时介圭觐，携手咏康哉。"],"theme":"边塞征战","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["秋","楼","花"],"cats":{"四季":["秋天"],"人生":["励志","时光","梦想"]},"theme_conf":0.82},{"uid":"8073152d-7f39-430b-93d2-24a9f7fc5323","title":"冬到金华山观因得故拾遗陈公学堂遗迹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涪右众山内，金华紫崔嵬。","上有蔚蓝天，垂光抱琼台。","系舟接绝壁，杖策穷萦回。","四顾俯层巅，澹然川谷开。","雪岭日色死，霜鸿有余哀。","焚香玉女跪，雾里仙人来。","陈公读书堂，石柱仄青苔。","悲风为我起，激烈伤雄才。"],"theme":"山水田园","theme2":["悼亡挽歌","游仙梦幻"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["山","冬"],"cats":{"抒情":["伤感","悼亡"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.424},{"uid":"f85432ef-54f1-4cc0-91c5-91af18ff0d05","title":"春日玄武门宴群臣","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韶光开令序，淑气动芳年。","驻辇华林侧，高宴柏梁前。","紫庭文珮满，丹墀衮绂连。","九夷簉瑶席，五狄列琼筵。","娱宾歌湛露，广乐奏钧天。","清尊浮绿醑，雅曲韵朱弦。","粤余君万国，还慙抚八埏。","庶几保贞固，虚己厉求贤。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":0.95},{"uid":"e4dc9fac-1160-45b6-8182-51829ac15f72","title":"河南白尹有喜崔宾客归洛兼见怀长句因而继和","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["几年侍从作名臣，却向青云索得身。","朝士忽为方外士，主人仍是眼中人。","双鸾游处天京好，五马行时海峤春。","遥羡光阴不虚掷，肯令丝竹暂生尘。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"d3974504-f89f-4aa0-9400-ef0ef6de1e55","title":"题昭上人房","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沃州传教后，百衲老空林。","虑尽朝昏磬，禅随坐卧心。","鹤飞湖草迥，门闭野云深。","地与天台接，中峰早晚寻。"],"theme":"咏物","theme2":["山水田园","哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"人生":["哲理"]},"theme_conf":0.399},{"uid":"1b942cdf-a8ec-4bf9-8c1e-bba47e0c4726","title":"暮秋枉裴道州手札率尔遣兴寄近呈苏涣侍御","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["久客多枉友朋书，素书一月凡一束。","虚名但蒙寒温问，泛爱不救沟壑辱。","齿落未是无心人，舌存耻作穷途哭。","道州手札适复至，纸长要自三过读。","盈把那须沧海珠，入怀本倚昆山玉。","拨弃潭州百斛酒，芜没潇岸千株菊。","使我昼立烦儿孙，令我夜坐费灯烛。","忆子初尉永嘉去，红颜白面花映肉。","军符侯印取岂迟，紫燕𫘧耳行甚速。","圣朝尚飞战鬬尘，济世宜引英俊人。","黎元愁痛会苏息，夷狄跋扈徒逡巡。","授钺筑坛闻意旨，颓纲漏网期弥纶。","郭钦上书见大计，刘毅答诏惊群臣。","他日更仆语不浅，明公论兵气益振。","倾壶箫管黑白发，儛劒霜雪吹青春。","宴筵曾语苏季子，后来杰出云孙比。","茅斋定王城郭门，药物楚老渔商市。","市北肩舆每联袂，郭南抱瓮亦隐几。","无数将军西第成，早作丞相东山起。","鸟雀苦肥秋粟菽，蛟龙欲蛰寒沙水。","天下鼓角何时休，阵前部曲终日死。","附书与裴因示苏，此生已媿须人扶。","致君尧舜付公等，早据要路思捐躯。"],"theme":"边塞征战","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨","慷慨"],"scene":["秋","夜"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"人生":["青春","战争"]},"theme_conf":0.356},{"uid":"5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093","title":"杂曲歌辞 渭城少年行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["欢愉"],"scene":["楼","清明","春","酒"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["青春"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.579},{"uid":"12f064ff-4e03-42fd-a28b-6e1495baf93c","title":"省试临渊羡鱼","author":"徐牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清泚濯缨处，今来喜一临。","慙无下钓处，空有羡鱼心。","退省时频改，谋身岁屡沈。","鬣成川上媚，网就水宁深。","頳尾临波里，朱须破浪浔。","此时傥不漏，江上免行吟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"人生":["励志"]},"theme_conf":1.0},{"uid":"5b721d41-b555-48ff-8c1d-c81104498e39","title":"早登太行山中言志","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清跸度河阳，凝笳上太行。","火龙明鸟道，铁骑绕羊肠。","白雾埋阴壑，丹霞助晓光。","涧泉含宿冻，山木带余霜。","野老茅为屋，樵人薜作裳。","宣风问耆艾，敦俗劝耕桑。","凉德慙先哲，徽猷慕昔皇。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人生":["梦想"]},"theme_conf":0.674},{"uid":"39e6e1d3-5d9e-4b3b-90f6-762839b3b8ed","title":"赠鉴上人","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["律仪传教诱，僧腊老烟霄。","树色依禅诵，泉声入寂寥。","宝龛经末劫，画壁见南朝。","深竹风开合，寒潭月动摇。","息心归静理，爱道坐中宵。","更欲寻真去，乘船过海潮。"],"theme":"佛道禅颂","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["夜","月","舟","江"],"cats":{"人生":["哲理"]},"theme_conf":0.86},{"uid":"78975868-daef-40f6-89f2-1aa8b5308c55","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已愁花落荒岩底，复恨根生乱石间。","几度欲移移不得，天教抛掷在深山。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","花","月","冬","夏"],"cats":{"抒情":["伤感","孤独","感恩"],"四季":["夏天","冬天"],"天气":["月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.475},{"uid":"0eaf80f5-5cbe-4075-9e50-793cfa66c8f5","title":"宿叶公棋阁","author":"李洞","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["带风棋阁竹相敲，局莹无尘拂树梢。","日到长天征未断，钟来岳顶劫须抛。","挑灯雪客栖寒店，供茗溪僧𦶟废巢。","因悟修身试贪教，不须焚火向三茅。"],"theme":"哲理悟道","theme2":["哲理悟道","羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["哲理"],"植物":["叶子"]},"theme_conf":0.72},{"uid":"2e743a29-04ae-416e-a014-6da19281a515","title":"雪后宿王纯池州草堂","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宿君湖上宅，琴韵静参差。","夜雪入秋浦，孤城连贵池。","流年看共老，衔酒发中悲。","良会应难再，晨鸡自有期。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["时光"]},"theme_conf":0.72},{"uid":"47cb698a-c951-49a4-b17c-032bc033ac87","title":"房兵曹胡马诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["胡马大宛名，锋棱瘦骨成。","竹批双耳峻，风入四蹄轻。","所向无空阔，真堪托死生。","骁腾有如此，万里可横行。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"人生":["战争"],"动物":["写马"]},"theme_conf":0.739},{"uid":"eed6313c-5664-4ab4-b04a-7de9d8a2fd3a","title":"霍小玉歌 三","author":"李惟","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西北槛前挂鹦鹉，笼中报道李郎来。","（见宋陈元龙《片玉集注》卷一《荔枝香》注引《丽情集》引《小玉歌》）（按：此诗作者之推定，与本书卷二十二崔珏《灼灼歌》相类，可参看。","《新唐书》卷七二《宰相世系表》载李义琛孙、李绾子名惟，约为盛君时人，当非此诗作者。","）。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"人生":["读书"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"d9afbbdc-a953-44c7-93c6-dd133a03a2cd","title":"送辽阳使还军","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["征人歌且行，北上辽阳城。","二月戎马息，悠悠边草生。","青山出塞断，代地入云平。","昔者匈奴战，多闻杀汉兵。","平生报国愤，日夜角弓鸣。","勉君万里去，勿使虏尘惊。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","夜","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.666},{"uid":"5bce54d8-5f1a-487b-807c-b30714c006f4","title":"不见","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不见李生久，佯狂真可哀。","世人皆欲杀，吾意独怜才。","敏捷诗千首，飘零酒一桮。","匡山读书处，头白好归来。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","悲慨"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"人生":["读书"]},"theme_conf":0.76},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"e71eb5f9-d4a1-44dd-b2ad-bffe671f51dd","title":"鼓吹曲辞 有所思","author":"孟郊","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["桔槔烽火昼不灭，客路迢迢信难越。","古镇刀攒万片霜，寒江浪起千堆雪。","此时西去定如何，空使南心远凄切。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["雪","江南","江"],"cats":{"人生":["战争"]},"theme_conf":0.656},{"uid":"738fc3d5-b2e3-4f00-8a81-496c103cdd58","title":"同吉中孚梦桃源 二","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜静春梦长，梦逐仙山客。","园林满芝术，鸡犬傍篱栅。","几处花下人，看予笑头白。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","欢愉"],"scene":["春","夜","山","园林"],"cats":{"四季":["春天"],"人生":["梦想"],"生活":["乡村"],"植物":["桃花"]},"theme_conf":0.438},{"uid":"785ea8b0-4589-4ea2-a01c-226a2556dbe5","title":"题玄武禅师屋壁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何年顾虎头，满壁画瀛州。","赤日石林气，青天江海流。","锡飞常近鹤，桮度不惊鸥。","似得庐山路，真随惠远游。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.768},{"uid":"e0fd6680-7e2c-4e1f-88bc-7ddd77c0789c","title":"谒真谛寺禅师","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兰若山高处，烟霞嶂几重。","冻泉依细石，晴雪落长松。","问法看诗忘，观身向酒慵。","未能割妻子，卜宅近前峰。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","雪","酒"],"cats":{"人生":["哲理"]},"theme_conf":0.563},{"uid":"69438f82-ac49-4093-85d4-99095b68d968","title":"同王𫓾起居程浩郎中韩翃舍人题安国寺用上人院","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["慧眼沙门真远公，经行宴坐有儒风。","香缘不绝簪裾会，禅想宁妨藻思通。","曙后𬬻烟生不灭，晴来堦色并归空。","狂夫入室无余事，唯与天花一笑同。"],"theme":"佛道禅颂","theme2":[],"style":"豪放","style2":["冲淡","旷达"],"mood":"欢愉","mood2":["恬淡"],"scene":["园林","花"],"cats":{"人生":["哲理"]},"theme_conf":0.84},{"uid":"4c9c3d75-272f-4529-bf21-8aafbe5b276e","title":"杂曲歌辞 昔昔盐 那能惜马蹏","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云中路杳杳，江畔草萋萋。","妾久垂珠泪，君何惜马蹏。","边风悲晓角，营月怨春鼙。","未道休征战，愁眉又复低。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["婉约","悲慨"],"mood":"愁怨","mood2":[],"scene":["春","月","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.665},{"uid":"dfe41fd5-0f8c-4a52-9ce5-8622202264ff","title":"琴曲歌辞 湘妃怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南巡竟不返，帝子怨逾积。","万里丧蛾眉，潇湘水空碧。","冥冥荒山下，古庙收贞魄。","乔木深青春，清光满瑶席。","搴芳徒有荐，灵意殊脉脉。","玉佩不可亲，裴回烟波夕。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.593},{"uid":"344b8022-5073-4b18-a099-ee3e1f12412b","title":"相和歌辞 短歌行","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人若不死，吾亦何所悲。","萧萧烟雨九原上，白杨青松葬者谁。","贵贱同一尘，死生同一指。","人生在世共如此，何异浮云与流水。","短歌行，短歌无穷日已倾。","邺宫梁苑徒有名，春草秋风伤我情。","何为不学金仙侣？一悟空王无死生。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","秋","雨"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"人生":["哲理"]},"theme_conf":0.531},{"uid":"195ac36f-552e-4cc2-9e99-6d8c0cc93b72","title":"杂曲歌辞 少年行二首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官为骏马监，职帅羽林儿。","两绶藏不见，落花何处期？","猎敲白玉镫，怒袖紫金锤。","田窦长留醉，苏辛曲护岐。","豪持出塞节，笑别远山眉。","捷报云台贺，公卿拜寿巵。"],"theme":"边塞征战","theme2":["送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","酒","山"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.409},{"uid":"a2b4fe60-9809-422d-afa7-143a2088f045","title":"阙题","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道由白云尽，春与青溪长。","时有落花至，远随流水香。","闲门向山路，深柳读书堂。","幽映每白日，清辉照衣裳。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":0.406},{"uid":"e4545449-1757-4265-96bb-8fb65870b953","title":"池州夫子庙麟台","author":"韦表微","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["二仪既闭，三象乃乖。","圣道埋郁，人心不开。","上无文武，下有定哀。","吁嗟麟兮，孰为来哉。","周虽不纲，孔实嗣圣。","诗书既删，礼乐大定。","劝善惩恶，奸邪乃正。","吁嗟麟兮，克昭符命。","圣与时合，化行位尊。","苟或乖戾，身穷道存。","于昭鲁邑，栖迟孔门。","吁嗟麟兮，孰知其仁。","运极数残，德至时否。","楚国寖广，秦封益侈。","墙仞迫阨，崎岖阙里。","吁嗟麟兮，靡有攸止。","世治则麟，世乱则麕。","出非其时，麋鹿同群。","孔不自圣，麟不自祥。","吁嗟麟兮，天何所亡。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["园林","楼"],"cats":{"抒情":["怀古"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.9},{"uid":"c3702d36-4293-4d70-a4e9-3b752445769f","title":"杂曲歌辞 少年行三首 二","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自拳五色毬，迸入他人宅。","却捉苍头奴，玉鞭打一百。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"bdb32446-6efc-402e-93f0-901b8eefe57e","title":"杂曲歌辞 生别离","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生别之为难，苦在心兮酸在肝。","晨鸡载鸣残月没，征马重嘶行人出。","回看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠梨叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧积心劳血气衰，未年三十生白发。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋","月"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.762},{"uid":"bb8bcabd-0823-4dea-bf90-a3a59aec3f22","title":"宿云门上方","author":"秦系","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禅室遥看峰顶头，白云东去水长流。","松间傥许幽人住，不更将钱买沃州。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"天气":["写云"],"人生":["哲理"]},"theme_conf":0.626},{"uid":"252c40ba-d76c-4893-925b-41883a6f254c","title":"横吹曲辞 出塞","author":"陈子昂","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["忽闻天上将，关塞重横行。","始返楼兰国，还向朔方城。","黄金装战马，白羽集神兵。","星月开天阵，山川列地营。","晚风吹画角，春色耀飞旌。","宁知班定远，独是一书生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.843},{"uid":"775398c8-b809-40aa-af2f-93746dbc82ca","title":"客中有感","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["天地一身在，头颅五十过。","流年消壮志，空使泪成河。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["愁怨"],"scene":[],"cats":{"抒情":["思乡","伤感"],"人生":["励志","时光","梦想"]},"theme_conf":1.0},{"uid":"209d2029-4af8-471c-91e1-f67ffc20c5b1","title":"宝林寺作","author":"徐浩","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["兹山昔飞来，远自琅琊台。","孤岫龟形在，深泉鳗井开。","越王屡登陟，何相传词才。","塔庙宗其巅，规模称壮哉。","禅堂清溽润，高阁无恢炱。","照耀珠吐月，铿轰钟隐雷。","揆余久缨弁，末路遭邅回。","一弃沧海曲，六年稽岭隈。","逝川惜东驶，驰景怜西颓。","腰带愁疾减，容颜衰悴催。","赖居兹寺中，法士多瓌能。","洗心听经论，礼足蠲凶灾。","永愿依胜侣，清江乘度杯。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","慷慨"],"scene":["山","江","楼"],"cats":{"抒情":["伤感","孤独"],"人生":["哲理"]},"theme_conf":0.78},{"uid":"bd285a68-be33-4ac0-b7ca-0dbd2b19b885","title":"平齐行二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["泰山沈寇六十年，旅祭不享生愁烟。","今逢圣君欲封禅，神使阴兵来阻战。","妖氛扫尽河水清，日观杲杲卿云见。","开元黄帝东封时，百神受职争奔驰。","千钧猛簴顺流下，洪波涵淡浮熊罴。","侍臣燕公秉文笔，玉检告天无媿词。","当今睿孙承圣祖，岳神望幸河宗舞。","青门大道属车尘，共待葳蕤翠华举。"],"theme":"应制干谒","theme2":["边塞征战","闺情宫怨","哲理悟道"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["伤感","闺怨"],"山水":["泰山"],"人生":["哲理","战争"]},"theme_conf":0.82},{"uid":"3866facf-d8d2-4f4e-b7c4-eefbc12bfdea","title":"关羽祠送高员外还荆州","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["将军禀天姿，义勇冠今昔。","走马百战场，一剑万人敌。","虽为感恩者，竟是思归客。","流落荆巫间，裴回故乡隔。","离筵对祠宇，洒酒暮天碧。","去去勿复言，衔悲向陈迹。"],"theme":"送别","theme2":["边塞征战","咏史怀古","羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡","伤感","怀古","感恩"],"人生":["战争"]},"theme_conf":0.72},{"uid":"a1255e7f-9db9-45a3-85cf-ad00559a3e58","title":"沣水送郑鄠县读书","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["麦秋中夏凉风起，送君西郊及沣水。","孤烟远树动离心，隔岸江流若千里。","早年江海谢浮名，此路云山惬尔情。","上古全经皆在口，秦人如见济南生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","秋","江","山"],"cats":{"抒情":["离别","孤独"],"四季":["夏天","秋天"],"山水":["江河"],"人生":["读书"]},"theme_conf":0.766},{"uid":"187bb2c5-4648-43a5-9361-e1b3a8aa65f8","title":"郊庙歌辞 禅社首乐章 太和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["肃我成命，于昭黄祇。","裘冕而祀，陟降在斯。","五音克备，八音聿施。","缉熙肆靖，厥心匪离。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":0.712},{"uid":"9b388c43-8ac8-412d-b310-d063c4149afa","title":"归义寺题震上人壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入谷逢雨花，香绿引幽步。","招提饶泉石，万转同一趣。","向背森碧峰，浅深罗古树。","尧皇未登极，此地曾隐雾。","秘谶得神谋，因高思虎踞。","太阳忽临照，物象俄光煦。","梵王宫始开，长者金先布。","白水入禅境，砀山通觉路。","往往无心云，犹起潜龙处。","仍闻七祖后，佛子继调御。","溪鸟投慧灯，山蝉饱甘露。","不作解缨客，宁知舍筏喻。","身世已悟空，归途复何去。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["山","花"],"cats":{"人生":["哲理"]},"theme_conf":0.9},{"uid":"d8a8ab40-f615-44dd-9366-883aa1202a1c","title":"路病","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["病客无主人，艰哉求卧难。","飞光赤道路，内火焦肺肝。","欲饮井泉竭，欲医囊用单。","稚颜能几日，壮志忽已残。","人子不言苦，归书但云安。","愁环在我肠，宛转终无端。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感"],"人生":["励志","梦想"]},"theme_conf":0.542},{"uid":"3f44618a-ec8e-40e0-bbfd-7cefa27e61d2","title":"杂曲歌辞 凉州词","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜蕃兵报国讐，沙州都护破凉州。","黄河九曲今归汉，塞外纵横战血流。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江","塞外","夜"],"cats":{"抒情":["爱国"],"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"d0a388eb-dd3d-4735-aacc-392ff3a2bed1","title":"留上李右相","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风俗登淳古，君臣挹大庭。","深沈谋九德，密勿契千龄。","独立调元气，清心豁窅冥。","本枝连帝系，长策冠生灵。","傅说明殷道，萧何律汉刑。","钧衡持国柄，柱石总朝经。","隐轸江山藻，氛氲鼎鼐铭。","兴中皆白雪，身外即丹青。","江海呼穷鸟，诗书问聚萤。","吹嘘成羽翼，提握动芳馨。","倚伏悲还笑，栖迟醉复醒。","恩荣初就列，含育忝宵形。","有窃丘山惠，无时枕席宁。","壮心瞻落景，生事感浮萍。","莫以才难用，终期善易听。","未为门下客，徒谢少微星。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":["婉约"],"mood":"慷慨","mood2":["欢愉","悲怆"],"scene":["雪","江","山"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":1.0},{"uid":"55b3c9cc-9b0b-4ed7-92ee-29b01c690c9f","title":"游长安诸寺联句 宣阳坊静域寺 三阶院联句","author":"段成式","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["密密助堂堂，隋人歌檿桑。","双弧摧孔雀，一矢陨贪狼。","百步望云立，九规看月张。","获蛟徒破浪，中乙漫如墙。","还似贯金鼓，更疑穿石梁。","因添挽河力，为灭射天狂。","绝艺却南牧，英声来鬼方。","丽龟何足敌，殪豕未为长。","龙臂胜猨臂，星芒超箭芒。","虚夸绝高鸟，垂拱议明堂。"],"theme":"哲理悟道","theme2":["山水田园","悼亡挽歌"],"style":"幽峭","style2":["冲淡","豪放"],"mood":"恬淡","mood2":[],"scene":["园林","月"],"cats":{"抒情":["悼亡"],"人生":["励志"]},"theme_conf":0.422},{"uid":"7bdd44ad-6a7e-4c17-802a-c88127770ca2","title":"秋日台中寄怀简诸僚","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["宪府日多事，秋光照碧林。","干云岩翠合，布石地苔深。","忧悔耿遐抱，尘埃缁素襟。","物情牵跼促，友道旷招寻。","颓节风霜变，流年芳景侵。","池荷足幽气，烟竹又繁阴。","簪组赤墀恋，池鱼沧海心。","涤烦滞幽赏，永度瑶华音。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.9},{"uid":"22e90c0d-2b59-4500-8e5d-80d38ec4692c","title":"闻官军收河南河北","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["劒外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.512},{"uid":"a7f9cfd6-7f54-4737-9d0d-ada81cb18e68","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白虹见，昼（川本作「尽」）见地侵（辛本、川本作「青」）天。","其地一方皆主乱，众人喧闹有灾缠，年内应其占。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"c3699e7b-dd2c-4d73-8e85-30e42f7363da","title":"横吹曲辞 入关","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["都城连百二，雄险北回环。","地势遥尊岳，河流侧让关。","秦皇曾虎视，汉祖亦龙颜。","何事枭凶辈，干戈自不闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人生":["战争"]},"theme_conf":0.501},{"uid":"664aff60-36cb-4907-8842-e6717be10cce","title":"送耿拾遗𣲗使江南括图书","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["驱传草连天，回风满树蝉。","将过夫子宅，前问孝廉船。","汉使收三箧，周诗采百篇。","别来将有泪，不是怨流年。"],"theme":"题画咏艺","theme2":["送别"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.471},{"uid":"dfaaaf11-9ead-4921-a71e-1f60be94af03","title":"得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官作掾心非好，儒服临戎政已闻。","说劒尝宗漆园吏，戒严应笑棘门军。","遥知抵掌论皇道，时复吟诗向白云。","百越待君言即叙，相思不敢怆离群。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["园林","江南"],"cats":{"抒情":["思念"],"人生":["读书","战争"],"动物":["写马"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"c9e63635-0caa-43c2-b4b8-b459f9983fbf","title":"送高三十五书记","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["崆峒小麦熟，且愿休王师。","请公问主将，焉用穷荒为。","饥鹰未饱肉，侧翅随人飞。","高生跨鞍马，有似幽幷儿。","脱身簿尉中，始与捶楚辞。","借问今何官，触热向武威。","答云一书记，所媿国士知。","人实不易知，更须慎其仪。","十年出幕府，自可持旌麾。","此行既特达，足以慰所思。","男儿功名遂，亦在老大时。","常恨结驩浅，各在天一涯。","又如参与商，惨惨中肠悲。","惊风吹鸿鹄，不得相追随。","黄尘翳沙漠，念子何当归。","边城有余力，早寄从军诗。"],"theme":"送别","theme2":[],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.587},{"uid":"ed5ce508-2df4-4ef2-a6a0-5b8586766d6f","title":"惟此温泉是称愈疾岂予独受其福思与兆人共之乘暇巡游乃言其志","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["桂殿与山连，兰汤涌自然。","阴崖含秀色，温谷吐潺湲。","绩为蠲邪著，功因养正宣。","愿言将亿兆，同此共昌延。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"824423a3-e7e6-41f5-bf24-d0d755bd5ed7","title":"过孔北海墓二十韵","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["抚事如神遇，临风独涕零。","墓平春草绿，碑折古苔青。","珪玉埋英气，山河孕炳灵。","发言惊辨囿，㧑翰动文星。","蕴策期干世，持权欲反经。","激扬思壮志，流落叹颓龄。","恶木人皆息，贪泉我独醒。","轮辕无匠石，刀几有庖丁。","碌碌迷藏器，规规守挈瓶。","愤容凌鼎镬，公议动朝廷。","故国将辞宠，危邦竟缓刑。","钝工磨白璧，凡石砺青萍。","揭日昭东夏，抟风滞北溟。","后尘遵轨辙，前席咏仪型。","木秀当忧悴，弦伤不底宁。","矜夸遭斥鷃，光彩困飞萤。","白羽留谈柄，清风袭德馨。","鸾凰婴雪刃，狼虎犯云屏。","兰蕙荒遗址，榛芜蔽旧坰。","轘辕近沂水，何事恋明庭。"],"theme":"咏史怀古","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["夏","雪","春"],"cats":{"抒情":["孤独","怀古"],"四季":["春天","夏天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"8baf651c-c608-4795-9260-c572c4af580b","title":"杂曲歌辞 少年行三首 三","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["玉劒膝边横，金杯马上倾。","朝游茂陵道，暮宿凤凰城。","豪吏多猜忌，无劳问姓名。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"43d23382-d543-4aba-8a11-ed524328785d","title":"横吹曲辞 紫骝马","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骝马照金鞍，转战入皐兰。","塞门风稍急，长城水正寒。","雪暗鸣珂重，山长喷玉难。","不辞横绝漠，流血几时干。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"8b73dd1d-d744-4620-965f-163b4b45127d","title":"南中春意","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入仕无知言，游方随世道。","平生愿开济，遇物干怀抱。","已阻青云期，甘同散樗老。","客游南海曲，坐见韶阳蚤。","旧国别佳人，他乡思芳草。","惜无鸿鹄翅，安得凌苍昊。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["女子"],"人生":["梦想"]},"theme_conf":0.618},{"uid":"9deee86d-3d16-40f1-aff9-f8805c75d827","title":"送王正字山寺读书","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["欲究先儒教，还过支遁居。","山堦闲听法，竹迳独看书。","向日荷新卷，迎秋柳半疎。","风流有佳句，不似带经锄。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.418},{"uid":"9bc25c25-81f9-4003-8592-9f413774e85f","title":"夜梦","author":"萧妃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昨日梦君归，贱妾下鸣机。","极知意气薄，不著去时衣。","故言如梦里，赖得雁书飞。"],"theme":"羁旅思乡","theme2":["闺情宫怨","游仙梦幻"],"style":"沉郁","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["夜"],"cats":{"抒情":["思念","思乡","闺怨"],"人生":["梦想"]},"theme_conf":0.437},{"uid":"a90b0985-951f-4afa-8f71-2a618b92d3aa","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 三","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓现，城寨可攻之。","虹（辛本、川本作「蛇」）直入来为病疫，浅虹兵瘴（京本作「青虹兵战」）要须知，移寨避灾宜（京本作「危」）。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"246ff90e-bd5c-4e81-8637-f1605fa647d9","title":"园官送茶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清晨蒙菜把，常荷地主恩。","守者愆实数，略有其名存。","苦苣刺如针，马齿叶亦繁。","青青嘉蔬色，埋没在中园。","园吏未足怪，世事固堪论。","呜呼战伐久，荆棘暗长原。","乃知苦苣辈，倾夺蕙草根。","小人塞道路，为态何喧喧。","又如马齿盛，气拥葵荏昏。","点染不易虞，丝麻杂罗纨。","一经器物内，永挂麤刺痕。","志士采紫芝，放歌避戎轩。","畦丁负笼至，感动百虑端。"],"theme":"送别","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["园林"],"cats":{"人生":["战争"],"生活":["边塞"],"食物":["写茶"]},"theme_conf":0.401},{"uid":"5f5d9f3e-a3d3-446a-ba9c-3066f4b6eff9","title":"杂曲歌辞 少年行四首 四","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["霜满中庭月过楼，金尊玉柱对清秋。","当年称意须为乐，不到天明未肯休。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"ca632d53-d4c4-41c3-a8e7-82f9c48cfd29","title":"初入谏司喜家室至","author":"窦群","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一旦悲欢见孟光，十年辛苦伴沧浪。","不知笔砚缘封事，犹问佣书日几行。"],"theme":"羁旅思乡","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.65},{"uid":"f0d03f1b-abb4-4c3c-84b8-ee1925878a97","title":"琴曲歌辞 幽兰","author":"崔涂","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽植众能知，贞芳只暗持。","自无君子佩，未是国香衰。","白露沾长早，青春每到迟。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":0.96},{"uid":"db9d91d8-9d41-4922-82a7-1c8d23f66238","title":"秋夜梁七兵曹同宿二首 二","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["好欲弃吾道，今宵又遇君。","老夫相劝酒，稚子待题文。","月下谁家笛，城头几片云。","如何此幽兴，明日重离群。"],"theme":"寄赠酬答","theme2":["亲情","边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"79462191-3bcb-4599-b51b-40bcf4d3065d","title":"杂曲歌辞 结客少年场行","author":"虞羽客","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽幷侠少年，金络控连钱。","窃符方救赵，击筑正怀燕。","轻生辞凤阙，挥袂上祁连。","陆离横宝劒，出没惊徂旃。","蒙轮恒顾敌，超乘忽争先。","摧枯逾百战，拓地远三千。","骨都魂已散，楼兰首复传。","龙城含晓雾，瀚海隔遥天。","歌吹金微返，振旅玉门旋。","烽火今已息，非复照甘泉。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["婉约","清新"],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.565},{"uid":"20a6a82e-639c-4244-a3c4-193f16fd0b57","title":"赠李八秘书别三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往时中补右，扈跸上元初。","反气凌行在，妖星下直庐。","六龙瞻汉阙，万骑略姚墟。","玄朔回天步，神都忆帝车。","一戎才汗马，百姓免为鱼。","通籍蟠螭印，差肩列凤舆。","事殊迎代邸，喜异赏朱虚。","寇盗方归顺，乾坤欲晏如。","不才同补衮，奉诏许牵裾。","鸳鹭叨云阁，麒麟滞玉除。","文园多病后，中散旧交疎。","飘泊哀相见，平生意有余。","风烟巫峡远，台榭楚宫虚。","触目非论故，新文尚起予。","清秋凋碧柳，别浦落红蕖。","消息多旗帜，经过叹里闾。","战连唇齿国，军急羽毛书。","幕府筹频问，山家药正锄。","台星入朝谒，使节有吹嘘。","西蜀灾长弭，南翁愤始摅。","对敭抏士卒，干没费仓储。","势藉兵须用，功无礼忽诸。","御鞍金騕褭，宫砚玉蟾蜍。","拜舞银钩落，恩波锦帕舒。","此行非不济，良友昔相于。","去斾依颜色，沿流想疾徐。","沈绵疲井臼，倚薄似樵渔。","乞米烦佳客，钞诗听小胥。","杜陵斜晚照，潏水带寒淤。","莫话清溪发，萧萧白暎梳。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["元宵","楼"],"cats":{"抒情":["离别"],"人生":["战争"],"节日":["元宵节"]},"theme_conf":0.348},{"uid":"b45024f9-099b-4057-897c-f5a2e3016dd3","title":"夜听许十损诵诗爱而有作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["许生五台宾，业白出石壁。","余亦师粲可，身犹缚禅寂。","何阶子方便，谬引为匹敌。","离索晚相逢，包蒙欣有击。","诵诗浑游衍，四座皆辟易。","应手看捶钩，清心听鸣镝。","精微穿溟涬，飞动摧霹雳。","陶谢不枝梧，风骚共推激。","紫燕自超诣，翠駮谁翦剔。","君意人莫知，人间夜寥阒。"],"theme":"送别","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"人生":["哲理"]},"theme_conf":0.509},{"uid":"af29ed64-419d-4eeb-803a-8466d45a7a2b","title":"昼梦","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["二月饶睡昏昏然，不独夜短昼分眠。","桃花气暖眼自醉，春渚日落梦相牵。","故乡门巷荆棘底，中原君臣豺虎边。","安得务农息战鬬，普天无吏横索钱。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["春","月","夜","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.658},{"uid":"b0049020-3b5e-4a46-9b66-71f6de65501d","title":"杂曲歌辞 少年行三首 一","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十八羽林郎，戎衣事汉王。","臂鹰金殿侧，挟弹玉舆旁。","驰道春风起，陪游出建章。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"b4e7cec1-f391-4b59-a09e-7815b6675fff","title":"题庄上人房","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不语焚香坐，心知道已成。","流年衰此世，定力见他生。","暮雪余春冷，寒灯续昼明。","寻常五侯至，敢望下阶迎。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","春"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"ee380cd0-fea2-4baa-92b7-c82c834265e6","title":"相和歌辞  豫章行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["胡风吹代马，北拥鲁阳关。","吴兵照海雪，西讨何时还？","半渡上辽津，黄云惨无颜。","老母与子别，呼天野草间。","白马绕旌旗，悲鸣相追攀。","白杨秋月苦，早落豫章山。","本为休明人，斩虏素不闲。","岂惜战鬬死，为君埽凶顽。","精感石没羽，岂忘惮险艰。","楼船若鲸飞，波荡落星湾。","此曲不可奏，三军鬓成斑。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","秋","月","楼","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["母亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.582},{"uid":"9e6cbc1b-95ed-406b-8c9d-d05876a1342c","title":"送陈章甫","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["四月南风大麦黄，枣花未落桐阴长。","青山朝别暮还见，嘶马出门思旧乡。","陈侯立身何坦荡，虬须虎眉仍大颡。","腹中贮书一万卷，不肯低头在草莽。","东门酤酒饮我曹，心轻万事皆鸿毛。","醉卧不知白日暮，有时空望孤云高。","长河浪头连天黑，津口停舟渡不得。","郑国游人未及家，洛阳行子空叹息。","闻道故林相识多，罢官昨日今如何。"],"theme":"送别","theme2":[],"style":"雄浑","style2":["豪放","沉郁"],"mood":"孤寂","mood2":["相思"],"scene":["酒","舟"],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.675},{"uid":"02304a34-5fd7-44fc-a781-9a1ed35a8a03","title":"秋风二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹巫山，上牢下牢修水关。","吴樯楚柁牵百丈，暖向神都寒未还。","要路何日罢长戟，战自青羌连百蛮。","中巴不曾消息好，暝传戍鼓长云间。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp5be9581b63edc2","title":"锁窗寒・琐寒窗","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["暗柳啼鸦，单衣伫立，小帘朱户。","桐花半亩，静锁一庭愁雨。","洒空阶，夜阑未休，故人剪烛西窗语。","似楚江暝宿，风灯零乱，少年羁旅。","迟暮。","嬉游处。","正店舍无烟，禁城百五。","旗亭唤酒，付与高阳俦侣。","想东园，桃李自春，小唇秀靥今在否。","到归时，定有残英，待客携尊俎。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春","夜","酒","雨"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"5a429d13-1d1b-4a15-9823-4abea75b9fa4","title":"闻庆州赵纵使君与党项战中箭身死辄书长句","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["将军独乘铁骢马，榆溪战中金仆姑。","死绥却是古来有，骁将自惊今日无。","青史文章争点笔，朱门歌舞笑捐躯。","谁知我亦轻生者，不得君王丈二殳。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.639},{"uid":"0145b0c7-8703-4e0d-b2a0-16a069723bd0","title":"杂曲歌辞 少年行","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少年足风情，垂鞭卖眼行。","带金师子小，裘锦骐𬴊狞。","选匠装金镫，推钱买[钿]筝。","李陵虽效死，时论得虚名。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"1eb3241e-272e-4183-801d-b37e6beb048f","title":"拟娼楼节怨","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上苑离离莺度，昆明幂幂蒲生。","时光春华可惜，何须对镜含情。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.544},{"uid":"de67de33-4490-4be1-accf-46965ae26d38","title":"杂曲歌辞 少年行二首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["连环羁玉声光碎，绿锦蔽泥虬卷高。","春风细雨走马去，珠落璀璀白𦋺袍。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"],"人生":["青春"]},"theme_conf":1.0},{"uid":"680c2d30-359c-475e-8e95-069f7018fdb0","title":"春日与诸公泛舟","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千里雪山开，沱江春水来。","驻帆云缥缈，吹管鹤裴回。","身外流年驶，尊前落景催。","不应归棹远，明月在高台。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.65},{"uid":"3e025699-a493-49b3-8b9d-be47fd65a2ae","title":"太子张舍人遗织成褥段","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["客从西北来，遗我翠织成。","开缄风涛涌，中有掉尾鲸。","逶迤罗水族，琐细不足名。","客云充君褥，承君终宴荣。","空堂魑魅走，高枕形神清。","领客珍重意，顾我非公卿。","留之惧不祥，施之混柴荆。","服饰定尊卑，大哉万古程。","今我一贱老，裋褐更无营。","煌煌珠宫物，寝处祸所婴。","叹息当路子，干戈尚纵横。","掌握有权柄，衣马自肥轻。","李鼎死岐阳，实以骄贵盈。","来瑱赐自尽，气豪直阻兵。","皆闻黄金多，坐见悔吝生。","奈何田舍翁，受此厚贶情。","锦鲸卷还客，始觉心和平。","振我麤席尘，媿客茹藜羹。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["思乡","悼亡"],"人生":["战争"]},"theme_conf":0.384},{"uid":"cp4cbe1f231c0a58","title":"永遇乐","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["千古江山，英雄无觅，孙仲谋处。","舞榭歌台，风流总被，雨打风吹去。","斜阳草树，寻常巷陌，人道寄奴曾住。","想当年，金戈铁马，气吞万里如虎。","元嘉草草，封狼居胥，赢得仓皇北顾。","四十三年，望中犹记，烽火扬州路。","可堪回首，佛狸祠下，一片神鸦社鼓。","凭谁问，廉颇老矣，尚能饭否。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"人生":["战争"]},"theme_conf":0.351},{"uid":"1318e5a7-c894-4bb0-a1aa-f5760e0b7f63","title":"旅馆雪晴又覩新月众兴所感因成杂言","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寥寥深夜雪初晴，楼上云开月渐明。","池中片影依稀见，帘外清光远近生。","皎皎晴空疑破镜，广庭积素偏相映。","珠帘卷却光更深，玉指持来色逾净。","梦觉青楼最可怜，婵娟素魄满寒天。","天地寥寥同一色，秦淮楚江无限极。","归鸿断猨何处声，深闺旅馆遥相忆。","长安五侯华阁开，嘉宾列坐倾金罍。","赏明月，玩流雪，纤手蛾眉座中设。","清歌一声无断绝，夜已央，乐未阑。","狐裘兽炭不知寒，珠环翠珮声珊珊。","履舃纷纭桂袖攒，朱颜倚醉尽君欢。","人生少年全不久，相看且劝杯中酒。","丈夫富贵自有期，映雪读书徒白首。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["孤寂"],"scene":["雪","月"],"cats":{"抒情":["思乡"],"天气":["写雪","月亮"],"人生":["青春","读书"],"节日":["中秋节"]},"theme_conf":0.557},{"uid":"36b6f467-dc98-4ac0-9b1b-316b4a65db43","title":"连州吟 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["羽翼不自有，相追力难任。","唯凭方寸灵，独夜万里寻。","方寻魂飘飖，南梦山岖嵚。","髣髴惊魍魉，悉窣闻枫林。","正直被放者，鬼魅无所侵。","贤人多安排，俗士多虚钦。","孤怀吐明月，众毁铄黄金。","愿君保玄曜，壮志无自沉。"],"theme":"游仙梦幻","theme2":[],"style":"幽峭","style2":["旷达","豪放"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.65},{"uid":"1c3b38ef-9c86-4971-8fe5-6234163dce8f","title":"薜荔庵","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["薜荔作禅庵，重叠庵边树。","空山径欲绝，也有人知处。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人生":["哲理"]},"theme_conf":0.509},{"uid":"241e52e3-22fe-4943-b65e-74117c33b8b7","title":"鼓吹曲辞 战城南二首 二","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["碛中有阴兵，战马时惊蹶。","轻猛李陵心，摧残苏武节。","黄金锁子甲，风吹色如铁。","十载不封侯，茫茫向谁说。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"人生":["战争"]},"theme_conf":1.0},{"uid":"c89b78bc-576e-40b0-923d-916d181cf73d","title":"归梦","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道路时通塞，江山日寂寥。","偷生唯一老，伐叛已三朝。","雨急青枫暮，云深黑水遥。","梦归归未得，不用楚辞招。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["雄浑"],"mood":"相思","mood2":["孤寂"],"scene":["塞外","雨","江","山"],"cats":{"抒情":["思乡"],"人生":["梦想"]},"theme_conf":0.627},{"uid":"7834bc02-d434-470f-8874-1f45a60707bc","title":"赠海明上人","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["来自西天竺，持经奉紫微。","年深梵语变，行苦俗流归。","月上安禅久，苔生出院稀。","梁间有驯鸽，不去复何依。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["月","园林"],"cats":{"人生":["哲理"]},"theme_conf":0.93},{"uid":"ea3f7ed0-3704-4ff2-aa5e-1727b20e3a7c","title":"安公房问法","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["流年一日复一日，世事何时是了时。","试向东林问禅伯，遣将心地学琉璃。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"山水":["庐山"],"人生":["哲理","时光"]},"theme_conf":0.96},{"uid":"1d65129a-ea27-4ec6-b8ed-8c12ee3d0d0a","title":"秋日书怀","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["金貂玉铉奉君恩，夜漏晨钟老掖垣。","参决万机空有媿，静观群动亦无言。","杯中壮志红颜歇，林下秋声绛叶翻。","倦鸟不知归去日，青芜白露满郊园。"],"theme":"咏怀抒感","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"慷慨","mood2":["恬淡"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["励志","梦想"]},"theme_conf":0.9},{"uid":"ad765a79-3c31-49ca-9e63-6bebc466ecd3","title":"送李殷游边","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十年梦相识，一觏俄远别。","征驾在我傍，草草意难说。","君居洞庭日，诗句满魏阙。","如何万里来，青桂看人折。","行装不及备，西去偶然诀。","孟夏出都门，红尘客衣热。","荒城见羊马，野馆具薇蕨。","边境渐无虞，旅宿常待月。","西园置酒地，日夕簪裾列。","壮志安可留，槐花樽前发。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["酒","园林","月","江","夏"],"cats":{"四季":["夏天"],"人生":["励志","梦想"]},"theme_conf":0.683},{"uid":"e5a97aba-72cd-4663-81fe-1f0af4375e15","title":"青云干吕","author":"林藻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["应节偏干吕，亭亭在紫氛。","缀空初布影，捧日已成文。","结盖祥光迥，为楼翠色分。","还同起封上，更似出横汾。","作瑞来藩国，呈形表圣君。","裴回如有托，谁道比闲云。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.58},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"9e40d9e8-6894-423e-a22e-41f78c97937a","title":"读谢灵运诗","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾闻达士道，穷通顺冥数。","通乃朝廷来，穷即江湖去。","谢公才廓落，与世不相遇。","壮志郁不用，须有所泄处。","泄为山水诗，逸韵谐奇趣。","大必笼天海，细不遗草树。","岂惟玩景物，亦欲摅心素。","往往即事中，未能忘兴谕。","因知康乐作，不独在章句。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["慷慨","孤寂"],"scene":["江"],"cats":{"抒情":["孤独","感恩"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"0f5874bf-3748-44c9-bc3a-be4a8c3eb2f6","title":"阁夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"],"theme":"边塞征战","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["夜"],"cats":{"抒情":["思乡","伤感"],"天气":["星星"],"人生":["战争"]},"theme_conf":0.425},{"uid":"6e8b1a9f-037f-4f95-94e3-4287c2a9787a","title":"岁除日奉推事使牒追赴抚州辨对留别崔法曹陆大祝处士上人同赋人字口号","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["上国杳未到，流年忽复新。","回车不自识，君定送何人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["除夕"],"cats":{"抒情":["离别"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.651},{"uid":"e4354c00-c83e-43da-9341-7007889dd625","title":"过香积寺","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不知香积寺，数里入云峰。","古木无人迳，深山何处钟。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禅制毒龙。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"婉约","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["山","花"],"cats":{"抒情":["孤独"],"人生":["哲理"]},"theme_conf":0.74},{"uid":"cpe17f558a5aa701","title":"洞仙歌","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["冰肌玉骨，自清凉无汗。","水殿风来暗香满。","绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。","起来携素手，庭户无声，时见疏星渡河汉。","试问夜如何，夜已三更，金波淡、玉绳低转。","但屈指、西风几时来，又不道、流年暗中偷换。"],"theme":"闺情宫怨","theme2":["游仙梦幻"],"style":"绮丽","style2":["冲淡","婉约"],"mood":"恬淡","mood2":[],"scene":["夜","月"],"cats":{"抒情":["闺怨"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.623},{"uid":"06b100d5-9899-4ae0-9eb8-66983943969f","title":"高都护骢马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["安西都护胡青骢，声价歘然来向东。","此马临阵久无敌，与人一心成大功。","功成惠养随所致，飘飘远自流沙至。","雄姿未受伏枥恩，猛气犹思战场利。","腕促蹄高如踣铁，交河几蹴曾冰裂。","五花散作云满身，万里方看汗流血。","长安壮儿不敢骑，走过掣电倾城知。","青丝络头为君老，何由却出横门道。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":[],"cats":{"人生":["战争"],"动物":["写马"]},"theme_conf":1.0},{"uid":"cpdef5aab5815c88","title":"木兰花慢","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["老来情味减，对别酒、怯流年。","况屈指中秋，十分好月，不照人圆。","无情水、都不管，共西风、只等送归船。","秋晚莼鲈江上，夜深儿女灯前。","征衫。","便好去朝天。","玉殿正思贤。","想夜半承明，留教视草，却遣筹边。","长安故人问我，道寻常、泥酒只依然。","目断秋霄落雁，醉来时响空弦。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","酒","夜","中秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.568},{"uid":"e7c246f6-8c50-43a0-b4ad-6a42a6cf6d7e","title":"云梦故城秋望","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故国遗墟在，登临想旧游。","一朝人事变，千载水空流。","梦渚鸿声晚，荆门树色秋。","片云凝不散，遥挂望乡愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.479},{"uid":"4d9c03ce-ae52-44ae-8100-f43432da8432","title":"杂曲歌辞 少年乐","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二十便封侯，名居第一流。","绿鬟深小院，清管下高楼。","醉把金船掷，闲敲玉镫游。","带盘红鼹鼠，袍砑紫犀牛。","锦袋归调箭，罗鞋起拨毬。","眼前长贵盛，那信世间愁。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","舟","园林","酒"],"cats":{"抒情":["伤感"],"人生":["青春"]},"theme_conf":0.62},{"uid":"64458e92-e680-4804-99da-aebca507210b","title":"送进士李殷下第游汾河","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上国花照地，遣君向西征。","旁人亦有恨，况复故人情。","单车欲云去，别酒忽然醒。","如何今夜梦，半作道路程。","边士不好礼，全家住军城。","城中鼓角严，旅客常夜惊。","中有左记室，逢人眼光明。","西门未归者，下马如到京。","还应一开卷，为子心不平。","慇懃说忠抱，壮志勿自轻。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["夜","酒"],"cats":{"抒情":["友情"],"人生":["励志","梦想"]},"theme_conf":0.534},{"uid":"59fb3f01-65b2-416a-aefb-c13e502bfba1","title":"塞下曲四首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["饮马渡秋水，水寒风似刀。","平沙日未没，黯黯见临洮。","昔日长城战，咸言意气高。","黄尘足今古，白骨乱蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"bdd14fd6-3be3-4f4f-acb7-4c8080ee8c83","title":"赠衡岳隐禅师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["拥褐安居南岳头，白云高寺见衡州。","石窗湖水摇寒月，枫树猨声报夜秋。","讲席旧逢山鸟至，梵经初向竺僧求。","垂垂身老将传法，因下人间逐北游。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.82},{"uid":"05ca1eef-d549-4f8e-b853-1340fbb486b8","title":"杂曲歌辞 行路难五首 三","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见荒树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟空守闺。","独宿自然堪下泪，况复时闻乌夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","春","秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["春天","秋天"],"人生":["战争"],"节日":["中秋节"]},"theme_conf":0.714},{"uid":"a6a2e130-f45f-49a4-a7da-e0441d1578cd","title":"酬庞十兵曹","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔游京华，自言生羽翼。","怀书访知己，末路空相识。","许国不成名，还家有慙色。","托身从𤱶亩，浪迹初自得。","雨泽感天时，耕耘忘帝力。","同人洛阳至，问我睢水北。","遂尔款津涯，净然见胸臆。","高谈悬物象，逸韵投翰墨。","别岸迥无垠，海鹤鸣不息。","梁城多古意，携手共凄恻。","怀贤想邹枚，登高思荆棘。","世情恶疵贱，之子怜孤直。","酬赠感幷深，离忧岂终极。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["重阳"],"cats":{"抒情":["友情","离别","思念","孤独"],"人生":["战争"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"21943b5d-11e5-44f2-9714-ad996dade3ae","title":"杂曲歌辞 少年行二首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["走马还相寻，西楼下夕阴。","结交期一劒，留意赠千金。","高阁歌声远，重关柳色深。","夜闲须尽醉，莫负百年心。"],"theme":"咏怀抒感","theme2":["送别","羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.78},{"uid":"bce77cf0-244d-435a-8a25-8d28a83bc4b9","title":"奉赠韦左丞二十二韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["纨袴不饿死，儒冠多误身。","丈人试静听，贱子请具陈。","甫昔少年日，早充观国宾。","读书破万卷，下笔如有神。","赋料扬雄敌，诗看子建亲。","李邕求识面，王翰愿卜邻。","自谓颇挺出，立登要路津。","致君尧舜上，再使风俗淳。","此意竟萧条，行歌非隐沦。","骑驴三十载，旅食京华春。","朝扣富儿门，暮随肥马尘。","残杯与冷炙，到处潜悲辛。","主上顷见征，歘然欲求伸。","青冥却垂翅，蹭蹬无纵鳞。","甚媿丈人厚，甚知丈人真。","每于百僚上，猥诵佳句新。","窃效贡公喜，难甘原宪贫。","焉能心怏怏，秪是走踆踆。","今欲东入海，即将西去秦。","尚怜终南山，回首清渭滨。","常拟报一饭，况怀辞大臣。","白鸥没浩荡，万里谁能驯。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":0.97},{"uid":"2c9a2809-eb92-46db-bdea-5c6071efe4f1","title":"梦好梨花歌","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["薄薄落落雾（别本作「路」）不分，梦中唤作梨花云。","瑶池水光蓬莱雪，青叶白花相次发。","不从地上生枝柯，合在天头遶宫阙。","天风微微吹不破，白艳却愁香涴露。","玉房彩女齐看来，错认仙山鹤飞过。","落花散粉飘满空，梨花颜色同不同。","眼穿臂短取不得，取得亦如从梦中。","无人为我解此梦，梨花一曲心珍重。","（见宋张邦基《墨庄漫录》卷六）（按：《墨庄漫录》：「东坡作梅花词云：『高情已逐晓云空，不与梨花同梦。","』注云：『唐王建有《梦看梨花云诗》。","』予求王建诗，行世甚少，唯印行本一卷，乃无此篇。","后得之于晏元献《类要》中。","后又得建全集七卷，乃得全篇，题云《梦好梨花歌》。","〖诗略〗或误传为王昌龄，非也。","」另参本书卷九王昌龄诗附按。","）。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["花"],"cats":{"抒情":["伤感","孤独"],"人生":["梦想","读书"],"植物":["梨花"]},"theme_conf":0.776},{"uid":"cp54f371b40dff60","title":"忆少年","author":"晁补之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["无穷官柳，无情画舸，无根行客。","南山尚相送，只高城人隔。","罨画园林溪绀碧。","算重来、尽成陈迹。","刘郎鬓如此，况桃花颜色。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["舟","山","园林"],"cats":{"抒情":["思念"],"人生":["青春"]},"theme_conf":0.538},{"uid":"b541e528-83cc-4c89-9990-94fda479abdb","title":"留别郑三韦九兼洛下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["忆昨相逢论久要，顾君哂我轻常调。","羁旅虽同白社游，诗书已作青云料。","蹇质蹉跎竟不成，年过四十尚躬耕。","长歌达者桮中物，大笑前人身后名。","幸逢明盛多招隐，高山大泽征求尽。","此时亦得辞渔樵，青袍裹身荷圣朝。","犂牛钓竿不复见，县人邑吏来相邀。","远路鸣蝉秋兴发，华堂美酒离忧销。","不知何日更携手，应念兹晨去折腰。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["秋","酒"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.432},{"uid":"7c79a705-fd5b-48b1-bc25-3d8658cd634c","title":"相和歌辞 从军行三首 三","author":"李约","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["候火起雕城，尘砂拥战声。","游军藏汉帜，降骑说蕃情。","霜降滮池浅，秋深太白明。","嫖姚方虎视，不觉请添兵。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["战争"]},"theme_conf":0.864},{"uid":"ba2f4924-7ab8-48f2-9e23-d656dea0117b","title":"杂曲歌辞 行路难二首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["长安少年不少钱，能骑骏马鸣金鞭。","五侯相逢大道边，美人弦管争留连。","黄金如斗不敢惜，片言如山莫弃捐。","安知顦顇读书者，暮宿虚台私自怜。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["读书"]},"theme_conf":0.65},{"uid":"0e1af8d7-0b33-4175-b3a3-4ddeebe8703a","title":"郊庙歌辞 禅社首乐章 灵具醉","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["灵具醉，杳熙熙。","灵将往，眇禗禗。","顾明德，吐正辞。","烂遗光，流祯祺。"],"theme":"哲理悟道","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"人生":["哲理"],"食物":["写酒"]},"theme_conf":0.587},{"uid":"9bb05363-395d-48f6-b28a-55d3e414d6cf","title":"杂曲歌辞 发白马","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["将军发白马，旌节渡黄河。","箫鼓聒川岳，沧溟涌洪波。","武安有振瓦，易水无寒歌。","铁骑若雪山，饮流涸滹沱。","扬兵猎月窟，转战畧朝那。","倚剑登燕然，边峰列嵯峨。","萧条万里外，耕作五原多。","一扫清大漠，包虎戢金戈。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","清新"],"mood":"慷慨","mood2":[],"scene":["山","江","雪","塞外","月"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.777},{"uid":"feb085bc-e461-4a18-b787-e831e3ef1885","title":"宿庐山赠白鹤观刘尊师","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苍苍五老雾中坛，杳杳三山洞里官。","手护昆仑象牙简，心推霹雳枣枝盘。","春飞雪粉如毫润，晓漱琼膏冰齿寒。","渐恨流年筋力少，惟思露冕事星冠。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["清新","雄浑"],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"山水":["庐山"],"天气":["写雪"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"6f9c734b-00ef-4d46-b30a-79ff6770c7aa","title":"长安书怀","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岐路今如此，还堪恸哭频。","关中成久客，海上老诸亲。","谷口田应废，乡山草又春。","年年销壮志，空作献书人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"827e44b1-7064-4ff7-9a9c-192eece94e2d","title":"韦讽录事宅观曹将军画马图","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["国初已来画鞍马，神妙独数江都王。","将军得名三十载，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹雳。","内府殷红马脑盌，倢伃传诏才人索。","盌赐将军拜舞归，轻纨细绮相追飞。","贵戚权门得笔迹，始觉屏障生光辉。","昔日太宗拳毛䯄，近时郭家师子花。","今之新图有二马，复令识者久叹嗟。","此皆骑战一敌万，缟素漠漠开风沙。","其余七匹亦殊绝，迥若寒空动烟雪。","霜蹄蹴踏长楸间，马官厮养森成列。","可怜九马争神骏，顾视清高气深稳。","借问苦心爱者谁，后有韦讽前支遁。","忆昔巡幸新丰宫，翠华拂天来向东。","腾骧磊落三万匹，皆与此图筋骨同。","自从献宝朝河宗，无复射蛟江水中。","君不见金粟堆前松柏里，龙媒去尽鸟呼风。"],"theme":"边塞征战","theme2":["题画咏艺"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["相思"],"scene":["雪","塞外"],"cats":{"抒情":["思念","孤独"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.481},{"uid":"c3ef6911-ab4b-41fb-9614-1fc519b996d1","title":"郊庙歌辞 禅社首乐章 雍和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["夙夜宥密，不敢宁宴。","五齐既陈，八音在县。","粢盛以洁，房俎斯荐。","惟德惟馨，尚兹克徧。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"人生":["哲理"]},"theme_conf":1.0},{"uid":"9b1ba89a-046a-4f9b-a38f-f619d1f85a52","title":"题延州圣僧穴","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["定力无涯不可称，未知何代坐禅僧。","默默山门宵闭月，荧荧石壁昼然灯。","四时树长书经叶，万岁岩悬拄杖藤。","昔日舍身缘救鸽，今时出见有飞鹰。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","夜","月"],"cats":{"人生":["哲理"]},"theme_conf":0.95},{"uid":"2ac203a8-6e70-4b78-ad75-9acacae9b04a","title":"相和歌辞  北上行","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北上何所苦，北上缘太行。","磴道盘且峻，巉岩凌穹苍。","马足蹶侧石，车轮摧高冈。","沙尘接幽州，烽火连朔方。","杀气毒劒戟，严风裂衣裳。","奔鲸夹黄河，凿齿屯洛阳。","前行无归日，返顾思旧乡。","惨戚冰雪里，悲号绝中肠。","尺布不掩体，皮肤剧枯桑。","汲水涧谷阻，采薪陇坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，饥饮零露浆。","叹此北上苦，停骖为之伤。","何日王道平？开颜覩天光。"],"theme":"边塞征战","theme2":["民生疾苦","山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["秋","冬","江","雪"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"山水":["黄河"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.296},{"uid":"2bdc4aa6-9b3f-4243-9d45-825d13267797","title":"登玉山诸峰偶至悟真寺","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["郭南云水佳，讼简野情发。","紫芝每相引，黄绶不能𫄬。","稍入石门幽，始知灵境绝。","冥搜未寸晷，仙迳俄九折。","蟠木盖石梁，崩岸露云穴。","数峰拔昆仑，秀色与空澈。","玉气交晴虹，桂花留曙月。","半岩采珉者，一点如片雪。","真赏无前程，奇观宁暂辍。","更闻东林磬，可听不可说。","兴中寻觉化，寂尔诸象灭。"],"theme":"山水田园","theme2":["山水田园"],"style":"绮丽","style2":["冲淡","幽峭"],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.72},{"uid":"4d22a2f9-a696-435c-8d2e-7c7e1b3c1af9","title":"鼓吹曲辞 将进酒","author":"李贺","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["瑠璃钟，琥珀浓，小槽酒滴真珠红。","烹龙炮凤玉脂泣，罗屏绣幕围香风。","吹龙笛，击鼍鼓，皓齿歌，细腰舞。","况是青春日将暮，桃花乱落如红雨。","劝君终日酩酊醉，酒不到刘伶坟上土。"],"theme":"咏怀抒感","theme2":["讽喻刺世"],"style":"绮丽","style2":["豪放"],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"人生":["青春"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"089b535d-2b28-486b-b58d-d8a3670c83b2","title":"郊庙歌辞 禅社首乐章 顺和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["至哉含柔德，万物资以生。","常顺称厚载，流谦通变盈。","圣心事能察，增广陈厥诚。","黄祇僾如在，泰折俟咸亨。"],"theme":"哲理悟道","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":1.0},{"uid":"2fe129d5-d149-4ff3-acb0-8f50048d8e89","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 五","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹入井，尽是败军情。","或有（京本作「似」）鼠形营上现，忽然交战血成坑，防（京本作「勿」）撃保城营。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cf68f337-d8fc-48a3-b89e-a828d08189a6","title":"喜观即到复题短篇二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["巫峡千山暗，终南万里春。","病中吾见弟，书到汝为人。","意荅儿童问，来经战伐新。","泊船悲喜后，款款话归秦。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放","沉郁"],"mood":"欢愉","mood2":[],"scene":["春","舟","山"],"cats":{"四季":["春天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.65},{"uid":"e16cb386-9a1c-463f-a43f-2110e2a36e33","title":"杂曲歌辞 少年行四首 一","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["新丰美酒斗十千，咸阳游侠多少年。","相逢意气为君饮，系马高楼垂柳边。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["酒","楼"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cpbf297a8f400d71","title":"澡兰香","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。","银瓶露井，彩云窗，往事少年依约。","为当时、曾写榴裙，伤心红绡褪萼。","黍梦光阴渐老，汀洲烟箬。","莫唱江南古调，怨抑难招，楚江沈魄。","薰风燕乳，暗雨梅黄，午镜澡兰帘幕。","念秦楼、也拟人归，应翦菖浦自酌。","但怅望、一屡新蟾，随人天角。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["清新","绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["江","花","江南"],"cats":{"抒情":["伤感","怀古"],"天气":["写云"],"人生":["时光"]},"theme_conf":1.0},{"uid":"884a25ac-d492-45dc-aeb8-d1e7c987ff0a","title":"燕居","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋斋膏沐暇，旭日照轩墀。","露重芭蕉叶，香凝橘柚枝。","简书随吏散，宝骑与僧期。","报国得何力，流年已觉衰。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"c8fd3313-7058-4b9d-9564-7cd94a77a05f","title":"宿远上人兰若","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["香花闭一林，真士此看心。","行道白云近，然灯翠壁深。","梵筵清水月，禅坐冷山阴。","更说东溪好，明朝乘兴寻。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["花","夜","月","山"],"cats":{"人生":["哲理"]},"theme_conf":0.9},{"uid":"bb93206b-92a8-4440-aeb5-4cc3bbe596ea","title":"送僧方及南谒柳员外","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔事庐山远，精舍虎溪东。","朝阳照瀑水，楼阁虹霓中。","骋望羡游云，振衣若秋蓬。","旧房闭松月，远思吟江风。","古寺历头陀，奇峰扳祝融。","南登小桂岭，却望归塞鸿。","衣裓贮文章，自言学雕虫。","抢榆念陵厉，覆篑图穹崇。","远郡多暇日，有诗访禅宫。","石门耸峭绝，竹院含空蒙。","幽响滴岩溜，晴芳飘野丛。","海云悬飓母，山果属狙公。","忽忆吴兴郡，白苹正葱茏。","愿言挹风采，邈若窥华嵩。","桂水夏澜急，火山宵焰红。","三衣濡菌露，一锡飞烟空。","勿谓翻译徒，不为文雅雄。","古来赏音者，燋爨得孤桐。"],"theme":"送别","theme2":["哲理悟道","送别"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"山水":["庐山"],"天气":["彩虹","太阳"],"人生":["哲理"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"c59e8104-e7ec-433d-ae2f-033ba7267993","title":"伤辽东战亡","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凿门初奉律，仗战始临戎。","振鳞方跃浪，骋翼正凌风。","未展六奇术，先亏一篑功。","防身岂乏智，殉命有余忠。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["伤感","悼亡"],"人生":["战争"]},"theme_conf":0.544},{"uid":"8674fa82-1c80-400d-b329-2c6ef1c5fee2","title":"冬日汉江南行将赴夏口途次江陵界寄裴尚书","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五部拥双旌，南依墨客卿。","关山迥梁甸，波浪接湓城。","烟景迷时候，云帆渺去程。","蛤珠冯月吐，芦雁触罗惊。","浦树凝寒晦，江天湛镜清。","赏心随处惬，壮志逐年轻。","舟檝不可驻，提封如任情。","向方曾指路，射策许言兵。","兰渚歇芳意，菱歌非应声。","元戎武昌守，羊祜幸连营。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["江","江南","冬","夏","舟"],"cats":{"四季":["夏天","冬天"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.87},{"uid":"6c7c45a6-c944-4ff3-aa99-f5cb0440436f","title":"赠卫八处士","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生不相见，动如参与商。","今夕复何夕，共此灯烛光。","少壮能几时，鬓发各已苍。","访旧半为鬼，惊呼热中肠。","焉知二十载，重上君子堂。","昔别君未婚，儿女忽成行。","怡然敬父执，问我来何方。","问荅乃未已，儿女罗酒浆。","夜雨剪春韭，新炊间黄粱。","主称会面难，一举累十觞。","十觞亦不醉，感子故意长。","明日隔山岳，世事两茫茫。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["酒"],"cats":{"人生":["青春"]},"theme_conf":0.92},{"uid":"3255bc39-f3ff-4c7b-9ac9-ccc21176db06","title":"送王相公赴范阳","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翊圣衔恩重，频年按节行。","安危皆报国，文武不缘名。","受脤乃调鼎，为霖更洗兵。","幕开丞相阁，旗总贰师营。","料敌知无战，安边示有征。","代云横马首，燕雁拂笳声。","去镇关河静，归看日月明。","欲知瞻恋切，迟暮一书生。"],"theme":"送别","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["鸟","雨","月"],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.484},{"uid":"6358b620-0c4b-4bd3-ae41-b93271318a05","title":"相和歌辞 短歌行二首 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["世人求富贵，多为身嗜欲。","盛衰不自由，得失常相逐。","问君少年日，苦学将干禄。","负笈尘中游，抱书雪前宿。","布衾不周体，藜茄才充腹。","三十登宦途，五十被朝服。","奴温已挟纩，马肥初食粟。","未敢议欢游，尚为名检束。","耳目聋暗后，堂上调丝竹。","牙齿缺落时，盘中堆酒肉。","彼来此已去，外余中不足。","少壮与荣华，相避如寒燠。","青云去地远，白日终天速。","从古无奈何，短歌听一曲。"],"theme":"讽喻刺世","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["欢愉","慷慨"],"scene":["雪","酒"],"cats":{"抒情":["伤感"],"人生":["青春"]},"theme_conf":1.0},{"uid":"26f3fc34-fc1c-41ef-8c59-9b6d1806020e","title":"杂曲歌辞 少年行","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千点斓斒喷玉骢，青丝结尾绣缠騣。","鸣鞭晚出章台路，叶叶春依杨柳风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"b49cb64c-709b-4fc0-bf82-ee616cbdc070","title":"送谢夷甫宰余姚县","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["君去方为宰，干戈尚未销。","邑中残老小，乱后少官僚。","廨宇经兵火，公田没海潮。","到时应变俗，新政满余姚。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"抒情":["感恩"],"人生":["战争"]},"theme_conf":0.7},{"uid":"3806494e-a073-476c-b9e0-bac7f834a4dc","title":"郊庙歌辞 晋昭德成功舞歌 昭德舞歌二首 二","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淮海干戈戢，朝廷礼乐施。","白驹皆就絷，丹凤复来仪。","德备三苗格，风行万国随。","小臣同百兽，率舞贺昌期。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["时光","战争"]},"theme_conf":1.0},{"uid":"6c492d0a-ef0a-4938-8c65-fa50a5de7d5e","title":"宿赞公房","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["杖锡何来此，秋风已飒然。","雨荒深院菊，霜倒半池莲。","放逐宁违性，虚空不离禅。","相逢成夜宿，陇月向人圆。"],"theme":"佛道禅颂","theme2":["山水田园","送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.8},{"uid":"4a61c679-137e-47fb-a94c-dc41ff685ab9","title":"览柏中允兼子姪数人除官制词因述父子兄弟四美载歌丝纶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["纷然丧乱际，见此忠孝门。","蜀中寇亦甚，柏氏功弥存。","深诚补王室，戮力自元昆。","三止锦江沸，独清玉垒昏。","高名入竹帛，新渥照乾坤。","子弟先卒伍，芝兰叠玙璠。","同心注师律，洒血在戎轩。","丝纶实具载，绂冕已殊恩。","奉公举骨肉，诛叛经寒温。","金甲雪犹冻，朱旗尘不飜。","每闻战场说，歘激懦气奔。","圣主国多盗，贤臣官则尊。","方当节钺用，必绝祲沴根。","吾病日回首，云台谁再论。","作歌挹盛事，推毂期孤骞。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","雪"],"cats":{"抒情":["孤独"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.585},{"uid":"21781aca-5d96-4c9e-9bc1-ed8140e1107b","title":"杂曲歌辞 悲哉行","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["悲哉为儒者，力学不能疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦迟。","纵有宦达者，两鬓已成丝。","可怜少壮日，适在穷贱时。","丈夫老且病，焉用富贵为。","沈沈朱门宅，中有乳臭儿。","状貌如妇人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十袭封爵，门承勋戚资。","春来日日出，服御何轻肥。","朝从博徒饮，暮有倡楼期。","评封还酒债，堆金选蛾眉。","声色狗马外，其余一无知。","山苗与涧松，地势随高卑。","古来无奈何，非君独伤悲。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.641},{"uid":"f619ba03-5e1d-497e-af90-2367f48e9c01","title":"杂曲歌辞 昔昔盐 一去无还意","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良人征绝域，一去不言还。","百战攻胡虏，三冬阻玉关。","萧萧边马思，猎猎戍旗闲。","独把千重恨，连年未解颜。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.796},{"uid":"cd904f43-b9eb-4e30-a3fe-f2bcb215a8db","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红似燕支腻如粉，伤心好物不须臾。","山中风起无时节，明日重来得在无。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["清新","婉约"],"mood":"孤寂","mood2":[],"scene":["月","花","山","冬","夏"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["太阳","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.446},{"uid":"02fdb3e2-f9dc-42c6-86cc-7d25e26b7411","title":"送韦邕少府归钟山","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["祈门官罢后，负笈向桃源。","万卷长开帙，千峰不闭门。","绿杨垂野渡，黄鸟傍山村。","念尔能高枕，丹墀会一论。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人生":["读书"]},"theme_conf":0.52},{"uid":"b7dd27c6-0626-42da-a842-380334fadf9a","title":"寄上礼部李侍郎","author":"崔峒","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吴楚相逢处，江湖共泛时。","任风舟去远，待月酒行迟。","白发常同欢，青云本要期。","贵来君却少，秋至老偏悲。","玉佩明朝盛，苍苔陋巷滋。","追寻恨无路，唯有梦相思。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["江","舟","酒","秋","月"],"cats":{"抒情":["思念"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"bda39e90-fcb0-4a37-8565-a8b31a46681f","title":"谒文公上方","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["野寺隐乔木，山僧高下居。","石门日色异，绛气横扶疎。","窈窕入风磴，长芦纷卷舒。","庭前猛虎卧，遂得文公庐。","俯视万家邑，烟尘对阶除。","吾师雨花外，不下十年余。","长者自布金，禅龛只晏如。","大珠脱玷翳，白月当空虚。","甫也南北人，芜蔓少耘锄。","久遭诗酒污，何事忝簪裾。","王侯与蝼蚁，同尽随丘墟。","愿闻第一义，回向心地初。","金篦刮眼膜，价重百车渠。","无生有汲引，兹理傥吹嘘。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["酒"],"cats":{"人生":["哲理"]},"theme_conf":0.96},{"uid":"519750da-fa09-4e97-a520-42a78269efaf","title":"山春洞","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["引烛踏仙泥，时时乱乳燕。","不知何道士，手把灵书卷。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"96964fe2-9087-42a4-abe9-87cc8e846c59","title":"唐明堂乐章 皇帝行","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["仰膺历数，俯顺讴歌。","远安迩肃，俗阜时和。","化光玉镜，讼息金科。","方兴典礼，永戢干戈。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["战争"]},"theme_conf":0.521},{"uid":"02c923a2-c7b4-4464-a46c-e5e4a1156933","title":"重游木兰亭","author":"徐铉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["缭绕长隄带碧浔，昔年游此尚青衿。","兰桡破浪城阴直，玉勒穿花苑树深。","宦路尘埃成久别，仙家风景有谁寻。","那知年长多情后，重凭栏干一独吟。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["楼"],"cats":{"抒情":["孤独"],"人生":["励志"]},"theme_conf":1.0},{"uid":"0cc77a07-c1db-4875-9e12-9574e51aab15","title":"荆南兵马使太常卿赵公大食刀歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["太常楼船声嗷嘈，问兵刮寇趋下牢。","牧出令奔飞百艘，猛蛟突兽纷腾逃。","白帝寒城驻锦袍，玄冬示我胡国刀。","壮士短衣头虎毛，凭轩拔鞘天为高。","翻风转日木怒号，冰翼雪澹伤哀猱。","镌错碧甖䴙鹈膏，铓锷已莹虚秋涛。","鬼物撇捩辞坑壕，苍水使者扪赤条。","龙伯国人罢钓鼇，芮公回首颜色劳。","分阃救世用贤豪，赵公玉立高歌起。","揽环结佩相终始，万岁持之护天子。","得君乱丝与君理，蜀江如线如针水。","荆岑弹丸心未已，贼臣恶子休干纪。","魑魅魍魉徒为耳，妖腰乱领敢欣喜。","用之不高亦不庳，不似长劒须天倚。","吁嗟光禄英雄弭，大食宝刀聊可比。","丹青宛转麒麟里，光芒六合无泥滓。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨","幽峭"],"mood":"慷慨","mood2":[],"scene":["冬","楼"],"cats":{"四季":["冬天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.805},{"uid":"26a0266d-313c-4911-b629-2418556d1b03","title":"洗兵马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["中兴诸将收山东，捷书日报清昼同。","河广传闻一苇过，胡危命在破竹中。","祗残邺城不日得，独任朔方无限功。","京师皆骑汗血马，回纥喂肉葡萄宫。","已喜皇威清海岱，常思仙仗过崆峒。","三年笛里关山月，万国兵前草木风。","成王功大心转小，郭相谋深古来少。","司徒清鉴悬明镜，尚书气与秋天杳。","二三豪俊为时出，整顿乾坤济时了。","东走无复忆鲈鱼，南飞觉有安巢鸟。","青春复随冠冕入，紫禁正耐烟花绕。","鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。","攀龙附凤势莫当，天下尽化为侯王。","汝等岂知蒙帝力，时来不得夸身强。","关中既留萧丞相，幕下复用张子房。","张公一生江海客，身长九尺须眉苍。","征起适遇风云会，扶颠始知筹策良。","青袍白马更何有，后汉今周喜再昌。","寸地尺天皆入贡，奇祥异瑞争来送。","不知何国致白环，复道诸山得银瓮。","隐士休歌紫芝曲，词人解撰河清颂。","田家望望惜雨干，布谷处处催春种。","淇上健儿归莫嬾，城南思妇愁多梦。","安得壮士挽天河，净洗甲兵长不用。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["旷达","清新"],"mood":"欢愉","mood2":["相思"],"scene":["鸟","春"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["青春","战争"],"动物":["写马"]},"theme_conf":0.43},{"uid":"3f8f27c5-2e3f-42e7-8238-4be04f1e2849","title":"故人寄茶","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["劒外九华英，缄题下玉京。","开时微月上，碾处乱泉声。","半夜邀僧至，孤吟对竹烹。","碧流霞脚碎，香泛乳花轻。","六腑睡神去，数朝诗思清。","其余不敢费，留伴读书行。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花","月","夜"],"cats":{"抒情":["友情","孤独"],"人生":["读书"],"食物":["写茶"]},"theme_conf":0.88},{"uid":"6bb1ee39-265a-4c53-a5b4-311b2e65429c","title":"和荅弟志和渔父歌","author":"张松龄","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乐是风波钓是闲，草堂松径已胜攀。","太湖水，洞庭山，狂风浪起且须还。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["江"],"cats":{"天气":["写风"],"人物":["父亲"],"人生":["梦想"]},"theme_conf":0.598},{"uid":"276d7c1f-d89d-48fd-a8f5-777b9efd9d23","title":"酬秘书弟兼寄幕下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["亚相膺时杰，群才遇良工。","翩翩幕下来，拜赐甘泉宫。","信知命世奇，适会非常功。","侍御执邦宪，清词焕春丛。","末路望绣衣，他时常发蒙。","孰云三军壮，惧我弹射雄。","谁谓万里遥，在我樽俎中。","光禄经济器，精微自深衷。","前席屡荣问，长城兼在躬。","高纵激颓波，逸翮驰苍穹。","将副节制筹，欲令沙漠空。","司业志应徐，雅度思冲融。","相思三十年，忆昨犹儿童。","今来抱青紫，忽若披鹓鸿。","说劒增慷慨，论交持始终。","秘书即吾门，虚白无不通。","多才陆平原，硕学郑司农。","献封到关西，独步归山东。","永意久知处，嘉言能亢宗。","客从梁宋来，行役随转蓬。","酬赠欣元弟，忆贤瞻数公。","游鳞戏沧浪，鸣凤栖梧桐。","并负垂天翼，俱乘破浪风。","眈眈天府间，偃仰谁敢同。","何意搆广厦，翻然顾雕虫。","应知阮步兵，惆怅此途穷。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["塞外"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["励志"]},"theme_conf":0.95},{"uid":"7247095c-ceeb-44e4-91e6-663aa7d504f5","title":"桂州岁暮","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁暮天涯客，寒窗欲晓时。","君恩空自感，乡思梦先知。","重谊人愁别，惊栖鹊恋枝。","不堪楼上角，南向海风吹。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["月","楼"],"cats":{"抒情":["思乡","伤感"],"人生":["读书"]},"theme_conf":0.676},{"uid":"d7732963-08cf-49ca-b903-6e954401ea56","title":"宿湖边山寺","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["群峰过雨涧淙淙，松下扉扃白鹤双。","香透经窗笼桧栢，云生梵宇湿旛幢。","蒲团僧定风过席，苇岸渔歌月堕江。","谁悟此生同寂灭，老禅慧力得心降。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江"],"cats":{"人生":["哲理"]},"theme_conf":0.9},{"uid":"04c4e10d-6c09-4fc2-a702-b55dbba16ee4","title":"喜雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春旱天地昏，日色赤如血。","农事都已休，兵戈况骚屑。","巴人困军须，恸哭厚土热。","沧江夜来雨，真宰罪一雪。","谷根小苏息，沴气终不灭。","何由见宁岁，解我忧思结。","峥嵘群山云，交会未断绝。","安得鞭雷公，滂沱洗吴越。"],"theme":"边塞征战","theme2":["山水田园"],"style":"沉郁","style2":["雄浑"],"mood":"悲怆","mood2":["欢愉"],"scene":["雨","江南"],"cats":{"天气":["写雨"],"人生":["战争"]},"theme_conf":0.522},{"uid":"1f6ef42b-eb0a-49f8-971b-d59a58ec6239","title":"百丈谿新理茅茨读书","author":"阎防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浪迹弃人世，远山自幽独。","始傍巢由踪，吾其获心曲。","荒庭何所有，老树半空腹。","秋蜩鸣北林，暮鸟穿我屋。","栖迟乐遵渚，恬旷寡所欲。","开卦推盈虚，散帙攻节目。","养闲度人事，达命知止足。","不学东周儒，俟时劳伐辐。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.9},{"uid":"b458468f-a5c3-44a5-aa38-29e8ab8f3533","title":"酬别薛三蔡大留简韩十四主簿","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迢递辞京华，辛勤异乡县。","登高俯沧海，廻首泪如霰。","同人久离别，失路还相见。","薛侯怀直道，德业应时选。","蔡子负清才，当年擢宾荐。","韩公有奇节，词赋凌群彦。","读书嵩岑间，作吏沧海甸。","伊余寡栖托，感激多愠见。","纵诞非尔情，飘沦任疵贱。","忽枉琼瑶作，乃深平生眷。","始谓吾道存，终嗟客游倦。","归心无昼夜，别事除言宴。","复值凉风时，苍茫夏云变。"],"theme":"送别","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["雪","夏","江","重阳"],"cats":{"抒情":["离别","思乡"],"四季":["夏天"],"人生":["读书"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"cp1018b391d4cfee","title":"六丑","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["正单衣试酒，恨客里、光阴虚掷。","愿春暂留，春归如过翼。","一去无迹。","为问花何在，夜来风雨，葬楚宫倾国。","钗钿堕处遗香泽。","乱点桃蹊，轻翻柳陌。","多情为谁追惜。","但蜂媒蝶使，时叩窗隔。","东园岑寂。","渐蒙笼暗碧。","静绕珍丛底，成叹息。","长条故惹行客。","似牵衣待话，别情无极。","残英小、强簪巾帻。","终不似一朵，钗头颤袅，向人侧。","漂流处、莫趁潮汐。","恐断红、尚有相思字，何由见得。"],"theme":"咏物","theme2":["爱情相思","羁旅思乡","送别"],"style":"沉郁","style2":["冲淡","婉约"],"mood":"相思","mood2":["孤寂"],"scene":["雨","花","春","酒"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.93},{"uid":"051a325b-0ad3-42b1-89dc-8c9d09cf45d5","title":"相和歌辞 苦寒行","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严寒动八荒，莿莿无休时。","阳乌不自暖，雪压扶桑枝。","岁暮寒益壮，青春安得归。","朔雁到南海，越禽何处飞？","谁言贫士叹，不为身无衣。"],"theme":"民生疾苦","theme2":["羁旅思乡"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["孤寂","慷慨"],"scene":["雪","春","鸟","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.51},{"uid":"4be77185-992e-4614-9746-de2e73c8a3c3","title":"关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","[戍]客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"5dd824cf-e4bc-4a99-a85a-48e2688ebbb2","title":"横吹曲辞 入塞曲 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["单于烽火动，都护去天涯。","别赐黄金甲，亲临白玉墀。","塞垣须静谧，师旅审安危。","定远条支宠，如今胜古时。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.708},{"uid":"29caf0d7-6d84-4b60-975d-d2acce3b89e4","title":"喜辱韩十四郎中书兼封近诗示代书题赠","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["各牵于役间游遨，独坐相思正郁陶。","长跪读书心𫏐缓，短章投我曲何高。","宦情缘木知非愿，王事敦人敢告劳。","所叹在官成远别，徒言岏水才容舠。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["相思","欢愉"],"scene":[],"cats":{"抒情":["思念","孤独"],"人生":["读书"]},"theme_conf":0.95},{"uid":"03a00289-c6dd-427b-98d4-1432aaabcbd2","title":"鼓吹曲辞 鼓吹铙歌 战武牢","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["战武牢，动河朔。","逆之助，图掎角。","怒鷇麛，抗乔岳。","翘萌牙，傲霜雹。","王谋内定，申掌握。","铺施芟夷，二主缚。","惮华戎，廓封略。","命之瞢，卑以斮。","归有德，唯先觉。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"人生":["战争"]},"theme_conf":1.0},{"uid":"d76f7632-9926-40d4-8ac2-497f7ca08223","title":"安邑里中秋怀寄高员外","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["原宪素非贫，嵇康自寡欲。","守道识通穷，达命齐荣辱。","庭梧变葱蒨，篱菊扬芳馥。","坠叶翻夕霜，高堂瞬华烛。","况兹寒夜永，复叹流年促。","感物思殷勤，怀贤心踯躅。","雄词封禅草，丽句阳春曲。","高德十年兄，异才千里足。","咫尺邈雪霜，相望如琼玉。","欲识岁寒心，松筠更秋绿。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["秋","中秋","雪"],"cats":{"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"c5082a98-967f-45dd-aa62-6a0217f71d65","title":"见上林春鴈翔青云寄杨起居李员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上林春更好，宾鴈不知归。","顾影怜青籞，传声入紫微。","夜陪池鹭宿，朝出苑花飞。","宁忆寒乡侣，鸾凰一见稀。"],"theme":"咏物","theme2":["山水田园","羁旅思乡"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.78},{"uid":"262d09ef-c986-4c06-81a4-9a75c6d83719","title":"岳阳楼别窦司直","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["洞庭九州间，厥大谁与让。","南汇群崖水，北注何奔放。","潴为七百里，吞纳各殊状。","自古澄不清，环混无归向。","炎风日搜搅，幽怪多冗长。","轩然大波起，宇宙隘而妨。","巍峩拔嵩华，腾踔较健壮。","声音一何宏，轰輵车万两。","犹疑帝轩辕，张乐就空旷。","蛟螭露笋簴，缟练吹组帐。","鬼神非人世，节奏颇跌踼。","阳施见夸丽，阴闭感凄怆。","朝过宜春口，极北缺隄障。","夜缆巴陵洲，丛芮才可傍。","星河尽涵泳，俯仰迷下上。","余澜怒不已，喧聒鸣瓮盎。","明登岳阳楼，辉焕朝日亮。","飞廉戢其威，清晏息纤纩。","泓澄湛凝绿，物影巧相况。","江豚时出戏，惊波忽荡瀁。","时当冬之孟，隙窍缩寒涨。","前临指近岸，侧坐眇难望。","涤濯神魂醒，幽怀舒以畅。","主人孩童旧，握手乍忻怅。","怜我窜逐归，相见得无恙。","开筵交履舃，烂漫倒家酿。","杯行无留停，高柱送清唱。","中盘进橙栗，投掷倾脯酱。","欢穷悲心生，婉娈不能忘。","念昔始读书，志欲干霸王。","屠龙破千金，为艺亦云亢。","爱才不择行，触事得谗谤。","前年出官由，此祸最无妄。","公卿采虚名，擢拜识天仗。","奸猜畏弹射，斥逐恣欺诳。","新恩移府庭，逼侧厕诸将。","于嗟苦驽缓，但惧失宜当。","追思南渡时，鱼腹甘所葬。","严程迫风帆，劈箭入高浪。","颠沈在须臾，忠鲠谁复谅。","生还真可喜，尅己自惩创。","庶从今日后，粗识得与丧。","事多改前好，趣有获新尚。","誓耕十亩田，不取万乘相。","细君知蚕织，稚子已能饷。","行当挂其冠，生死君一访。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":["慷慨","悲怆"],"scene":["楼","江"],"cats":{"抒情":["离别","伤感"],"天气":["星星"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.467},{"uid":"b0d04448-935e-4e7a-ad7e-9a69c31b0ad7","title":"阆水歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["嘉陵江色何所似，石黛碧玉相因依。","正怜日破浪花出，更复春从沙际归。","巴童荡桨攲侧过，水鸡衔鱼来去飞。","阆中胜事可肠断，阆州城南天下稀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["春","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"d8e0db16-f56c-4180-bc8f-9724551bd8fc","title":"横吹曲辞 前出塞九首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["磨刀呜咽水，水赤刃伤手。","欲轻肠断声，心绪乱已久。","丈夫誓许国，愤惋复何有？","功名图麒麟，战骨当速朽。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"3383ff3c-b6bf-44b6-900a-766acc558644","title":"王兵马使二角鹰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["悲台萧飒石巃嵸，哀壑杈枒浩呼汹。","中有万里之长江，回风滔日孤光动。","角鹰飜倒壮士臂，将军玉帐轩翠气。","二鹰猛脑徐侯穟，目如愁胡视天地。","杉鸡竹兔不自惜，溪虎野羊俱辟易。","鞲上锋棱十二翮，将军勇锐与之敌。","将军树勋起安西，昆仑虞泉入马蹄。","白羽曾肉三狻猊，敢决岂不与之齐。","荆南芮公得将军，亦如角鹰下翔云。","恶鸟飞飞啄金屋，安得尔辈开其群，驱出六合枭鸾分。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["伤感"],"山水":["长江"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.518},{"uid":"1d096967-8741-47e1-99f9-41e41c03f829","title":"闻惠二过东溪特一送","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["惠子白驹瘦，归溪唯病身。","皇天无老眼，空谷滞斯人。","崖蜜松花熟，山杯竹叶新。","柴门了无事，黄绮未称臣。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["幽峭","绮丽"],"mood":"恬淡","mood2":[],"scene":["山","酒"],"cats":{"人生":["时光"]},"theme_conf":0.528},{"uid":"1a2571ec-f313-41ac-9a3b-695ebd446b8d","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 七","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓见，更或似弓形。","有若晕来如断续，兵兴五日定（辛本、川本作「便」）回程。","久住必灾成。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"b795db08-a132-4d2c-9925-654193077602","title":"喜弟淑再至为长歌","author":"李渤","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前年别时秋九月，白露吹霜金吹烈。","离鸿一别影初分，泪袖双挥心哽咽。","别来几度得音书，南岳知□□□□。","庐山峨峨倚天碧，捧排空崖千万尺。","社牓长题高士名，食堂每记云山迹。","我本开云此山住，偶为名利相萦误。","自负心机四十年，羞闻社客山中篇。","忧时魂梦忆归路，觉来疑在林中眠。","昨日亭前乌鹊喜，果得今朝尔来此。","吾吟行路五十篇，尽说江南数千里。","自怜兄弟今五人，共萦儒素家尚贫。","虽然廪饩各不一，就中总免拘常伦。","长兄年少曾落托，拔劒沙场随卫霍。","口里虽谭周孔文，怀中不舍孙吴略。","次兄一生能苦节，夏聚流萤冬映雪。","非论疾恶志如霜，更觉临泉心似铁。","第三之兄更奇异，昂昂独负青云志。","下看金玉不如泥，肯道王侯身可贵。","却愁清逸不干时，高踪大器无人知。","倘逢感激许然诺，必能万古留清规。","念尔年来方二十，夙夜孜孜能独立。","卷中笔落星汉摇，洞里丹灵鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间谈笑多相妨。","广海青山殊未足，逢著高楼还醉宿。","朝走安公枥上驹，暮伦陶令篱边菊。","近来诗思殊无况，苦被时流不相放。","云腾浪走势未衰，鹤膝蜂腰岂能障。","送尔为文殊不识，贵从一一传胷臆。","若到湖南见紫霄，会须待我同攀陟。"],"theme":"亲情","theme2":["山水田园","边塞征战"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["山","江南","秋","冬","雪","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["秋天","冬天"],"山水":["庐山"],"人生":["励志","梦想","战争"],"生活":["边塞"]},"theme_conf":0.95},{"uid":"08a8ab7b-fb84-4a05-8b4e-177f2728bdbf","title":"和浙西李大夫晚下北固山喜径松成阴怅然怀古偶题临江亭幷浙东元相公所和依本韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一辞温室树，几见武昌柳。","荀谢年何少，韦平望已久。","种松夹石道，纡组临沙阜。","目览帝王州，心存股肱守。","叶动惊彩翰，波澄见頳首。","晋宋齐梁都，千山万江口。","烟散隋宫出，涛来海门吼。","风俗太伯余，衣冠永嘉后。","江长天作限，山固壤无朽。","自古称佳丽，非贤谁奄有。","八元邦族盛，万石门风厚。","天柱揭东溟，文星照北斗。","高亭一骋望，举酒共为寿。","因赋咏怀诗，远寄同心友。","禁中晨夜直，江左东西偶。","将手握兵符，儒腰盘贵绶。","颁条风有自，立事言无苟。","农野闻让耕，军人不使酒。","用材当构厦，知道宁窥牖。","谁谓青云高，鹏飞终背负。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["江","山","楼"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["星星"],"人生":["梦想"]},"theme_conf":0.383},{"uid":"1365c1c9-e864-4920-ba10-d3815a59f6b7","title":"春日思归","author":"李频","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春情不断若连环，一夕思归鬓欲斑。","壮志未酬三尺劒，故乡空隔万重山。","音书断绝干戈后，亲友相逢梦寐间。","却羡浮云与飞鸟，因风吹去又吹还。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.718},{"uid":"a9c061a4-c957-4d74-a0f3-86001d8b2a7f","title":"杂曲歌辞 少年行四首 二","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["家本清河住五城，须凭弓箭得功名。","等闲飞鞚秋原上，独向寒云试射声。"],"theme":"羁旅思乡","theme2":["边塞征战","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡","慷慨"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.387},{"uid":"0613f575-4f07-4326-8591-603fb3d1da45","title":"秦中感秋寄远上人","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["庐山"],"人生":["励志","梦想"]},"theme_conf":0.82},{"uid":"35b3a0df-11b4-46ae-bc44-f58f19a51447","title":"题精舍寺","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["石林精舍武溪东，夜扣禅关谒远公。","月在上方诸品静，僧持半偈万缘空。","秋山竟日闻猨啸，落木寒泉听不穷。","惟有双峰最高顶，此心期与故人同。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":["幽峭"],"mood":"孤寂","mood2":["恬淡"],"scene":["山","秋","夜","月"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.66},{"uid":"f3e3dab9-6df9-4bc1-b428-ace90e3a922c","title":"杂曲歌辞 结客少年场行","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长安重游侠，洛阳富才雄。","玉劒浮云骑，金鞍明月弓。","鬬鸡过渭北，走马向关东。","孙宾遥见待，郭解暗相通。","不受千金爵，谁论万里功。","将军下天上，虏骑入云中。","烽火夜似月，兵气晓成虹。","横行徇知己，负羽远从戎。","龙旌昏朔雾，鸟阵卷寒风。","追奔瀚海咽，战罢阴山空。","归来谢天子，何如马上翁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","冲淡"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.711},{"uid":"f3c09e9e-e471-4489-9d3f-a598832ac638","title":"悲陈陶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孟冬十郡良家子，血作陈陶泽中水。","野旷天清无战声，四万义军同日死。","群胡归来血洗箭，仍唱胡歌饮都市。","都人回面北向啼，日夜更望官军至。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"6beb5cc2-ae49-4e23-952a-1cb92fa11512","title":"望蓟门","author":"祖咏","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["燕台一望客心惊，箫鼓喧喧汉将营。","万里寒光生积雪，三边曙色动危旌。","沙场烽火连胡月，海畔云山拥蓟城。","少小虽非投笔吏，论功还欲请长缨。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.842},{"uid":"6711c65c-3dc9-4a48-bfe6-d5e2dfe66dac","title":"送廖融处士南游","author":"翁宏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["病卧瘴云间，莓苔渍竹关。","孤吟牛渚月，老忆洞庭山。","壮志潜消尽，淳风竟未还。","今朝忽相遇，执手一开颜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨","相思"],"scene":["江"],"cats":{"抒情":["思念","孤独"],"人生":["励志","梦想"]},"theme_conf":0.648},{"uid":"7ff83e4f-cf78-4123-8a0c-4e39cb867020","title":"惜花吟","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["枝上花，花下人，可怜颜色俱青春。","昨日看花花灼灼，今朝看花花欲落。","不如尽此花下欢，莫待春风总吹却。","莺歌蝶舞韶光长，红炉煑茗松花香。","妆成罢吟恣游后，独把芳枝归洞房。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["孤独","闺怨"],"人生":["青春"]},"theme_conf":1.0},{"uid":"dd4c60cf-6385-48a0-86b2-2020cdf70f36","title":"青云干吕 二","author":"彭伉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣布中区化，祥符异域云。","含春初应吕，晕碧已成文。","东起随风暖，西流共日曛。","升时嘉异月，为庆等凝汾。","轻与晴烟比，高将晓雾分。","飘飘如可致，愿此翊明君。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","月"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"8551389a-8251-4516-80e0-9247893493ca","title":"乌江女","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["越艳谁家女，朝游江岸傍。","青春犹未嫁，红粉旧来娼。","锦袖盛朱橘，银钩摘紫房。","见人羞不语，回艇入溪藏。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"人生":["青春"]},"theme_conf":1.0},{"uid":"c27559b0-f98d-4b5f-a239-f5ec7cb33f71","title":"漫成二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江臯已仲春，花下复清晨。","仰面贪看鸟，回头错应人。","读书难字过，对酒满壶频。","近识峨眉老，知予嬾是真。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":0.92},{"uid":"8b41c002-e220-45f6-b816-c8f499e39622","title":"述梦诗四十韵","author":"李德裕","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赋命诚非薄，良时幸已遭。","君当尧舜日，官接凤皇曹。","目睇烟霄阔，心惊羽翼高。","椅梧连鹤禁，壀堄接龙韬。","我后怜词客，吾僚并隽髦。","著书同陆贾，待诏比王褒。","重价连悬璧，英词淬宝刀。","泉流初落涧，露滴更濡毫。","赤豹欣来献，彤弓喜暂櫜非烟含瑞气，驯雉洁霜毛。","静室便幽独，虚楼散郁陶。","花光晨艳艳，松韵晚骚骚。","画壁看飞鹤，仙图见巨鼇。","倚簷阴药树，落格蔓蒲桃。","荷静蓬池鲙，冰寒郢水醪。","荔枝来自远，卢橘赐仍叨。","麝气随兰泽，霜华入杏膏。","恩光惟觉重，携挈未为劳。","夕阅梨园骑，宵闻禁杖獒。","扇回交彩翟，雕起飏银绦。","辔待袁丝揽，书期蜀客操。","尽规常謇謇，退食尚忉忉。","龟顾垂金钮，鸾飞曳锦袍。","御沟杨柳弱，天廐骕骦豪。","屡换青春直，闲随上苑遨。","烟低行殿竹，风拆绕墙桃。","聚散俄成昔，悲愁益自熬。","每怀仙驾远，更望茂陵号。","地接三茅岭，川迎伍子涛。","花迷瓜步暗，石固蒜山牢。","兰野凝香管，梅洲动翠篙。","泉鱼惊彩妓，溪鸟避干旄。","感旧心犹绝，思归首更搔。","无聊燃[蜜]炬，谁复劝金舠。","岚气朝生栋，城阴夜入濠。","望烟归海峤，送鴈渡江臯。","宛马嘶寒枥，吴钩在锦弢。","未能追狡兔，空觉长黄蒿。","水国逾千里，风帆过万艘。","阅川终古恨，惟见暮滔滔。"],"theme":"咏怀抒感","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["夜","鸟","园林","山","江"],"cats":{"抒情":["思乡","伤感","孤独"],"人生":["青春"],"食物":["荔枝"]},"theme_conf":0.78},{"uid":"c92216ac-114d-4bda-9c55-89688840f5b0","title":"薄命篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔住邯郸年尚少，只是娇羞弄花鸟。","青楼碧纱大道边，绿杨日暮风褭褭。","婵娟玉貌二八余，自怜颜色花不如。","丽质全胜秦氏女，藁砧宁用专城居。","岁去年来年渐长，青春红粉全堪赏。","玉楼珠箔但闲居，南陌东城讵来往。","韶光日日看渐迟，[摽]梅既落行有时。","宁知燕赵娉婷子，翻嫁幽幷游侠儿。","年年结束青丝骑，出门一去何时至。","秋月空悬翡翠帘，春帏嬾卧鸳鸯被。","沙塞经时不寄书，深闺愁独意何如。","花前拭泪情无限，月下调琴恨有余。","离别苦多相见少，洞房愁梦何由晓。","闲看双燕泪霏霏，静对空床魂悄悄。","镜里红颜不自禁，陌头香骑动春心。","为问佳期早晚是，人人总解有黄金。"],"theme":"闺情宫怨","theme2":["送别","闺情宫怨","爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","秋","鸟","春","塞外","中秋"],"cats":{"抒情":["爱情","离别","伤感","闺怨"],"四季":["春天","秋天"],"天气":["月亮"],"人生":["青春"],"节日":["中秋节"]},"theme_conf":0.96},{"uid":"202641be-8d53-4de4-b477-fcbef11c89bf","title":"种白蘘荷","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["血虫化为疠，夷俗多所神。","衔猜每腊毒，谋富不为仁。","蔬果自远至，杯酒盈肆陈。","言甘中必苦，何用知其真。","华洁事外饰，尤病中州人。","钱刀恐贾害，饥至益逡巡。","窜伏常战栗，怀故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂灵编，言此殊足珍。","崎岖乃有得，托以全余身。","纷敷碧树阴，眄睐心所亲。"],"theme":"讽喻刺世","theme2":["民生疾苦","边塞征战","咏物"],"style":"沉郁","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"],"人生":["战争"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"94fe7344-b244-4341-8887-e717c373c9a2","title":"杂曲歌辞 少年行三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫笑田家老瓦盆，自从盛酒长儿孙。","倾银注瓦惊人眼，共醉终同卧竹根。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.394},{"uid":"c9747409-7db3-4600-8a85-90465a503b29","title":"寄续尊师","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["得道任发白，亦逢城市游。","新经天上取，稀药洞中收。","春木带枯叶，新蒲生漫流。","年年望灵鹤，常在此山头。"],"theme":"佛道禅颂","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":0.9},{"uid":"362e9ec3-e452-4f59-b5f4-10757da34b28","title":"杂曲歌辞 妾薄命","author":"刘元淑","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自从离别守空闺，遥闻征战起云梯。","夜夜愁君辽海外，年年弃妾渭桥西。","阳春白日照空暖，紫燕衔花向庭满。","彩鸾琴里怨声多，飞鹊镜前妆梳断。","谁家夫壻不从征，应是渔阳别有情。","莫道红颜燕地少，家家还似洛阳城。","且逐新人殊未归，还令秋至夜霜飞。","北斗星前横度鴈，南楼月下捣寒衣。","夜深闻鴈肠欲绝，独坐缝衣灯又灭。","暗啼罗帐空自怜，梦度阳关向谁说。","每怜容貌宛如神，如何薄命不胜人。","愿君朝夕燕山至，好作明年杨柳春。"],"theme":"闺情宫怨","theme2":["送别","边塞征战"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","秋","鸟","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天","秋天"],"天气":["星星"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.354},{"uid":"cpa4d238ecabd1f0","title":"高阳台","author":"韩","dynasty":"宋","section":"宋词","form":"词","paragraphs":["频听银签，重燃绛蜡，年华衮衮惊心。","饯旧迎新，能消几刻光阴。","老来可惯通宵饮，待不眠、还怕寒侵。","掩清尊。","多谢梅花，伴我微吟。","邻娃已试春妆了，更蜂腰簇翠，燕股横金。","勾引东风，也知芳思难禁。","朱颜那有年年好，逞艳游、赢取如今。","恣登临。","残雪楼台，迟日园林。"],"theme":"送别","theme2":[],"style":"清新","style2":["绮丽","沉郁"],"mood":"惆怅","mood2":[],"scene":["楼","春"],"cats":{"四季":["春天"],"人生":["青春","时光"]},"theme_conf":1.0},{"uid":"110ea489-e0f3-40c3-8bd1-39936729a6cf","title":"冬夜题旅馆","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["退飞忆林薮，乐业羡黎庶。","四海尽穷途，一枝无宿处。","严冬北风急，中夜哀鸿去。","孤烛思何深，寒窗坐难曙。","劳歌待明发，惆怅盈百虑。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"豪放","style2":["悲慨"],"mood":"相思","mood2":["孤寂","惆怅"],"scene":["冬","夜"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.624},{"uid":"ea82076e-44f8-4d9c-8844-a2325b642224","title":"题鹤林寺","author":"薛据","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["道门隐形胜，向背临法桥。","松覆山殿冷，花藏溪路遥。","珊珊宝幡挂，燄燄明灯烧。","迟日半空谷，春风连上潮。","少凭水木兴，暂忝身心调。","愿谢携手客，兹山禅侣饶。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","春","山","江"],"cats":{"四季":["春天"],"人生":["哲理"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.533},{"uid":"5a194d8f-5981-4036-9da1-dc6e3cedf4f9","title":"杂曲歌辞 少年行四首 一","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["少小边州惯放狂，骣骑蕃马射黄羊。","如今年事无筋力，犹倚营门数鴈行。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"ad25550b-b0b6-49cd-981a-88d90471b624","title":"寄彭州高三十五使君适虢州岑二十七长史参三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故人何寂寞，今我独凄凉。","老去才难尽，秋来兴甚长。","物情尤可见，辞客未能忘。","海内知名士，云端各异方。","高岑殊缓步，沈鲍得同行。","意惬关飞动，篇终接混茫。","举天悲富骆，近代惜卢王。","似尔官仍贵，前贤命可伤。","诸侯非弃掷，半刺已翱翔。","诗好几时见，书成无信将。","男儿行处是，客子鬬身强。","羁旅推贤圣，沈绵抵咎殃。","三年犹疟疾，一鬼不销亡。","隔日搜脂髓，增寒抱雪霜。","徒然潜隙地，有腼屡鲜妆。","何太龙钟极，于今出处妨。","无钱居帝里，尽室在边疆。","刘表虽遗恨，庞公至死藏。","心微傍鱼鸟，肉瘦怯豺狼。","陇草萧萧白，洮云片片黄。","彭门劒阁外，虢略鼎湖旁。","荆玉簪头冷，巴笺染翰光。","乌麻蒸续晒，丹橘露应尝。","岂异神仙宅，俱兼山水乡。","竹斋烧药灶，花屿读书床。","更得清新否，遥知对属忙。","旧宫宁改汉，淳俗本归唐。","济世宜公等，安贫亦士常。","蚩尤终戮辱，胡羯漫猖狂。","会待祅氛静，论文暂裹粮。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":["孤寂","悲怆"],"scene":["秋","雪"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.373},{"uid":"7e29d72b-7386-48c6-af3c-9dafd02f0665","title":"木兰歌","author":"韦元甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["木兰抱杼嗟，借问复为谁。","欲闻所戚戚，感激彊其颜。","老父隶兵籍，气力日衰耗。","岂足万里行，有子复尚少。","胡沙没马足，朔风裂人肤。","老父旧羸病，何以彊自扶。","木兰代父去，秣马备戎行。","易却纨绮裳，洗却铅粉妆。","驰马赴军幕，慷慨携干将。","朝屯雪山下，暮宿青海傍。","夜袭燕支虏，更携于阗羌。","将军得胜归，士卒还故乡。","父母见木兰，喜极成悲伤。","木兰能承父母颜，却卸巾鞲理丝簧。","昔为烈士雄，今为娇子容。","亲戚持酒贺父母，始知生女与男同。","门前旧军都，十年共崎岖。","本结弟兄交，死战誓不渝。","今者见木兰，言声虽是颜貌殊。","惊愕不敢前，叹息徒嘻吁。","世有臣子心，能如木兰节。","忠孝两不渝，千古之名焉可灭。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放","悲慨"],"mood":"悲怆","mood2":["慷慨"],"scene":["冬","夜","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"天气":["写风"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.668},{"uid":"d2cb0132-c27d-4037-abb6-c76f576b866b","title":"送顾八分文学适洪吉州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["中郎石经后，八分盖顦顇。","愿侯运𬬻锤，笔力破余地。","昔在开元中，韩蔡同赑屭。","玄宗妙其书，是以数子至。","御札早流传，揄扬非造次。","三人竝入直，恩泽各不二。","愿于韩蔡内，辨眼工小字。","分日示诸王，钩深法更秘。","文学与我游，萧疎外声利。","追随二十载，浩荡长安醉。","高歌卿相宅，文翰飞省寺。","视我扬马间，白首不相弃。","骅骝入穷巷，必脱黄金辔。","一论朋友难，迟暮敢失坠。","古来事反复，相见横涕泗。","向者玉珂人，谁是青云器。","才尽伤形体，病渴污官位。","故旧独依然，时危话颠踬。","我甘多病老，子负忧世志。","胡为困衣食，颜色少称遂。","远作辛苦行，顺从众多意。","舟檝无根蔕，蛟鼍好为祟。","况兼水贼繁，特戒风飙驶。","崩腾戎马际，往往杀长吏。","子干东诸侯，劝勉防纵恣。","邦以民为本，鱼饥费香饵。","请哀疮痍深，告诉皇华使。","使臣精所择，进德知历试。","恻隐诛求情，固应贤愚异。","列士恶苟得，俊杰思自致。","赠子猛虎行，出效载酸鼻。"],"theme":"送别","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.477},{"uid":"3a4f111b-6ab4-4457-9021-8c216f44ddf7","title":"寄终南真空禅师","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闲想白云外，了然清净僧。","松门山半寺，夜雨佛前灯。","此境可长住，浮生自不能。","一从林下别，瀑布几成冰。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["夜","雨"],"cats":{"山水":["瀑布"],"人生":["哲理"]},"theme_conf":0.85},{"uid":"31bcaea7-a3c1-47a0-a1d3-eb91a703d1fb","title":"赠杜二拾遗","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["传道招[提]客，诗书自讨论。","佛香时入院，僧饭屡过门。","听法还应难，寻经剩欲翻。","草玄今已毕，此外复何言。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["园林"],"cats":{"人生":["读书"]},"theme_conf":0.95},{"uid":"f0d0412b-b79c-4643-a730-f980bf7e088a","title":"秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南征为客久，西候别君初。","岁满归凫舄，秋来把雁书。","荆门留美化，姜被就离居。","闻道和亲人，垂名报国余。","连枝不日竝，八座几时除。","往者胡星孛，恭惟汉网疎。","风尘相澒洞，天地一丘墟。","殿瓦鸳鸯坼，宫帘翡翠虚。","钩陈摧徼道，枪櫐失储胥。","文物陪巡守，亲贤病拮据。","公时呵䝟貐，首唱却鲸鱼。","势惬宗萧相，材非一范雎。","尸填太行道，血走浚仪渠。","滏口师仍会，函关愤已摅。","紫微临大角，皇极正乘舆。","赏从频峨冕，殊私再直庐。","岂惟高卫霍，曾是接应徐。","降集飜翔凤，追攀绝众狙。","侍臣双宋玉，战策两穰苴。","鉴澈劳悬镜，荒芜已荷锄。","向来披述作，重此忆吹嘘。","白发甘凋丧，青云亦卷舒。","经纶功不朽，跋涉体何如。","应讶耽湖橘，常餐占野蔬。","十年婴药饵，万里狎樵渔。","扬子淹投阁，邹生惜曳裾。","但惊飞熠耀，不记改蟾蜍。","烟雨封巫峡，江淮略孟诸。","汤池虽险固，辽海尚填淤。","努力输肝胆，休烦独起予。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["离别","爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.532},{"uid":"bb68efa3-9758-4ac2-927c-a0985c84acad","title":"答白刑部闻新蝉","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉声未发前，已自感流年。","一入凄凉耳，如闻断续弦。","晴清依露叶，晚急畏霞天。","何事秋卿咏，逢时亦悄然。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"e110a26e-5f86-457d-838d-2566c1d9269e","title":"郊庙歌辞 禅社首乐章 寿和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["惟以明发，有怀载殷。","乐盈而反，礼顺其禋。","立清以献，荐欲是亲。","於穆不已，裒对斯臻。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":1.0},{"uid":"503b3e6f-a832-43df-bf4b-20bbfcef0769","title":"送孔党赴举","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["入贡列诸生，诗书业早成。","家承孔圣后，身有鲁儒名。","楚水通荥浦，春山拥汉京。","爱君方弱冠，为赋少年行。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"ae355c43-35bf-4bcb-8381-6018739b2b48","title":"题玉山观禅师兰若","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉山宴坐移年月，锡杖承恩诣丹阙。","先朝亲与会龙华，紫禁鸣钟白日斜。","宫女焚香把经卷，天人就席礼袈裟。","禅床久卧虎溪水，兰若初开凤城里。","不出嚣尘见远公，道成何必青莲宫。","朝持药钵千家近，暮倚绳床一室空。","掖垣挥翰君称美，远客陪游问真理。","薄宦深知误此心，回心愿学雷居士。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["婉约","冲淡"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人生":["哲理"]},"theme_conf":0.97},{"uid":"d746a56b-a083-4549-b107-30764a8726b2","title":"观放鱼歌","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["常州贤刺史，从谏议大夫除。","天地好生物，刺史性与天地俱。","见山客，狎鱼鸟。","坐山客，北亭湖。","命舟人，驾舫子。","漾漾菰蒲，酒兴引行处。","正见渔人鱼，刺史密会山客意。","复念网罗婴无辜，忽脱身上殷绯袍。","尽买罟擭尽有无，鳗鳣鲇鳢䲡。","涎恶最顽愚，鳟舫见豳风。","质干稍高流，时白喷雪鲫鲤𦛇。","此辈肥脃为绝尤，老鲤变化颇神异。","三十六鳞如抹朱，水苞弘窟有蛟鼍。","饵非龙饵唯无鲈，丛杂百千头。","性命悬须臾，天心应刺史。","刺史尽活诸，一一投深泉。","跳脱不复拘，得水竞腾突。","动作诡怪殊，或透藻而出。","或破浪而趋，或掉尾孑孑。","或奋鬣愉愉，或如莺掷梭。","或如虵衔珠，四散渐不见。","岛屿徒萦纡，㶉𫛶鸰鸥凫。","喜观争呌呼，小虾亦相庆。","绕岸摇其须，乃知贪生不独顽痴夫。","可怜百千命，几为中肠葅。","若养圣贤真，大烹龙髓敢惜乎。","苦痛如今人，尽是鱼食鱼。","族类恣饮噉，强力无亲疏。","明明刺史心，不欲与物相欺诬。","岸虫两与命，无意杀此活彼用贼徒。","亦忆清江使，横遭乎余且。","圣神七十钻，不及泥中䲡。","哀哉托非贤，五脏生冤讐。","若当刺史时，圣物保不囚。","不疑且不卜，二子安能谀。","二子傥故谀，吾知心受诛。","礼重一草木，易卦称中孚。","又曰钓不纲，又曰远庖厨。","故仁人用心，刺史尽合符。","昔鲁公观棠距箴，遂被孔子贬而书。","今刺史好生，德洽民心。","谁为刺史一褒誉，刺史自上来。","德风如草铺，衣冠兴废礼。","百姓减暴租，豪猾不豪猾。","鳏孤不鳏孤，开古孟渎三十里。","四千顷泥坑为膏腴，刺史视之总若无。","讼庭雀噪坐不得，湖上拔茭植芙蕖。","胜业庄中二桑门，时时对坐谈真如。","因说十千天子事，福力当与刺史俱。","天雨曼陀罗花深没膝，四十千真珠璎珞堆高楼。","此中怪特不可会，但慕刺史仁有余。","刺史敕左右兼小家奴，慎勿背我沈毒钩。","念鱼承奉刺史仁，深僻处，远远游。","刺史官职小，教化未能敷。","第一莫近人，恶人唯口腴。","第一莫出境，四境多网罟。","重伤刺史心，丧尔微贱躯。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"旷达","style2":["绮丽","沉郁"],"mood":"孤寂","mood2":["相思","悲怆"],"scene":["江","楼","鸟"],"cats":{"抒情":["思念","伤感","孤独"],"人生":["励志"]},"theme_conf":0.501},{"uid":"51e663b3-6f76-41f4-8e75-c03772e5f8e1","title":"杂曲歌辞 少年子","author":"李百药","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少年飞翠盖，上路动金镳。","始酌文君酒，新吹弄玉箫。","少年不欢乐，何以尽芳朝。","千金笑里面，一搦抱中腰。","挂冠岂惮宿，迎拜不胜娇。","寄语少年子，无辞归路遥。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"人生":["青春"]},"theme_conf":1.0},{"uid":"68c0c67f-eb61-4dfc-8685-a43c60f1e0e2","title":"长安道中早行","author":"张泌","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["客离孤馆一灯残，牢落星河欲曙天。","鸡唱未沈函谷月，鴈声新度灞陵烟。","浮生已悟庄周蝶，壮志仍输祖逖鞭。","何事悠悠策羸马，此中辛苦过流年。"],"theme":"哲理悟道","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["星星"],"人生":["励志","哲理","时光","梦想"]},"theme_conf":0.49},{"uid":"09788f19-1e11-4394-a543-0edf2cfdcae9","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":["塞外"],"cats":{"抒情":["离别","思念","伤感","孤独"],"人物":["女子"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.755},{"uid":"86500cf0-f0a0-4a79-893e-6bedd71460ee","title":"怀钟陵旧游四首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["滕阁中春绮席开，柘枝蛮鼓殷晴雷。","垂楼万幕青云合，破浪千帆阵马来。","未掘双龙牛斗气，高悬一榻栋梁材。","连巴控越知何事，珠翠沈檀处处堆。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"16c63af4-622a-45e2-9a1c-ebb406711054","title":"琴曲歌辞 宛转歌 一","author":"郎大家宋氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["风已清，月朗琴复鸣。","掩抑非千态，殷勤是一声。","歌宛转，宛转和且长。","愿为双鸿鹄，比翼共翱翔。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["爱情"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"eaf1094e-b116-4d91-819b-df1a80e1c991","title":"月蚀诗","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["新天子即位五年，岁次庚寅。","斗柄插子，律调黄钟。","森森万木夜僵立，寒气赑屭顽无风。","烂银盘从海底出，出来照我草屋东。","天色绀滑凝不流，冰光交贯寒朣胧。","初疑白莲花，浮出龙王宫。","八月十五夜，比并不可双。","此时怪事发，有物吞食来。","轮如壮士斧斫坏，桂似雪山风拉摧。","百炼镜，照见胆。","平地埋寒灰，火龙珠。","飞出脑，却入蚌蛤胎。","摧环破璧眼看尽，当天一搭如煤炲。","磨踪灭迹须臾间，便似万古不可开。","不料至神物，有此大狼狈。","星如撒沙出，争头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射户外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太阴太阳精，皇天要识物。","日月乃化生，走天汲汲劳四体。","与天作眼行光明，此眼不自保。","天公行道何由行，吾见阴阳家有说。","望日蚀月月光灭，朔月掩日日光缺。","两眼不相攻，此说吾不容。","又孔子师老子云，五色令人目盲。","吾恐天似人，好色即丧明。","幸且非春时，万物不娇荣。","青山破瓦色，绿水冰峥嵘。","花枯无女艳，鸟死沈歌声。","顽冬何所好，偏使一目盲。","传闻古老说，蚀月虾蟇精。","径圆千里入汝腹，汝此痴骸阿谁生。","可从海窟来，便解缘青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝悬四目，四海生光辉。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受虫豸欺。","长嗟白兔捣灵药，恰似有意防奸非。","药成满臼不中度，委任白兔夫何为。","忆昔尧为天，十日烧九州。","金烁水银流，玉煼丹砂焦。","六合烘为窑，尧心增百忧。","帝见尧心忧，勃然发怒决洪流。","立拟沃杀九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御导九日。","争持节幡麾幢旒，驾车六九五十四头蛟螭虬。","掣电九火辀，汝若蚀开齱齵轮。","御辔执索相爬钩，推荡轰訇入汝喉。","红鳞燄鸟烧口快，翎鬣倒侧声醆邹。","撑肠拄肚礧傀如山丘，自可饱死更不偷。","不独填饥坑，亦解尧心忧。","恨汝时当食，藏头𢬍脑不肯食。","不当食，张唇哆觜食不休。","食天之眼养逆命，安得上帝请汝刘。","呜呼！人养虎，被虎啮。","天媚蟇，被蟇瞎。","乃知恩非类，一一自作孽。","吾见患眼人，必索良工诀。","想天不异人，爱眼固应一。","安得常娥氏，来习扁鹊术。","手操舂喉戈，去此睛上物。","其初犹朦胧，既久如抹漆。","但恐功业成，便此不吐出。","玉川子又涕泗下，心祷再拜额榻砂土中。","地上虮虱臣仝告愬帝天皇，臣心有铁一寸。","可刳妖蟇痴肠，上天不为臣立梯磴。","臣血肉身，无由飞上天。","扬天光，封词付与小心风。","𩙥排阊阖入紫宫，密迩玉几前擘坼。","奏上臣仝顽愚胸，敢死横干天。","代天谋其长，东方苍龙角。","插戟尾捭风，当心开明堂。","统领三百六十鳞虫，坐理东方宫。","月蚀不救援，安用东方龙。","南方火鸟赤泼血，项长尾短飞跋躠。","头戴井冠高逵枿，月蚀鸟宫十三度。","鸟为居停主人不觉察，贪向何人家。","行赤口毒舌，毒虫头上吃却月。","不啄杀，虚眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧为牙，凿为齿。","偷牺牲，食封豕。","大蟇一脔，固当软美。","见似不见，是何道理。","爪牙根天不念天，天若准拟错准拟。","北方寒龟被虵缚，藏头入壳如入狱。","虵筋束紧束破壳，寒龟夏鼈一种味。","且当以其肉充臛，死壳没信处。","唯堪支床脚不堪钻灼与天卜，岁星主福德。","官爵奉董秦，忍使黔娄生。","覆尸无衣巾，天失眼不吊。","岁星胡其仁，荧惑矍铄翁。","执法大不中，月明无罪过。","不纠蚀月虫，年年十月朝太微。","支卢谪罚何灾凶，土星与土性相背。","反养福德生祸害，到人头上死破败。","今夜月蚀安可会，太白真将军。","怒激锋铓生，恒州阵斩郦定进。","项骨脃甚春蔓菁，天唯两眼失一眼。","将军何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固应乐见天盲时，天若不肯信。","试唤臯陶鬼一问，一如今日。","三台文昌宫，作上天纪纲。","环天二十八宿，磊磊尚书郎。","整顿排班行，劒握他人将。","一四太阳侧，一四天市傍。","操斧代大匠，两手不怕伤。","弧矢引满反射人，天狼呀啄明煌煌。","痴牛与𫘤女，不肯勤农桑。","徒劳含淫思，旦夕遥相望。","蚩尤簸旗弄旬朔，始搥天鼓鸣珰琅。","枉矢能蛇行，眊目森森张。","天狗下舐地，血流何滂滂。","谲险万万党，架搆何可当。","眯目衅成就，害我光明王。","请留北斗一星相北极，指麾万国悬中央。","此外尽扫除，堆积如山冈。","赎我父母光，当时常星没。","殒雨如迸浆，似天会事发。","叱喝诛奸强，何故中道废。","自遗今日殃，善善又恶恶。","郭公所以亡，愿天神圣心。","无信他人忠，玉川子词讫。","风色紧格格，近月黑暗边。","有似动劒戟，须臾痴蟇精。","两吻自决坼，初露半个璧。","渐吐满轮魄，众星尽原赦。","一蟇独诛磔，腹肚忽脱落。","依旧挂穹碧，光彩未苏来。","惨澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蚀尽不收，今子咄咄词。","颇合孔意不，玉川子笑荅。","或请听逗留，孔子父母鲁。","讳鲁不讳周，书外书大恶。","故月蚀不见收，予命唐天。","口食唐土，唐礼过三。","唐乐过五，小犹不说。","大不可数，灾沴无有小大瘉。","安得引衰周，研核其可否。","日分昼，月分夜。","辨寒暑，一主刑。","二主德，政乃举。","孰为人面上，一目偏可去。","愿天完两目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["幽峭","豪放"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["月","夏","冬"],"cats":{"抒情":["思念","伤感"],"四季":["夏天","冬天"],"天气":["月亮","星星"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.423},{"uid":"de7404b1-b2f2-4924-b187-b47aa50039d7","title":"清明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["著处繁花务是日，长沙千人万人出。","渡头翠柳艳明眉，争道朱蹄骄啮膝。","此都好游湘西寺，诸将亦自军中至。","马援征行在眼前，葛强亲近同心事。","金镫下山红粉晚，牙樯捩柁青楼远。","古时丧乱皆可知，人世悲欢暂相遣。","弟姪虽存不得书，干戈未息苦离居。","逢迎少壮非吾道，况乃今朝更祓除。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["清新"],"mood":"悲怆","mood2":["欢愉","慷慨"],"scene":["清明"],"cats":{"抒情":["伤感"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.78},{"uid":"d9b26a58-c9cb-4a98-8980-32df48b58348","title":"代九九","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年桃李月，颜色共花宜。","廻脸莲初破，低蛾柳竝垂。","望山多倚树，弄水爱临池。","远被登楼识，潜因倒影窥。","隔林徒想像，上砌转逶迤。","谩掷庭中果，虚攀墙外枝。","强持文玉佩，求结麝香缡。","阿母怜金重，亲兄要马骑。","把将娇小女，嫁与冶游儿。","自隐勤勤索，相要事事随。","每常同坐卧，不省暂参差。","才学羞兼妒，何言宠便移。","青春来易皎，白日誓先亏。","僻性嗔来见，邪行醉后知。","别床铺枕席，当面指瑕疵。","妾貌应犹在，君情遽若斯。","的成终世恨，焉用此宵为。","鸾镜灯前扑，鸳衾手下隳。","参商半夜起，琴瑟一声离。","努力新丛艳，狂风次第吹。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["豪放","婉约"],"mood":"慷慨","mood2":["愁怨"],"scene":["园林","夜","春"],"cats":{"抒情":["离别","闺怨"],"四季":["春天"],"天气":["写风"],"人物":["母亲"],"人生":["青春"]},"theme_conf":0.431},{"uid":"0532d507-dd36-4bb4-868a-fe771d68c11e","title":"华清宫三十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绣岭明珠殿，层峦下缭墙。","仰窥丹槛影，犹想赭袍光。","昔帝登封后，中原自古强。","一千年际会，三万里农桑。","几席延尧舜，轩墀接禹汤。","雷霆驰号令，星斗焕文章。","钓筑乘时用，芝兰在处芳。","北扉闲木索，南面富循良。","至道思玄圃，平居厌未央。","钩陈裹岩谷，文陛压青苍。","歌吹千秋节，楼台八月凉。","神仙高缥缈，环珮碎丁当。","泉暖涵窓镜，云娇惹粉囊。","嫩岚滋翠葆，清渭照红粧。","帖泰生灵寿，懽娱岁序长。","月闻仙曲调，霓作舞衣裳。","雨露偏金穴，乾坤入醉乡。","玩兵师汉武，回手倒干将。","黥鬣掀东海，胡牙揭上阳。","喧呼马嵬血，零落羽林枪。","倾国留无路，还魂怨有香。","蜀峰横惨澹，秦树远微茫。","鼎重山难转，天扶业更昌。","望贤余故老，花萼旧池塘。","往事人谁问，幽襟泪独伤。","碧簷斜送日，殷叶半凋霜。","迸水倾瑶砌，疎风罅玉房。","尘埃羯鼓索，片段荔枝筐。","鸟啄摧寒木，蜗涎蠹画梁。","孤烟知客恨，遥起泰陵傍。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":["沉郁","豪放"],"mood":"愁怨","mood2":["孤寂","恬淡"],"scene":["山","花","园林","楼"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["秋天"],"人生":["战争"],"食物":["荔枝"]},"theme_conf":0.305},{"uid":"5cee205e-5c59-46e5-b060-9b0916c64a3f","title":"忆昔二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔先皇巡朔方，千乘万骑入咸阳。","阴山骄子汗血马，长驱东胡胡走藏。","邺城反复不足怪，关中小儿坏纪纲，张后不乐上为忙。","至今今上犹拨乱，劳身焦思补四方。","我昔近侍叨奉引，出兵整肃不可当。","为留猛士守未央，致使岐雍防西羌。","犬戎直来坐御床，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"c348bc2e-f50d-436b-88b7-c198d63dacfc","title":"行路难三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["金樽清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪满山。","闲来垂钓碧溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在。","长风破浪会有时，直挂云帆济沧海。"],"theme":"咏怀抒感","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":["慷慨","惆怅"],"scene":["酒"],"cats":{"山水":["黄河"],"人生":["励志"]},"theme_conf":0.95},{"uid":"78f8699c-a199-4dde-8be3-79fb887a596d","title":"相和歌辞 门有车马客行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["门有车马客，金鞍曜朱轮。","谓从丹霄落，乃是故乡亲。","呼儿埽中堂，坐客论悲辛。","对酒两不饮，停觞泪盈巾。","叹我万里游，飘飖三十春。","空谈霸王略，紫绶不挂身。","雄劒藏玉匣，阴符生素尘。","廓落无所合，流离湘水滨。","借问宗党间，多为泉下人。","生苦百战役，死托万鬼邻。","北风扬胡沙，埋翳周与秦。","大运且如此，苍穹宁匪仁。","恻怆竟何道？存亡任大钧。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["绮丽","冲淡"],"mood":"悲怆","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["思乡","伤感","悼亡"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.438},{"uid":"3e6f3ca9-f771-438d-8f5f-75ba5b802739","title":"酬李端校书见赠","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿槐垂穗乳乌飞，忽忆山中独未归。","青镜流年看发变，白云芳草与心违。","乍逢酒客春游惯，久别林僧夜坐稀。","昨日闻君到城阙，莫将簪弁胜荷衣。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["酒","春","夜","山"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.97},{"uid":"7e57dc35-56b8-4e3d-ab51-25d6c4bd1fab","title":"逢故人","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故交相见稀，相见倍依依。","尘路事不尽，云岩闲好归。","投人销壮志，徇俗变真机。","又落他乡泪，风前一满衣。"],"theme":"羁旅思乡","theme2":["送别","闲适隐逸"],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["友情","思乡","伤感"],"人生":["励志","梦想"]},"theme_conf":0.388},{"uid":"0cf6265f-c453-4bc5-9f3f-55a6ab43a83a","title":"杂曲歌辞 少年行三首 二","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["侍猎长杨下，承恩更射飞。","尘生马影灭，箭落鴈行稀。","薄暮归随仗，联翩入琐闱。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"13619ace-57d2-4444-ac03-15481045fff6","title":"淇上酬薛三据兼寄郭少府微","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["自从别京华，我心乃萧索。","十年守章句，万事空寥落。","北上登蓟门，茫茫见沙漠。","倚劒对风尘，慨然思卫霍。","拂衣去燕赵，驱马怅不乐。","天长沧洲路，日暮邯郸郭。","酒肆或淹留，渔潭屡栖泊。","独行备艰险，所见穷善恶。","永愿拯刍荛，孰云干鼎镬。","皇情念淳古，时俗何浮薄。","理道资任贤，安人在求瘼。","故交负灵奇，逸气抱謇谔。","隐轸经济具，纵横建安作。","才望忽先鸣，风期无宿诺。","飘飖劳州县，迢递限言谑。","东驰眇贝丘，西顾弥虢略。","淇水徒自流，浮云不堪托。","吾谋适可用，天路岂寥廓。","不然买山田，一身与耕凿。","且欲同鹪鹩，焉能志鸿鹄。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":["豪放","幽峭"],"mood":"孤寂","mood2":["恬淡","相思"],"scene":["塞外","酒"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":0.98},{"uid":"de9b3a1a-925d-445a-9e23-d03b0f64d388","title":"横吹曲辞 出塞曲 二","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉帐将军意，慇懃把酒论。","功高宁在我，阵没与招魂。","塞色干戈束，军容喜气屯。","男儿今始是，敢出玉关门。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.867},{"uid":"4c57a579-0494-41cf-a174-6472ac4f2e8e","title":"游桃源一百韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["沅江清悠悠，连山郁岑寂。","回流抱绝𪩘，皎镜含虚碧。","昏旦递明媚，烟岚分委积。","香蔓垂绿潭，暴龙照孤碛。","渊明著前志，子骥思远跖。","寂寂无何乡，密尔天地隔。","金行太元岁，渔者偶探赜。","寻花得幽踪，窥洞穿暗隙。","依微闻鸡犬，豁达值阡陌。","居人互将迎，笑语如平昔。","广乐虽交奏，海禽心不怿。","挥手一来归，故溪无处觅。","绵绵五百载，市朝几迁革。","有路在壶中，无人知地脉。","皇家感至道，圣祚自天锡。","金阙传本枝，玉函留宝历。","禁山开秘宇，复户洁灵宅。","蘂检香氛氲，醮坛烟幂幂。","我来尘外躅，莹若朝星析。","崖转对翠屏，水穷留画鹢。","三休俯乔木，千级扳峭壁。","旭日闻撞钟，彩云迎蹑屐。","遂登最高顶，纵目还楚泽。","平湖见草青，远岸连霞赤。","幽寻如梦想，绵思属空阒。","夤缘且忘疲，耽玩近成癖。","清猨伺晓发，瑶草凌寒坼。","祥禽舞葱茏，珠树摇玓𬍛。","羽人顾我笑，劝我税归轭。","霓裳何飘飖，童颜洁白皙。","重岩是藩屏，驯鹿受羁靮。","楼居弥清霄，萝茑成翠帟。","仙翁遗竹杖，王母留桃核。","姹女飞丹砂，青童护金液。","宝气浮鼎耳，神光生劒脊。","虚无天乐来，僁窣鬼兵役。","丹丘肃朝礼，玉札工䌷绎。","枕中淮南方，床下阜乡舄。","明灯坐遥夜，幽籁听淅沥。","因话近世仙，耸然心神惕。","乃言瞿氏子，骨状非凡格。","往事黄先生，群儿多侮剧。","謷然不屑意，元气贮肝膈。","往往游不归，洞中观博弈。","言高未易信，犹复加诃责。","一旦前致辞，自云仙期迫。","言师有道骨，前事常被谪。","如今三山上，名字在真籍。","悠然谢主人，后岁当来觌。","言毕依庭树，如烟去无迹。","观者皆失次，惊追纷络绎。","日暮山径穷，松风自萧槭。","适逢修蛇见，瞋目光激射。","如严三清居，不使恣搜索。","唯余步纲势，八趾在沙砾。","至今东北隅，表以坛上石。","列仙徒有名，世人非目击。","如何庭庑际，白日振飞翮。","洞天岂幽远，得道如咫尺。","一气无死生，三光自迁易。","因思人间世，前路何狭窄。","瞥然此生中，善祝期满百。","大方播群类，秀气肖翕辟。","性静本同和，物牵成阻厄。","是非鬬方寸，荤血昏精魄。","遂令多夭伤，犹喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安缇绣荣，不悟泥途适。","纷吾本孤贱，世业在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰荐，乡曲缪推择。","居安白社贫，至傲玄𫄸辟。","功名希自取，簪组俟扬历。","书府蚤怀铅，射宫曾发的。","起草香生帐，坐曹乌集柏。","赐燕聆箫韶，侍祠阅琮璧。","尝闻履忠信，可以行蛮貊。","自述希古心，忘恃干时画。","巧言忽成锦，苦志徒食蘗。","平地生峰峦，深心有矛戟。","层波一震荡，弱植忽沦溺。","北渚吊灵均，长岑思亭伯。","祸来昧几兆，事去空叹息。","尘累与时深，流年随漏滴。","才能疑木鴈，报施迷夷跖。","楚奏絷钟仪，商歌劳宁戚。","禀生非悬解，对镜方感激。","自从婴网罗，每事问龟策。","王正降雷雨，环玦赐迁斥。","倘伏夷平人，誓将依羽客。","买山构精舍，领徒开讲席。","冀无身外忧，自有闲中益。","道芽期日就，尘虑乃冰释。","且欲遗姓名，安能慕竹帛。","长生尚学致，一溉岂虚掷。","芝术资糇粮，烟霞拂巾帻。","黄石履看堕，洪崖肩可拍。","聊复嗟蜉蝣，何烦哀虺蜴。","青囊既深味，琼葩亦屡摘。","纵无西山资，犹免长戚戚。"],"theme":"游仙梦幻","theme2":["羁旅思乡"],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["山","江","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["写云","太阳"],"人物":["老师"],"人生":["时光","战争"],"植物":["桃花"]},"theme_conf":0.87},{"uid":"40c2882a-7e79-4915-a77a-95acb7cc4715","title":"在郡秋怀二首 一","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋风入前林，萧瑟鸣高枝。","寂寞游子思，寤叹何人知。","宦成名不立，志存岁已驰。","五十而无闻，古人深所疵。","平生去外饰，直道如不羁。","未得操割效，忽复寒暑移。","物情自古然，身退毁亦随。","悠悠沧江渚，望望白云涯。","露下霜且降，泽中草离披。","兰艾若不分，安用馨香为。"],"theme":"亲情","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["励志"]},"theme_conf":0.519},{"uid":"6487761a-51bf-4362-9513-52c1f6c495bb","title":"哭张十八校书","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["芸阁为郎一命初，桐州寄傲十年余。","魂随逝水归何处，名在新诗众不如。","蹉跎江浦生华发，牢落寒原会素车。","更忆八行前日到，含凄为报秣陵书。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["楼","江"],"cats":{"抒情":["悼亡"],"人生":["时光"]},"theme_conf":0.98},{"uid":"a4027d74-3867-4341-ad57-5248746e36a5","title":"和令狐相公春日寻花有怀白侍郎阁老","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["芳菲满雍州，鸾凤许同游。","花迳须深入，时光不少留。","色鲜由树嫩，枝亚为房稠。","静对仍持酒，高看特上楼。","晴宜连夜赏，雨便一年休。","共忆秋官处，余霞曲水头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼","花"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.95},{"uid":"5aac5703-ad15-4da8-84fb-ff0e68557569","title":"立春日宴高陵任明府宅","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春灰今变候，密雪又霏霏。","坐客同心满，流年此会稀。","风成空处乱，素积夜来飞。","且共衔杯酒，陶潜不得归。"],"theme":"节令风俗","theme2":[],"style":"冲淡","style2":["旷达"],"mood":"欢愉","mood2":[],"scene":["春","酒","雪"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":0.8},{"uid":"cf854c36-62d7-4c54-ad3f-258cfedbb14a","title":"题郑十八著作虔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["台州地阔海冥冥，云水长和岛屿青。","乱后故人双别泪，春深逐客一浮萍。","酒酣嬾舞谁相拽，诗罢能吟不复听。","第五桥东流恨水，皇陂岸北结愁亭。","贾生对𫛳伤王傅，苏武看羊陷贼庭。","可念此翁怀直道，也沾新国用轻刑。","祢衡实恐遭江夏，方朔虚传是岁星。","穷巷悄然车马绝，案头干死读书萤。"],"theme":"送别","theme2":["咏物"],"style":"沉郁","style2":["豪放","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","夏","春","酒"],"cats":{"抒情":["友情","伤感"],"四季":["春天","夏天"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.53},{"uid":"410b6c68-3226-47ea-a83c-c93f648d5213","title":"安平公诗","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈人博陵王名家，怜我总角称才华。","华州留语晓至暮，高声喝吏放两衙。","明朝骑马出城外，送我习业南山阿。","仲子延岳年十六，面如白玉欹乌纱。","其弟炳章犹两丱，瑶林琼树含奇花。","陈留阮家诸侄秀，逦迤出拜何骈罗。","府中从事杜与李，麟角虎翅相过摩。","清词孤韵有歌响，击触钟磬鸣环珂。","三月石堤冻销释，东风开花满阳坡。","时禽得伴戏新木，其声尖咽如鸣梭。","公时载酒领从事，踊跃鞍马来相过。","仰看楼殿撮清汉，坐视世界如恒沙。","面热脚掉互登陟，青云表柱白云崖。","一百八句在贝叶，三十三天长雨花。","长者子来辄献盖，辟支佛去空留𫖇。","公时受诏镇东鲁，遣我草诏随车牙。","顾我下笔即千字，疑我读书倾五车。","呜嘑大贤苦不寿，时世方士无灵砂。","五月至止六月病，遽颓泰山惊逝波。","明年徒步吊京国，宅破子毁哀如何。","西风冲户卷素帐，隟光斜照旧燕窠。","古人常叹知己少，况我沦贱艰虞多。","如公之德世一二，岂得无泪如黄河。","沥胆咒愿天有眼，君子之泽方滂沱。"],"theme":"送别","theme2":["悼亡挽歌","民生疾苦"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["山","江"],"cats":{"抒情":["友情","伤感","孤独","悼亡"],"山水":["泰山","黄河"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.431},{"uid":"32a0cecf-b0fc-4415-8294-2c31f20d5f52","title":"演兴四首 初祀","author":"元结","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["山之乳兮葺太祠，木孙为桷兮木母榱。","云缨为𣓍兮愚木栭，洞渊禅兮揭巍巍。","涂木兰兮莳糅蔫，被弱草兮禘礿联。","仡浑洪兮馥阗阗，管化石兮洞刳天。","翘修钐兮掉芜殳，灵巫𧮢兮舞颙干。","荐天𩷨兮酒阳泉，献水芸兮饭霜籼，与太灵兮千万年。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"人生":["哲理"]},"theme_conf":0.544},{"uid":"4874dc2a-9909-4205-b5da-4907c0724484","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十一","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白赤虹，昼（川本作「尽」）见莫兴兵。","更有虹霓垂军上，彼军杀将且须停，动必有灾迍。"],"theme":"边塞征战","theme2":[],"style":"旷达","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"818ab313-009a-4bca-829a-30768146e907","title":"杂曲歌辞 结客少年场行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["紫燕黄金瞳，啾啾摇绿鬉。","平明相驰逐，结客洛门东。","少年学劒术，凌轹白猨公。","珠袍曳锦带，七首插吴鸿。","由来万夫勇，挟此生雄风。","托交从剧孟，买醉入新丰。","笑尽一杯酒，杀人都市中。","羞道易水寒，从令日贯虹。","燕丹事不立，虚没秦帝宫。","舞阳死灰人，安可与成功。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":["悲怆"],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"cbceb077-c964-4d19-8fa4-3b2c6613c08c","title":"杂曲歌辞 破阵乐 三","author":"不详","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少年胆气凌云，共许骁雄出群。","匹马城南挑战，单刀蓟北从军。","一鼓鲜卑送欵，五饵单于解纷。","誓欲成名报国，羞将开口论勋。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":[],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.845},{"uid":"2954ddd2-f1c7-41b1-8c9e-42058398cde0","title":"晨诣超师院读禅经","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汲井漱寒齿，清心拂尘服。","闲持贝叶书，步出东斋读。","真源了无取，妄迹世所逐。","遗言冀可冥，缮性何由熟。","道人庭宇静，苔色连深竹。","日出雾露余，青松如膏沐。","澹然离言说，悟悦心自足。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"人生":["哲理"]},"theme_conf":0.587},{"uid":"4e01deae-f2e1-403a-a615-97aaf7e78738","title":"鼓吹曲辞 战城南二首 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万里桑干傍，茫茫古蕃壤。","将军貌顦顇，抚劒悲年长。","胡兵尚陵逼，久住亦非强。","邯郸少年辈，个个有伎俩。","拖枪半夜去，雪片大如掌。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":1.0},{"uid":"930a9bfb-ee77-4806-b03c-7bf63a9b070e","title":"宋州东登望题武陵驿","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["梁宋人稀鸟自啼，登舻一望倍含凄。","白骨半随河水去，黄云犹傍郡城低。","平陂战地花空落，旧苑春田草未齐。","明主频移虎符守，几时行县向黔黎。"],"theme":"咏史怀古","theme2":["羁旅思乡","咏物"],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"人生":["战争"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"0710a746-8660-4bc1-b073-8ce51ac9f4d9","title":"梦李白二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浮云终日行，游子久不至。","三夜频梦君，情亲见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失坠。","出门搔白首，若负平生志。","冠盖满京华，斯人独顦顇。","孰云网恢恢，将老身反累。","千秋万岁名，寂莫身后事。"],"theme":"寄赠酬答","theme2":["民生疾苦","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["江","舟","秋","夜"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.75},{"uid":"0d07875d-bf3e-4a2e-9139-ba767079c8ad","title":"八哀诗 故秘书少监武功苏公源明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["武功少也孤，徒步客徐衮。","读书东岳中，十载考坟典。","时下莱芜郭，忍饥浮云𪩘。","负米晚为身，每食脸必泫。","夜字照𦶟薪，垢衣生碧藓。","庶以勤苦志，报兹劬劳显。","学蔚醇儒姿，文包旧史善。","洒落辞幽人，归来潜京辇。","射君东堂策，宗匠集精选。","制可题未干，乙科已大阐。","文章日自负，吏禄亦累践。","晨趋阊阖内，足蹋宿昔趼。","一麾出守还，黄屋朔风卷。","不暇陪八骏，虏庭悲所遣。","平生满尊酒，断此朋知展。","忧愤病二秋，有恨石可转。","肃宗复社稷，得无逆顺辨。","范晔顾其儿，李斯忆黄犬。","秘书茂松意，溟涨本末浅。","青荧芙蓉劒，犀兕岂独剸。","反为后辈亵，予实苦怀缅。","煌煌斋房芝，事绝万手搴。","垂之俟来者，正始征劝勉。","不要悬黄金，胡为投乳贙。","结交三十载，吾与谁游衍。","荥阳复冥莫，罪罟已横罥。","呜呼子逝日，始泰则终蹇。","长安米万钱，凋丧尽余喘。","战伐何当解，归帆阻清沔。","尚缠漳水疾，永负蒿里饯。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":[],"cats":{"抒情":["伤感","孤独","悼亡"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.99},{"uid":"03835a84-cf65-4775-8f22-fd98bf907b5e","title":"奉赠卢五丈参谋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["恭惟同自出，妙选异高标。","入幕知孙楚，披襟得郑侨。","丈人藉才地，门阀冠云霄。","老矣逢迎拙，相于契托饶。","赐钱倾府待，争米驻船遥。","邻好艰难薄，氓心杼轴焦。","客星空伴使，寒水不成潮。","素发干垂领，银章破在腰。","说诗能累夜，醉酒或连朝。","藻翰惟牵率，湖山合动摇。","时清非造次，兴尽却萧条。","天子多恩泽，苍生转寂寥。","休传鹿是马，莫信𫛳如鸮。","未解依依袂，还斟泛泛瓢。","流年疲蟋蟀，体物幸鹪鹩。","辜负沧州愿，谁云晚见招。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江"],"cats":{"人生":["时光"]},"theme_conf":0.66},{"uid":"dc01e269-75e6-4f68-8ce1-ea2615ba9719","title":"题思禅寺上方","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["溪口闻法鼓，停桡登翠屏。","攀云到金界，合掌开禅扃。","郁律众山抱，空蒙花雨零。","老僧指香楼，云是不死庭。","眇眇于越路，茫茫春草青。","远山喷百谷，缭绕驰东溟。","目极道何在，境照心亦冥。","𬴃然诸根空，破结如破瓶。","下视三界狭，但闻五浊腥。","山中有良药，吾欲隳天形。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"相思","mood2":["悲怆"],"scene":["花","山","春","雨","楼"],"cats":{"四季":["春天"],"人生":["哲理"]},"theme_conf":0.97},{"uid":"6532c143-b684-4399-abfa-4edc7e8de03c","title":"避地","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["避地岁时晚，窜身筋骨劳。","诗书遂墙壁，奴仆且旌旄。","行在仅闻信，此生随所遭。","神尧旧天下，会见出腥臊。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.64},{"uid":"59e2fe4b-c925-4b3e-851d-e1c355c43b98","title":"关山月","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高高秋月明，北照辽阳城。","塞迥光初满，风多晕更生。","征人望乡思，战马闻鼙惊。","朔风悲边草，胡沙暗虏营。","霜凝匣中劒，风惫原上旌。","早晚谒金阙，不闻刁斗声。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["塞外","月","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写风","月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.595},{"uid":"591954e3-94ae-41f0-a2b1-5dbad55e951f","title":"龙州韦郎中先梦六赤后因打叶子以诗上","author":"李洞","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["红蜡香烟扑画楹，梅花落尽庾楼清。","光辉圆魄衔山冷，彩镂方牙着腕轻。","宝帖牵来狮子镇，金盆引出凤凰倾。","微黄喜兆庄周梦，六赤重新掷印成。"],"theme":"哲理悟道","theme2":["游仙梦幻"],"style":"婉约","style2":["绮丽","清新"],"mood":"相思","mood2":["欢愉"],"scene":["花","楼"],"cats":{"人生":["哲理","梦想"],"植物":["叶子"]},"theme_conf":0.565},{"uid":"a032115c-e129-487b-b0cb-c8d15f01d2a7","title":"行路难","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["出门行路难，富贵安可期。","淮阴不免恶少辱，阮生亦作穷途悲。","颠倒英雄古来有，封侯却属屠沽儿。","长安车马随轻肥，青云宾从纷交驰。","白眼向人多意气，宰牛烹羊如折葵。","䜩乐宁知白日短，时时醉拥双蛾眉。","扬雄闭门空读书，门前碧草春离离。","不如拂衣且归去，世上浮名徒尔为。"],"theme":"羁旅思乡","theme2":["送别"],"style":"豪放","style2":["婉约"],"mood":"慷慨","mood2":["悲怆","欢愉"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.5},{"uid":"f0e9fe34-bbb9-4763-be64-4d7ea74b65ec","title":"省中春暮酬嵩阳焦道士见招","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝花飞暝林，对酒伤春心。","流年催素发，不觉映华簪。","垂老遇知己，酬恩看寸阴。","如何紫芝客，相忆白云深。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.92},{"uid":"704cf3c8-46c0-4e9f-b015-7e386bd0eff2","title":"题衡山县文宣王庙新学堂呈陆宰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旄头彗紫微，无复俎豆事。","金甲相排荡，青衿一顦顇。","呜呼已十年，儒服弊于地。","征夫不遑息，学者沦素志。","我行洞庭野，歘得文翁肆。","侁侁胄子行，若舞风雩至。","周室宜中兴，孔门未应弃。","是以资雅才，涣然立新意。","衡山虽小邑，首唱恢大义。","因见县尹心，根源旧宫閟。","讲堂非曩搆，大屋加涂墍。","下可容百人，墙隅亦深邃。","何必三千徒，始压戎马气。","林木在庭户，密干叠苍翠。","有井朱夏时，辘轳冻阶戺。","耳闻读书声，杀伐灾髣髴。","故国延归望，衰颜减愁思。","南纪改波澜，西河共风味。","采诗倦跋涉，载笔尚可记。","高歌激宇宙，凡百慎失坠。"],"theme":"寄赠酬答","theme2":["山水田园","咏物"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":["相思"],"scene":["山","江"],"cats":{"抒情":["伤感","怀古"],"人生":["读书"]},"theme_conf":0.75},{"uid":"a23b4c7c-255d-4a62-b221-4b62b42fcbcb","title":"将之京国赠薛员外","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["黄叶下空馆，寂寥寒雨愁。","平居岁华晏，络纬啼林幽。","节物凋壮志，咄嗟不能休。","空怀赵鞅叹，变化良无由。","所思杳何如，侧身仰皇州。","苍烟晦楚野，寒浪埋昭丘。","赵壹赋命薄，陈思多世忧。","翻然羡鱼鸟，畅矣山川游。","薛公龙泉姿，其气在斗牛。","南冠束秀发，白石劳悲讴。","圭衮照崇阅，文儒嗣箕裘。","旷然方寸地，霁海浮云舟。","澧浦一遗佩，郢南再悲秋。","叫阍路既阻，浩荡怀灵修。","莫奏武溪笛，且登仲宣楼。","亨通与否闭，物理相沈浮。","天子坐宣室，夔龙奉谟猷。","行当赐环去，岂作遗贤羞。"],"theme":"应制干谒","theme2":["山水田园"],"style":"冲淡","style2":["雄浑","旷达"],"mood":"孤寂","mood2":["愁怨","慷慨"],"scene":["舟","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.91},{"uid":"d3162017-25c7-4031-9ad0-67d9815e79f8","title":"题元阳观旧读书房赠李范","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["此观十年游，此房千里宿。","还来旧窗下，更取君书读。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人生":["读书"]},"theme_conf":0.86},{"uid":"26bda590-69ee-4667-88e4-07e217c0ebaf","title":"重阳日中外同欢以诗言志因示群官","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["[爽]节在重九，物华新雨余。","清秋黄叶下，菊散金潭初。","万实行就稔，百工欣所如。","欢心畅遐迩，殊俗同车书。","至化自敦睦，佳辰宜宴胥。","锵锵间丝竹，济济罗簪裾。","此乐匪足耽，此诚期永孚。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"人生":["梦想"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"f699ef22-319a-481b-8575-103300613ab9","title":"仆射来示有三春向晚四者难幷之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多过隙，新宴且寻盟。","鹦鹉林须乐，麒麟阁未成。","分阴当爱惜，迟景好逢迎。","林野熏风起，楼台谷雨晴。","墙低山半出，池广水初平。","桥转长虹曲，舟回小鹢轻。","残花犹布绣，密竹自闻笙。","欲过芳菲节，难忘宴慰情。","月轮行似箭，时物始如倾。","见雁随兄去，听莺求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虚丝管清。","峰峦侵碧落，草木近朱明。","与点非沂水，陪膺是洛城。","拨醅争绿醑，卧酪待朱樱。","几处能留客，何人唤解酲。","旧仪尊右揆，新命宠春卿。","有喜鹊频语，无机鸥不惊。","青林思小隐，白雪仰芳名。","访旧殊千里，登高赖九城。","酂侯司管钥，疏傅傲簪缨。","纶綍曾同掌，烟霄即上征。","册庭尝接武，书殿忝连衡。","兰室春弥馥，松心晚更贞。","琴招翠羽下，钩掣紫鳞呈。","只愿回乌景，谁能避兕觥。","方知醉兀兀，应是走营营。","凤阁鸾台路，从他年少争。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"f0952fff-6045-44ee-bc86-cf2192e23e7c","title":"题禅院","author":"喻凫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["无花地亦香，有鹤松多直。","向此奚必孤，山僧尽相识。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","花"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.68},{"uid":"644f3188-fc89-45d4-94a4-6df041708e61","title":"和韩侍御白发","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白发今朝见，虚斋晓镜清。","乍分霜简色，微映铁冠生。","幕下多能事，周行挹令名。","流年未可叹，正遇太阶平。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人生":["时光"]},"theme_conf":0.82},{"uid":"c8e50d0a-dd19-4fa2-b07e-95882090e9d7","title":"横吹曲辞 折杨柳 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人生":["青春"],"植物":["柳树"]},"theme_conf":0.753},{"uid":"cd08aef7-5242-4d04-8bb9-09411a11a8d8","title":"送人弃官入道","author":"韩偓","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙李浓阴润，皇枝密叶敷。","俊才轻折桂，捷径取纡朱。","断绁三清路，扬鞭五达衢。","侧身期破的，缩手待呼卢。","社稷俄如缀，雄豪讵守株。","忸怩非壮志，摆脱是良图。","尘土留难住，缨緌弃若无。","冥心归大道，回首笑吾徒。","酒律应难忘，诗魔未肯徂。","他年如拔宅，为我指清都。"],"theme":"送别","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["酒"],"cats":{"人生":["励志","梦想"]},"theme_conf":0.569},{"uid":"cd66d8b3-abe6-4316-ab34-b88a4bb8bb83","title":"杂曲歌辞 北风行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["烛龙栖寒门，光曜犹旦开。","日月照之何不及此，惟有北风怒号天上来。","燕山雪花大如席，片片吹落轩辕台。","幽州思妇十二月，停歌罢笑双蛾摧。","倚门望行人，念君长城苦寒良可哀。","别时提劒救边去，遗此虎文金髀钗。","中有一双白羽箭，蜘蛛结网生尘埃。","箭空在，人今战死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["雪","冬","雨"],"cats":{"抒情":["闺怨"],"山水":["黄河"],"天气":["写风"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.317},{"uid":"8fc37ad3-7f3b-466e-aad1-e00a080fdf1d","title":"睢阳酬别畅大判官","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾友遇知己，策名逢圣朝。","高才擅白雪，逸翰怀青霄。","承诏选嘉宾，慨然即驰轺。","清昼下公馆，尺书忽相邀。","留欢惜别离，毕景驻行镳。","言及沙漠事，益令胡马骄。","丈夫拔东蕃，声冠霍嫖姚。","兜鍪冲矢石，铁甲生风飙。","诸将出冷陉，连营济石桥。","酋豪尽俘馘，子弟输征徭。","边庭绝刁斗，战地成渔樵。","榆关夜不扃，塞口长萧萧。","降胡满蓟门，一一能射雕。","军中多宴乐，马上何轻趫。","戎狄本无厌，羇縻非一朝。","饥附诚足用，饱飞安可招。","李牧制儋蓝，遗风岂寂寥。","君还谢幕府，慎勿轻刍荛。"],"theme":"送别","theme2":["边塞征战"],"style":"豪放","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"抒情":["友情","离别"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.421},{"uid":"50da9443-962b-4d51-a2db-92084b98e1e4","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 八","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白赤虹，单见色无双。","如气冲天或横过，蚩尤旗号动戈鎗，起处必为殃。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cpbf1334f01df25f","title":"少年游","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["长安古道马迟迟。","高柳乱蝉栖。","夕阳岛外，秋风原上，目断四天垂。","归云一去无踪迹，何处是前期。","狎兴生疏，酒徒萧索，不似去年时。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","酒"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.72},{"uid":"066e5f06-6d53-47d1-81f8-982462f0281d","title":"酬郭先辈","author":"徐铉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["太原郭夫子，行高文炳蔚。","弱龄负世誉，一举游月窟。","仙籍第三人，时人故称屈。","昔余吏西省，倾盖名籍籍。","及我窜群舒，向风心郁郁。","归来暮江上，云雾一披拂。","雷雨不下施，犹作池中物。","念君介然气，感时思奋发。","示我数篇文，与古争驰突。","彩褥粲英华，理深刮肌骨。","古诗尤精奥，史论皆宏拔。","举此措诸民，何忧民不活。","吁嗟吾道薄，与世长迂阔。","顾我徒有心，数奇身正绌。","论兵属少年，经国须儒术。","夫子无自轻，苍生正愁疾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人生":["励志"]},"theme_conf":0.95},{"uid":"4925c861-b0f8-4b2f-923e-9cba2df1323e","title":"洛阳女儿行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳女儿对门居，才可容颜十五余。","良人玉勒乘骢马，侍女金盘鲙鲤鱼。","画阁朱楼尽相望，红桃绿柳垂簷向。","罗帏送上七香车，宝扇迎归九华帐。","狂夫富贵在青春，意气骄奢剧季伦。","自怜碧玉亲教舞，不惜珊瑚持与人。","春窗曙灭九微火，九微片片飞花璅。","戏罢曾无理曲时，妆成秪是薰香坐。","城中相识尽繁华，日夜经过赵李家。","谁怜越女颜如玉，贫贱江头自浣纱。"],"theme":"闺情宫怨","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","花"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.396},{"uid":"3781db86-9a0f-4243-806a-63bfbd4bc927","title":"送刘禹锡侍御出刺连州","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["遐荒迢遰五羊城，归兴浓消客里情。","家近似忘山路险，土甘殊觉瘴烟轻。","梅花清入罗浮梦，荔子红分广海程。","此去定知偿隐趣，石田春雨读书耕。"],"theme":"送别","theme2":[],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["花","春","雨","山"],"cats":{"四季":["春天"],"人生":["读书"],"食物":["荔枝"]},"theme_conf":0.538},{"uid":"35d74803-47e5-41c2-9631-a9ef240491e0","title":"赠普门上人","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["支公身欲老，长在沃州多。","慧力堪传教，禅功久伏魔。","山云随坐夏，江草伴头陀。","借问回心后，贤愚去几何。"],"theme":"佛道禅颂","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","山","江"],"cats":{"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.88},{"uid":"c9362aba-fb50-481b-a4cd-08ddd65cdd2a","title":"梦李白二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["死别已吞声，生别常恻恻。","江南瘴疠地，逐客无消息。","故人入我梦，明我长相忆。","恐非平生魂，路远不可测。","魂来枫叶青，魂返关塞黑。","君今在罗网，何以有羽翼。","落月满屋梁，犹疑照颜色。","水深波浪阔，无使蛟龙得。"],"theme":"寄赠酬答","theme2":["游仙梦幻","羁旅思乡","边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","月"],"cats":{"抒情":["友情","思念","思乡"],"人生":["梦想"],"生活":["边塞"]},"theme_conf":0.75},{"uid":"8502e6fa-f283-440a-a69a-12bb1b54610f","title":"酬盩厔耿少府𣲗见寄","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["方丈萧萧落叶中，暮天深巷起悲风。","流年不尽人自老，外事无端心已空。","家近小山当海畔，身留环衞荫墙东。","遥闻相访频逢雪，一醉寒宵谁与同。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","悲慨"],"mood":"悲怆","mood2":["孤寂","惆怅"],"scene":["雪","山","酒","夜"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.95},{"uid":"954bc2e7-212b-4af0-afc2-f9230822a784","title":"送孙泼赴云中","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄骢少年舞双戟，目视旁人皆辟易。","百战能夸陇上儿，一身复作云中客。","寒风动地气苍茫，横吹先悲出塞长。","敲石军中传夜火，斧冰河畔汲朝浆。","前锋直指阴山外，虏骑纷纷胆应碎。","匈奴破尽人看归，金印酬功如斗大。"],"theme":"送别","theme2":["边塞征战"],"style":"雄浑","style2":["悲慨","幽峭"],"mood":"悲怆","mood2":[],"scene":["塞外","夜"],"cats":{"抒情":["伤感"],"天气":["写云"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.479},{"uid":"3182d857-499a-4f62-89f1-aa628eaf63e3","title":"哭长孙侍郎","author":"杜诵","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道为诗书重，名因赋颂雄。","礼闱曾擢桂，宪府既乘骢。","流水生涯尽，浮云世事空。","唯余旧台柏，萧瑟九原中。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["悼亡"],"人生":["读书"]},"theme_conf":0.98},{"uid":"3fff5496-d24c-48c6-9c61-0d8925b663fe","title":"登蒲州逍遥楼","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长榆息烽火，高柳静风尘。","卜征巡九洛，展豫出三秦。","昔是潜龙地，今为上理辰。","时平乘道泰，聊赏遇年春。","黄河分地络，飞观接天津。","一览遗芳翰，千载肃如神。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.565},{"uid":"8fbcb3d0-f752-4276-9e20-971e82b36b3e","title":"酬令狐相公六言见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["已嗟别离太远，更被光阴苦催。","吴苑燕辞人去，汾川鴈带书来。","愁吟月落犹望，忆梦天明未回。","今日便令歌者，唱兄诗送一杯。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["月","江南","酒"],"cats":{"抒情":["离别","思念","伤感"],"人生":["时光"]},"theme_conf":0.96},{"uid":"4a9c46cb-b60d-439c-885e-c4dc8522940f","title":"送顾况泗上觐叔父","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴乡岁贡足嘉宾，后进之中见此人。","别业更临洙泗上，拟将书卷对残春。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江南"],"cats":{"四季":["春天"],"人物":["父亲"],"人生":["读书"]},"theme_conf":0.671},{"uid":"fbb109b7-3b66-4f82-a111-97892b26fa7a","title":"喜闻官军已临贼境二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡虏潜京县，官军拥贼壕。","鼎鱼犹假息，穴蚁欲何逃。","帐殿罗玄冕，辕门照白袍。","秦山当警跸，汉苑入旌旄。","路失羊肠险，云横雉尾高。","五原空壁垒，八水散风涛。","今日看天意，游魂贷尔曹。","乞降那更得，尚诈莫徒劳。","元帅归龙种，司空握豹韬。","前军苏武节，左将吕虔刀。","兵气回飞鸟，威声没巨鼇。","戈鋋开雪色，弓矢尚秋毫。","天步艰方尽，时和运更遭。","谁云遗毒螫，已是沃腥臊。","睿想丹墀近，神行羽卫牢。","花门腾绝漠，拓羯渡临洮。","此辈感恩至，羸俘何足操。","锋先衣染血，骑突劒吹毛。","喜觉都城动，悲怜子女号。","家家卖钗钏，只待献春醪。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","塞外","秋","春","酒"],"cats":{"抒情":["感恩"],"四季":["春天","秋天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"75e8e864-7f92-42e9-9467-8988475bdf49","title":"幽怀","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽怀不能写，行此春江浔。","适与佳节会，士女竞光阴。","凝妆耀洲渚，繁吹荡人心。","间关林中鸟，亦知和为音。","岂无一尊酒，自酌还自吟。","但悲时易失，四序迭相侵。","我歌君子行，视古犹视今。"],"theme":"咏怀抒感","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江","酒"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.88},{"uid":"e951ac7e-488c-4282-a368-a58852fc9f2f","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆题惠山寺书堂","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故山一别光阴改，秋露清风岁月多。","松下壮心年少去，池边衰影老人过。","白云生灭依岩岫，青桂荣枯托薜萝。","惟有此身长是客，又驱旌斾寄烟波。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"60f3c484-4e4f-4612-9f93-e753c7c67c02","title":"送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁脔去东床，趋庭赴北堂。","风波空远涉，琴瑟几虚张。","渥水出骐骥，昆山生凤皇。","两家诚款款，中道许苍苍。","颇谓秦晋匹，从来王谢郎。","青春动才调，白首缺辉光。","玉润终孤立，珠明得暗藏。","余寒折花卉，恨别满江乡。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["女子","父亲"],"人生":["青春"]},"theme_conf":0.524},{"uid":"e110c62b-f130-4558-b4af-8282d6a2a5de","title":"酬杨司业十二兄早秋述情见寄","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白发故人少，相逢意弥远。","往事共销沈，前期各衰晚。","昨来遇弥苦，已复云离𪩘。","秋草古胶庠，寒沙废宫苑。","知心岂忘鲍，咏怀难和阮。","壮志日萧条，那能竞朝幰。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.94},{"uid":"7242db95-41ec-4932-af0b-3d5d9b362775","title":"春日书情赠别司空曙","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["壮志随年尽，谋身意未安。","风尘交契阔，老大别离难。","腊近晴多暖，春迟夜却寒。","谁堪少兄弟，三十又无官。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["离别"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.875},{"uid":"cp334c6d9b3adb62","title":"月下笛","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感","怀古"],"山水":["西湖"],"天气":["月亮"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.416},{"uid":"47dbfc92-dd51-458f-859a-1953cde28460","title":"秋日作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居值秋节，此日更愁辛。","寂寞无一事，蒿莱通四邻。","闭门生白发，回首忆青春。","岁月不相待，交游随众人。","云霄何处托，愚直有谁亲。","举酒聊自劝，穷通信尔身。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["秋"],"cats":{"抒情":["思念","伤感","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"人生":["青春"]},"theme_conf":0.9},{"uid":"b3e2191a-e121-4ddc-a90c-f39467dabf75","title":"郊庙歌辞 享章怀太子庙乐章 武舞作","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绿林炽炎历，黄虞格有苗。","沙尘惊塞外，帷幄命嫖姚。","七德干戈止，三边云雾消。","宝祚长无极，歌舞盛今朝。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","夏"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"e3e7c18c-7987-4926-ae60-8e2ef9e2d7dd","title":"杂曲歌辞 少年行","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["醉骑白马走空衢，恶少皆称电不如。","五凤街头闲勒辔，半垂衫袖揖金吾。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"人生":["青春"]},"theme_conf":0.66},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"874a0ca3-62ca-4c9f-976b-895b035ac3d6","title":"边城落日","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["紫塞流沙北，黄图灞水东。","一朝辞俎豆，万里逐沙蓬。","候月恒持满，寻源屡凿空。","野昏边气合，烽迥戍烟通。","膂力风尘倦，疆场岁月穷。","河流控积石，山路远崆峒。","壮志凌苍兕，精诚贯白虹。","君恩如可报，龙剑有雌雄。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"慷慨","mood2":[],"scene":["塞外","月"],"cats":{"天气":["太阳"],"人生":["励志","梦想"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"a0d7cfef-2d17-4f6b-983f-ed65c3dff9a2","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹赤白，尽是阻军行。","若是（京本作「似」）虹桥栏着路，且须盘泊犒（京本作「靠」）军兵，不久却回程。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"22e1c91f-ce17-4cb1-8ea4-b10773525c5c","title":"郊庙歌辞 禅社首乐章 肃和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["黄祇是[祗]，我其夙夜。","寅畏诚絜，匪遑宁舍。","礼以琮玉，荐厥茅藉。","念兹降康，胡宁克暇。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"人生":["哲理"]},"theme_conf":0.692},{"uid":"70ea423c-d3c0-4870-885f-4ebadc8b8fcf","title":"久雨期王将军不至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天雨萧萧滞茅屋，空山无以慰幽独。","锐头将军来何迟，令我心中苦不足。","数看黄雾乱玄云，时听严风折乔木。","泉源泠泠杂猿狖，泥泞漠漠饥鸿鹄。","岁暮穷阴耿未已，人生会面难再得。","忆尔腰下铁丝箭，射杀林中雪色鹿。","前者坐皮因问毛，知子历险人马劳。","异兽如飞星宿落，应弦不碍苍山高。","安得突骑只五千，崒然眉骨皆尔曹。","走平乱世相催促，一豁明主正郁陶。","忆昔范增碎玉斗，未使吴兵著白袍。","昏昏阊阖闭氛祲，十月荆南雷怒号。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写雨"],"人生":["梦想"]},"theme_conf":0.558},{"uid":"e9f0c9ff-9301-4ad3-99f5-7283edd3aa6d","title":"伤春赠远","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去水流年日并驰，年光客思两相随。","咨嗟斑鬓今承弁，慙愧新荷又发池。","杨柳逶迤愁远道，鹧鸪啁哳怨南枝。","忆君何啻同琼树，但向春风送别离。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"c2f5bd6f-76a1-4d3f-b5d7-81d81b6c6190","title":"校猎曲","author":"马戴","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["楚子畋郊野，布罟笼天涯。","浮云张作罗，万草结成罝。","意在绝飞鸟，臂弓腰镆鎁。","远将射句践，次欲诛夫差。","壮志一朝尽，他□□繁华。","当时能猎贤，保国兼保家。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["励志","梦想"]},"theme_conf":0.636},{"uid":"60de5a95-c758-49be-ad0a-380712d15cb3","title":"杂曲歌辞 少年行","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["射飞夸侍猎，行乐爱联镳。","荐枕青娥艳，鸣鞭白马骄。","曲房珠翠合，深巷管弦调。","日晚春风里，衣香满路飘。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"a4d6fab0-17cf-448c-97f9-d1345ad69217","title":"青云干吕","author":"王履贞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["异方占瑞气，干吕见青云。","表圣兴中国，来王谒大君。","迎祥殊大乐，叶庆类横汾。","自感明时起，非因触石分。","暎霄难辨色，从吹乍成文。","须使流千载，垂芳在典坟。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"b84b8b0b-9447-467f-819f-0ddf0f00a03a","title":"相和歌辞 饮马长城窟行","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安少年无远图，一生惟羡执金吾。","骐𬴊前殿拜天子，走马为君西击胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国彊兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["夜","塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.803},{"uid":"5c676620-1448-4ee7-815d-35512077d8ad","title":"郑典设自施州归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾怜荥阳秀，冒暑初有适。","名贤慎所出，不肯妄行役。","旅兹殊俗远，竟以屡空迫。","南谒裴施州，气合无险僻。","攀援悬根木，登顿入天石。","青山自一川，城郭洗忧戚。","听子话此邦，令我心悦怿。","其俗则纯朴，不知有主客。","温温诸侯门，礼亦如古昔。","敕厨倍常羞，杯盘颇狼藉。","时虽属丧乱，事贵赏匹敌。","中宵惬良会，裴郑非远戚。","群书一万卷，博涉供务隙。","他日辱银钩，森疎见矛戟。","倒屣喜旋归，画地求所历。","乃闻风土质，又重田畴辟。","刺史似寇恂，列郡宜竞惜。","北风吹瘴疠，羸老思散策。","渚拂蒹葭塞，峤穿萝茑幂。","此身仗儿仆，高兴潜有激。","孟冬方首路，强饭取崖壁。","叹尔疲驽骀，汗沟血不赤。","终然备外饰，驾驭何所益。","我有平肩舆，前途犹准的。","翩翩入鸟道，庶脱蹉跌厄。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":[],"scene":["塞外","冬","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","冬天"],"人生":["读书"],"生活":["边塞"]},"theme_conf":0.593},{"uid":"d4bba55e-36f1-47d1-96af-eb87264434f6","title":"贺收复秦原诸州诗","author":"白敏中","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一诏皇城四海颁，丑戎无数束身还。","戍楼吹笛人休战，牧野嘶风马自闲。","河水九盘收数曲，天山千里锁诸关。","西边北塞今无事，为报东南夷与蛮。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","楼","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.631},{"uid":"4a3c83d8-a6f2-46f7-852b-4d2162d1c6c4","title":"经破薛举战地","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年怀壮气，提戈初仗节。","心随朗日高，志与秋霜洁。","移锋惊电起，转战长河决。","营碎落星沈，阵卷横云裂。","一挥氛沴静，再举鲸鲵灭。","于兹俯旧原，属目驻华轩。","沈沙无故迹，减灶有残痕。","浪霞穿水净，峰雾抱莲昏。","世途亟流易，人事殊今昔。","长想眺前踪，抚躬聊自适。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["战争"]},"theme_conf":0.811},{"uid":"19f067ad-0289-4474-a94a-fe5117350987","title":"求自试","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙禁祥云合，高梧彩凤游。","沈冥求自试，通鉴果蒙收。","文墨悲无位，诗书误白头。","陈王抗表日，毛遂请行秋。","双剑曾埋狱，司空问斗牛。","希垂拂拭惠，感激愿相投。"],"theme":"游仙梦幻","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"7d89d155-45a6-432d-a873-d00d2917c366","title":"送蔡希曾都尉还陇右因寄高三十五书记","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蔡子勇成癖，弯弓西射胡。","健儿宁鬬死，壮士耻为儒。","官是先锋得，材缘挑战须。","身轻一鸟过，枪急万人呼。","云幕随开府，春城赴上都。","马头金狎帢，驼背锦糢糊。","咫尺云山路，归飞青海隅。","上公犹宠锡，突将且前驱。","汉使黄河远，凉州白麦枯。","因君问消息，好在阮元瑜。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":["悲怆"],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.528},{"uid":"4bcfad28-8899-4e64-a87c-5d45a7dddd37","title":"题荐福寺衡岳暕师房","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春城乞食还，高论此中闲。","僧腊堦前树，禅心江上山。","疎帘看雪卷，深户映花关。","晚送门人出，钟声杳霭间。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","春","江","山"],"cats":{"四季":["春天"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"dc52501e-3598-4ebf-bba8-7bf0c3a9a172","title":"归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["化佛示持帚，仲尼称执鞭。","列生御风归，饲豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长绶趋遥泉。","开士行何苦，双瓶胝两肩。","萧寺百余僧，东厨正扬烟。","露足沙石裂，外形巾褐穿。","若其有此身，岂得安稳眠。","独出违顺境，不为寒暑还。","大圣于其中，领我心之虔。","万法常空灭，无生因忍全。","一国一释迦，一灯分百千。","永愿遗世知，现身弥勒前。","潜容偏虚空，灵响不可传。","智慧舍利佛，神通自干连。","阿若楚系简帛陈如，迦叶迦旜延。","左右二菩萨，文殊幷普贤。","身披六铢衣，亿刦为大僊。","宝塔宝楼阁，重簷交梵天。","譬如一明珠，共赞光白圆。","天魔波[旬]等，降伏金刚坚。","野叉罗刹鬼，亦赦尘垢缠。","乃致金翅鸟，吞龙护洪渊。","一十一众中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等无颇偏。","天子事端拱，大臣行其权。","玉堂无蝇飞，五月冰凛筵。","尽力答明主，犹自招罪愆。","九族无白身，百花动婵娟。","神圣恶如此，物华不能妍。","禄山一微胡，驱马来自燕。","宛彼宫阙丽，如何犬羊膻。","苦哉千万人，流血成丹川。","此辈之死后，镬汤所熬煎。","业风吹其魂，猛火烧其烟。","独有丁行者，无忧树枝边。","市头盲老人，长者乞一钱。","韬照多密用，为君吟此篇。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","鸟","中秋","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["哲理"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"221ebe63-3aa2-4662-9c8e-f303d99700bb","title":"送志弥师往淮南","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["已能持律藏，复去礼禅亭。","长老偏摩顶，时流尚诵经。","独行寒野旷，旅宿远山青。","眷属空相望，鸿飞已杳冥。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":0.588},{"uid":"982f789a-c377-4b64-808a-56f36abf9ff0","title":"可叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上浮云如白衣，斯须改变如苍狗。","古往今来共一时，人生万事无不有。","近者抉眼去其夫，河东女儿身姓柳。","丈夫正色动引经，酆城客子王季友。","群书万卷常暗诵，孝经一通看在手。","贫穷老瘦家卖屐，好事就之为携酒。","豫章太守高帝孙，引为宾客敬颇久。","闻道三年未曾语，小心恐惧闭其口。","太守得之更不疑，人生反复看亦丑。","明月无瑕岂容易，紫气郁郁犹冲斗。","时危可仗真豪俊，二人得置君侧否。","太守顷者领山南，邦人思之比父母。","王生早曾拜颜色，高山之外皆培𪣻。","用为羲和天为成，用平水土地为厚。","王也论道阻江湖，李也丞疑旷前后。","死为星辰终不灭，致君尧舜焉肯朽。","吾辈碌碌饱饭行，风后力牧长回首。"],"theme":"羁旅思乡","theme2":["亲情"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.523},{"uid":"86909f2e-2ccb-40d2-8773-8bdec8006cce","title":"赠康洽","author":"李端","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄须康兄酒泉客，平生出入王侯宅。","今朝醉卧又明朝，忽忆故乡头已白。","流年恍惚瞻西日，陈事苍茫指南陌。","声名恒压鲍参军，班位不过扬执戟。","迩来七十遂无机，空是咸阳一布衣。","后辈轻肥贱衰朽，五侯门馆许因依。","自言万物有移改，始信桑田变成海。","同时献赋人皆尽，共壁题诗君独在。","步出东城风景和，青山满眼少年多。","汉家尚壮今则老，发短心长知奈何。","华堂举杯白日晚，龙钟相见谁能免。","君今已反我正来，朱颜宜笑能几回。","借问朦胧花树下，谁家畚插筑高台。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"孤寂","mood2":["慷慨"],"scene":["酒"],"cats":{"抒情":["思乡","孤独"],"人生":["青春","时光"]},"theme_conf":0.96},{"uid":"4b0bc117-6db3-4fe7-a7ac-6df03c52a62a","title":"天边行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天边老人归未得，日暮东临大江哭。","陇右河源不种田，胡骑羌兵入巴蜀。","洪涛滔天风拔木，前飞秃鹙后鸿鹄。","九度附书向洛阳，十年骨肉无消息。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["长江","黄河"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"cpcecdecaab6d888","title":"凤箫吟・芳草","author":"韩缜","dynasty":"宋","section":"宋词","form":"词","paragraphs":["锁离愁，连绵无际，来时陌上初熏。","绣帏人念远，暗垂珠泪，泣送征轮。","长亭长在眼，更重重、远水孤云。","但望极楼高，尽日目断王孙。","消魂。","池塘别后，曾行处、绿妒轻裙。","恁时携素手，乱花飞絮里，缓步香。","朱颜空自改，向年年、芳意长新。","遍绿野，嬉游醉眠，莫负青春。"],"theme":"送别","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["离别","伤感","孤独"],"人生":["青春"]},"theme_conf":0.813},{"uid":"88a56b30-c190-4149-9876-6751971c2597","title":"和刘七读书","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["夜雨深馆静，苦心黄卷前。","云阴留墨沼，萤影傍华编。","梦鸟富清藻，通经仍妙年。","何愁丹穴凤，不饮玉池泉。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","雨"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":1.0},{"uid":"10ef9dd5-f761-4463-9d90-fa9a426ac89c","title":"横吹曲辞 关山月","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱边歌。","海边漠漠天气白，胡儿夜度黄龙碛。","军中探骑暮出城，伏兵暗处低旌戟。","溪水连地霜草平，野𫘞寻水碛中鸣。","陇头风急雁不下，沙场苦战多流星。","可怜万国关山道，年年战骨多秋草。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","山"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.559},{"uid":"4af04ec2-4fde-4a22-8847-3ee2dcb3f527","title":"微之到通州日授馆未安见尘壁间有数行字读之即仆旧诗其落句云渌水红莲一朵开千花百草无颜色然不知题者何人也微之吟叹不足因缀一章兼录仆诗本同寄省其诗乃十五年前初及第时赠长安妓人阿輭绝句缅思往事杳若梦中怀旧感今因酬长句","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十五年前似梦游，曾将诗句结风流。","偶助笑歌嘲阿輭，可知传诵到通州。","昔教红袖佳人唱，今遣青衫司马愁。","惆怅又闻题处所，雨淋江馆破墙头。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["花"],"cats":{"人物":["女子"],"人生":["梦想"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"cpb4d17b6c2877aa","title":"烛影摇红","author":"张抡","dynasty":"宋","section":"宋词","form":"词","paragraphs":["双阙中天，凤楼十二春寒浅。","去年元夜奉宸游，曾侍瑶池宴。","玉殿珠帘尽卷。","拥群仙、蓬壶阆苑。","五云深处，万烛光中，揭天丝管。","驰隙流年，恍如一瞬星霜换。","今宵谁念泣孤臣，回首长安远。","可是尘缘未断。","谩惆怅、华胥梦短。","满怀幽恨，数点寒灯，几声归雁。"],"theme":"羁旅思乡","theme2":["应制干谒"],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["惆怅","悲怆"],"scene":["夜"],"cats":{"抒情":["思乡","孤独"],"人生":["时光"]},"theme_conf":0.52},{"uid":"df7ccf42-3d7d-4927-a388-43ec90d7ec7b","title":"送鸿举游江[西]","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["禅客学禅兼学文，出山初似无心云。","从风卷舒来何处，缭绕巴山不得去。","山州古寺好闲居，读尽龙王宫里书。","使君滩头拣石砚，白帝城边寻野蔬。","忽然登高心瞥起，又欲浮杯信流水。","烟波浩淼鱼鸟情，东去三千三百里。","荆门峡断无盘涡，湘平汉阔清光多。","庐山雾开见瀑布，江西月净闻渔歌。","钟陵八郡多名守，半是西方社中友。","与师相见便谈空，想得高斋狮子吼。"],"theme":"送别","theme2":["闲适隐逸","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"山水":["庐山","江河","瀑布"],"人生":["哲理"],"动物":["写鸟"]},"theme_conf":0.351},{"uid":"7bb37684-e982-4765-bce8-fbfe3b87dc15","title":"赠别王十七管记","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["故交吾未测，薄宦空年岁。","晚节踪曩贤，雄词冠当世。","堂中皆食客，门外多酒债。","产业曾未言，衣裘与人敝。","飘飖戎幕下，出入关山际。","转战轻壮心，立谈有边计。","云沙自廻合，天海空迢递。","星高汉将骄，月盛胡兵锐。","沙深冷陉断，雪暗辽阳闭。","亦谓扫欃枪，旋惊陷蜂虿。","归旌告东捷，鬬骑传西败。","遥飞绝汉书，已筑长安第。","画龙俱在叶，宠鹤先居卫。","勿辞部曲勋，不藉将军势。","相逢季冬月，伥望穷海裔。","折劒留赠人，严装遂云迈。","我行将悠𥾝，及此还羁滞。","曾非济代谋，且有临深诫。","随波混清浊，与物同丑丽。","眇忆青岩栖，宁忘褐衣拜。","自言爱水石，本欲亲兰蕙。","何意薄松筠，翻然重菅蒯。","恒深取与分，孰慢平生契。","欵曲鸡黍期，酸辛别离袂。","逢时愧名节，遇坎悲沦替。","适赵非解纷，游燕往无说。","浩歌方振荡，逸翮思凌励。","倏若异鹏抟，吾当学蝉蜕。"],"theme":"送别","theme2":[],"style":"豪放","style2":["幽峭","清新"],"mood":"相思","mood2":["恬淡","悲怆"],"scene":["冬","山","鸟","雪","月"],"cats":{"抒情":["离别","思念","伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.519},{"uid":"0445f296-5816-4ab9-a617-7d8ed29088ea","title":"凉州词二首 一","author":"王翰","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"人生":["战争"],"生活":["边塞"]},"theme_conf":0.626},{"uid":"db548528-fbd1-4356-bc2d-403760c1267c","title":"登三台言志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["未央初壮汉，阿房昔侈秦。","在危犹骋丽，居奢遂役人。","岂如家四海，日宇罄朝伦。","扇天裁户旧，砌地翦基新。","引月擎宵桂，飘云逼曙鳞。","露除光炫玉，霜阙映雕银。","舞接花梁燕，歌迎鸟路尘。","镜池波太液，庄苑丽宜春。","作异甘泉日，停非路寝辰。","念劳慙逸己，居旷返劳神。","所欣成大厦，宏材伫渭滨。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"慷慨","mood2":[],"scene":["园林","月","鸟","楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"b47a1058-7706-4f5b-b110-c5078de3abd6","title":"题惟干上人房","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绳床茅屋下，独坐味闲安。","苦行无童子，忘机避宰官。","是非齐已久，夏腊比应难。","更悟真如性，尘心稍自宽。"],"theme":"佛道禅颂","theme2":["哲理悟道","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"b6d20c68-6a13-491d-b88c-6f25bcd154b8","title":"冬夜集赋得寒漏","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清冬洛阳客，寒漏建章台。","出禁因风彻，萦窗共月来。","偏将残濑杂，乍与远鸿哀。","遥夜重城警，流年滴水催。","闲斋堪坐听，况有故人杯。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆","恬淡"],"scene":["夜","冬"],"cats":{"四季":["冬天"],"人生":["时光"]},"theme_conf":0.588},{"uid":"4572699f-cc98-457f-8880-7258b363532a","title":"赠沛禅师","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南岳满湘沅，吾师经利涉。","身归沃洲老，名与支公接。","净教传荆吴，道缘止渔猎。","观空色不染，对境心自惬。","室中人寂寞，门外山重叠。","天台积幽梦，早晚当负笈。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","山"],"cats":{"抒情":["孤独"],"人生":["哲理"]},"theme_conf":0.54},{"uid":"45110b81-0f02-4c85-b72a-f2210d10c12f","title":"八哀诗 赠太子师汝阳郡王琎","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汝阳让帝子，眉宇真天人。","虬须似太宗，色映塞外春。","往者开元中，主恩视遇频。","出入独非时，礼异见群臣。","爱其谨洁极，倍此骨肉亲。","从容听朝后，或在风雪晨。","忽思格猛兽，苑囿腾清尘。","羽旗动若一，万马肃𬳽𬳽。","诏王来射雁，拜命已挺身。","箭出飞鞚内，上又回翠麟。","飜然紫塞翮，下拂明月轮。","胡人虽获多，天笑不为新。","王每中一物，手自与金银。","袖中谏猎书，扣马久上陈。","竟无衔橛虞，圣聪矧多仁。","官免供给费，水有在藻鳞。","匪唯帝老大，皆是王忠勤。","晚年务置醴，门引申白宾。","道大容无能，永怀侍芳茵。","好学尚贞烈，义形必沾巾。","挥翰绮绣扬，篇什若有神。","川广不可溯，墓久狐兔邻。","宛彼汉中郡，文雅见天伦。","何以开我悲，泛舟俱远津。","温温昔风味，少壮已书绅。","旧游易磨灭，衰谢增酸辛。"],"theme":"悼亡挽歌","theme2":["送别","边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["月","塞外","雪"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.99},{"uid":"2cb99ff8-0c0b-40c2-8d66-a760adba5c7f","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 九","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹起处，头尾地侵天。","其虹见时非有雨，晴天见者血成川，民更有灾愆。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"4639195c-ea55-4380-a88f-c1b3dca3282e","title":"夜宿灵台寺寄郎士元","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西日横山含碧空，东方吐月满禅宫。","朝瞻双顶青冥上，夜宿诸天色界中。","石潭倒献莲花水，塔院空闻松柏风。","万里故人能尚尔，知君视听我心同。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["夜"],"cats":{"抒情":["友情"],"人生":["哲理"]},"theme_conf":0.9},{"uid":"2e1e7ba7-1beb-4430-a7f2-3e5d7241beec","title":"送樊二十三侍御赴汉中判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["威弧不能弦，自尔无宁岁。","川谷血横流，豺狼沸相噬。","天子从北来，长驱振凋敝。","顿兵岐梁下，却跨沙漠裔。","二京陷未收，四极我得制。","萧索汉水清，缅通淮湖税。","使者纷星散，王纲尚旒缀。","南伯从事贤，君行立谈际。","生知七曜历，手画三军势。","冰雪净聪明，雷霆走精锐。","幕府辍谏官，朝廷无此例。","至尊方旰食，仗尔布嘉惠。","补阙暮征入，柱史晨征憩。","正当艰难时，实藉长久计。","回风吹独树，白日照执袂。","恸哭苍烟根，山门万重闭。","居人莽牢落，游子方迢递。","裴回悲生离，局促老一世。","陶唐歌遗民，后汉更列帝。","恨无匡复姿，聊欲从此逝。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.416},{"uid":"2236d4fc-b6ec-481c-97cb-ac7609dd8382","title":"咏司马彪续汉志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二仪初创象，三才乃分位。","非惟树司牧，固亦垂文字。","緜代更膺期，芳图无辍记。","炎汉承君道，英谟纂神器。","潜龙既可跃，逵兔奚难致。","前史殚妙词，后昆沈雅思。","书言扬盛迹，补阙兴洪志。","川谷犹旧途，郡国开新意。","梅山未觉朽，谷水谁云异。","车服随名表，文物因时置。","凤戟翼康衢，銮舆总柔辔。","清浊必能澄，洪纤幸无弃。","观仪不失序，遵礼方由事。","政宣竹律和，时平玉条备。","文囿雕奇彩，艺门蕴深致。","云飞星共流，风扬月兼至。","类禋遵令典，坛壝资良地。","五胜竟无违，百司诚有庇。","粤予承暇景，谈丛引泉秘。","讨论穷义府，看核披经笥。","大辨良难仰，小学终先匮。","闻道谅知荣，含毫孰忘媿。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"人生":["梦想"],"动物":["写马"]},"theme_conf":0.533},{"uid":"57fcfc8f-4993-43a2-a154-615b75a5105f","title":"八哀诗 赠左仆射郑国公严公武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑公瑚琏器，华岳金天晶。","昔在童子日，已闻老成名。","嶷然大贤后，复见秀骨清。","开口取将相，小心事友生。","阅书百纸尽，落笔四座惊。","历识匪父任，嫉邪常力争。","汉议尚整肃，胡骑忽纵横。","飞传自河陇，逢人问公卿。","不知万乘出，雪涕风悲鸣。","受词劒阁道，谒帝萧关城。","寂寞云台仗，飘飖沙塞旌。","江山少使者，笳鼓凝皇情。","壮士血相视，忠臣气不平。","密论贞观体，挥发岐阳征。","感激动四极，联翩收二京。","西郊牛酒再，原庙丹青明。","匡汲俄宠辱，卫霍竟哀荣。","四登会府地，三掌华阳兵。","京兆空柳色，尚书无履声。","群乌自朝夕，白马休横行。","诸葛蜀人爱，文翁儒化成。","公来雪山重，公去雪山轻。","记室得何逊，韬钤延子荆。","四郊失壁垒，虚馆开逢迎。","堂上指图画，军中吹玉笙。","岂无成都酒，忧国只细倾。","时观锦水钓，问俗终相幷。","意待犬戎灭，人藏红粟盈。","以兹报主愿，庶或裨世程。","炯炯一心在，沈沈二竖婴。","颜回竟短折，贾谊徒忠贞。","飞旐出江汉，孤舟轻荆衡。","虚无马融笛，怅望龙骧茔。","空余老宾客，身上媿簪缨。"],"theme":"悼亡挽歌","theme2":["悼亡挽歌","送别"],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["孤寂"],"scene":["雪","楼","酒","塞外"],"cats":{"抒情":["伤感","孤独","悼亡"],"人生":["战争"]},"theme_conf":0.95},{"uid":"3b39dc82-798d-44db-8452-bf8e17e7d343","title":"客自江南话过亡友朱司议故宅","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["交臂多相共，风流忆此人。","海翻移里巷，书蠹积埃尘。","奉佛栖禅久，辞官上疏频。","故来分半宅，惟是旧交亲。"],"theme":"悼亡挽歌","theme2":["哲理悟道","咏史怀古"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["友情","思念","悼亡","怀古"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"9d22d9e5-04ad-42f1-b88c-7c4b07f012c1","title":"送薛秀才","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虽是寻山客，还同慢世人。","读书惟务静，无褐不忧贫。","野色春冬树，鸡声远近邻。","郄公即吾友，合与尔相亲。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["冬","春","山"],"cats":{"四季":["春天","冬天"],"人生":["读书"]},"theme_conf":0.778},{"uid":"6281fbf0-c461-4efe-ac5d-26e86d33fc49","title":"横吹曲辞 入塞曲 一","author":"沈彬","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["欲为皇王服远戎，万人金甲鼓鼙中。","阵云暗塞三边黑，兵血愁天一片红。","半夜飜营旗搅月，深秋防戍劒磨风。","谤书未及明君𦶟，卧骨将军已殁功。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.894},{"uid":"2d7dac40-92dc-450e-a834-3050521eb709","title":"杂曲歌辞 结客少年场行","author":"沈彬","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["重义轻生一劒知，白虹贯日报讐归。","片心惆怅清平世，酒市无人问布衣。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["酒"],"cats":{"抒情":["思乡","孤独"],"人生":["青春"]},"theme_conf":1.0},{"uid":"9a6006f8-1767-4d21-b631-fdeb28721ec8","title":"诣开悟禅师问心法次第寄韩郎中","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["障深闻道晚，根钝出尘难。","浊劫相从惯，迷途自谓安。","得知身垢妄，始喜额珠完。","欲识真如理，君尝法味看。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人生":["哲理"]},"theme_conf":0.96},{"uid":"cp16bdb8f3299f70","title":"瑞鹤仙","author":"陆淞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["脸霞红印枕。","睡觉来、冠儿还是不整。","屏间麝煤冷。","但眉峰压翠，泪珠弹粉。","堂深昼永。","燕交飞、风帘露井。","恨无人，与说相思，近日带围宽尽。","重省。","残灯朱幌，淡月纱窗，那时风景。","阳台路迥。","云雨梦，便无准。","待归来，先指花梢教看，却把心期细问。","问因循、过了青春，怎生意稳。"],"theme":"闺情宫怨","theme2":["爱情相思","游仙梦幻","山水田园"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"人生":["青春"],"动物":["写鸟"]},"theme_conf":0.274},{"uid":"4ece9f6a-9b24-427a-9ef7-dce93f2f388e","title":"横吹曲辞 出塞曲","author":"刘济","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["将军在重围，音信绝不通。","羽书如流星，飞人甘泉宫。","倚是幷州儿，少年心胆雄。","一朝随召募，百战争王公。","去年桑干北，今年桑干东。","死是征人死，功是将军功。","汗马牧秋月，疲兵卧霜风。","仍闻左贤王，更欲图云中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","秋"],"cats":{"四季":["秋天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.827},{"uid":"31df356e-d9f2-4984-8f0e-66349cab666e","title":"横吹曲辞 关山月","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["汉月生辽海，曈昽出半晖。","合昏玄兔郡，中夜白登围。","晕落关山迥，光合霜霰微。","将军听晓角，战马欲南归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","塞外","山"],"cats":{"抒情":["思乡"],"天气":["月亮"],"人生":["战争"]},"theme_conf":0.544},{"uid":"ce3c68c1-2a48-4f7a-9e13-e0fa27179875","title":"奉和圣制早登太行山中言志","author":"苗晋卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["金吾戒道清，羽骑动天声。","砥路方南绝，重岩始北征。","关楼前望远，河邑下观平。","喜气回舆合，祥风入斾轻。","祝尧三老至，会禹百神迎。","月令农先急，春搜礼复行。","仍亲后土祭，更理晋阳兵。","不似劳车辙，空留八骏名。"],"theme":"应制干谒","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"人生":["梦想"]},"theme_conf":0.97},{"uid":"be76202d-c128-4278-b070-dcb351ae96ae","title":"白马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白马东北来，空鞍贯双箭。","可怜马上郎，意气今谁见。","近时主将戳，中夜商于战。","丧乱死多门，呜呼泪如霰。"],"theme":"边塞征战","theme2":["咏物"],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["悲怆","愁怨"],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.594},{"uid":"56c66dee-7bd0-403b-81a4-6b5d552e776d","title":"相和歌辞 燕歌行","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["国之重镇惟幽都，东威九夷制北胡。","五军精卒三十万，百战百胜擒单于。","前临滹沲后沮水，崇山沃野亘千里。","昔时燕王重贤士，黄金筑台从隗始。","倏忽兴王定蓟丘，汉家又以封王侯。","萧条魏晋为横流，鲜卑窃据朝五州。","我唐区夏余十纪，军容武备赫万祀。","彤弓黄钺授元帅，垦耕大漠为内地。","季秋胶折边草腓，治兵羽猎因出师。","千营万队连旌旗，望之如火忽雷驰。","匈奴慑窜穷发北，大荒万里无尘飞。","隋家昔为天下宰，穷兵黩武征辽海。","南风不竞多死声，鼓卧旗折黄云横。","六军将士皆死尽，战马空鞍归故营。","时迁道革天下平，白环入贡沧海清。","自有农夫已高枕，无劳校尉重横行。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","夏"],"cats":{"四季":["夏天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.626},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"924c524c-67cb-4e2a-9d9b-e16243269c66","title":"杂曲歌辞 少年行三首 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["锦衣鲜华手擎鹘，闲行气貌多轻忽。","稼穑艰难总不知，五帝三王是何物。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人生":["青春"]},"theme_conf":0.88},{"uid":"054f613f-675f-4387-aa4d-428b8a6c601e","title":"赠别褚山人","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["携手赠将行，山人道姓名。","光阴蓟子训，才术褚先生。","墙上梨花白，尊中桂酒清。","洛阳无二价，犹是慕风声。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人生":["时光"]},"theme_conf":0.858},{"uid":"a8ab151d-4d19-4e8a-a5d3-e5cf10d7165e","title":"和袭美醉中即席赠润卿博士次韵","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["共是虚皇简上仙，清词如羽欲飘然。","登山凡著几緉屐，破浪欲乘千里船。","远梦只留丹井畔，闲吟多在酒旗前。","谁知海上无名者，只记渔歌不记年。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"人生":["励志"],"食物":["写酒"]},"theme_conf":0.97},{"uid":"cc5abbb6-01a9-4346-8ba9-29770f446154","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山雨不作埿，江云薄为雾。","晴飞半岭鹤，风乱平沙树。","明灭洲景微，隐见岩姿露。","拘闷出门游，旷绝经目趣。","消中日伏枕，卧久尘及屦。","岂无平肩舆，莫辨望乡路。","兵戈浩未息，蛇虺反相顾。","悠悠边月破，郁郁流年度。","针灸阻朋曹，糠籺对童孺。","一命须屈色，新知渐成故。","穷荒益自卑，飘泊欲谁诉。","虺羸愁应接，俄顷恐违迕。","浮俗何万端，幽人有独步。","庞公竟独往，尚子终罕遇。","宿留洞庭秋，天寒潇湘素。","杖策可入舟，送此齿发暮。"],"theme":"羁旅思乡","theme2":["边塞征战","山水田园","送别"],"style":"清新","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"天气":["写雨"],"人生":["时光"]},"theme_conf":0.356},{"uid":"9d551104-88c1-4011-b24a-2ef8f5e60731","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["如折芙蓉栽旱地，似抛芍药挂高枝。","云埋水隔无人识，唯有南宾太守知。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["月","冬","夏","花","山"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["写云","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.488},{"uid":"8d968574-77fb-46e2-9594-d31f60408227","title":"同群公宿开善寺赠陈十六所居","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驾车出人境，避暑投僧家。","裴回龙象侧，始见香林花。","读书不及经，饮酒不胜茶。","知君悟此道，所未搜袈裟。","谈空忘外物，持诫破诸邪。","则是无心地，相看唯月华。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏","花","酒","月"],"cats":{"四季":["夏天"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.72},{"uid":"fae03a94-8286-4f27-87d2-76a614bdb218","title":"兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 一","author":"易静","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虹霓现，因雨影东西。","晨现必当雨未止，晚来东现日光辉，术者细观之。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","江"],"cats":{"天气":["彩虹"],"人生":["战争"]},"theme_conf":1.0},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"9cefb93d-3695-483a-8ed9-9d15ce5d39b8","title":"南亭晓坐因以示璩","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["隐几日无事，风交松桂枝。","园庐含晓霁，草木发华姿。","迹似南山隐，官从小宰移。","万殊同野马，方寸即灵龟。","弱质常多病，流年近始衰。","图书传授处，家有一男儿。"],"theme":"闲适隐逸","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","园林","山"],"cats":{"人生":["时光"]},"theme_conf":0.86},{"uid":"556a1fa5-a3d2-48cb-bfb7-354c057e042f","title":"季冬自嵩山赴洛道中作","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皇运偶中变，长蛇食中土。","天盖西北倾，众星陨如雨。","胡尘动地起，千里闻战鼓。","死人成为阜，流血涂草莽。","策马何纷纷，捐躯抗豺虎。","甘心赴国难，谁谓荼叶苦。","天子初受命，省方造区宇。","斩鲸安溟波，截鼇作天柱。","三微复正统，五玉归文祖。","不图汉官仪，今日忽再覩。","升高望京邑，佳气连海浦。","宝鼎歊景云，明堂舞干羽。","虎臣囗激昂，囗囗囗御侮。","腐儒著缝掖，何处议邹鲁。","西上轘辕山，丘陵横今古。","和气蒸万物，腊月春霭吐。","得为太平人，穷达不足数。","他日遇封禅，著书继三五。"],"theme":"边塞征战","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山","冬"],"cats":{"抒情":["爱国"],"四季":["冬天"],"人生":["哲理","战争"]},"theme_conf":0.433},{"uid":"428cbfda-43a6-4cb3-9418-d65f2ea45d54","title":"杂曲歌辞 少年行四首 二","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["汉家君臣欢宴终，高议云台论战功。","天子临轩赐侯印，将军佩出明光宫。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"人生":["青春","战争"]},"theme_conf":0.674},{"uid":"643603e3-ff0c-43b7-942b-e2348da428ab","title":"舟泛洞庭","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蛟室围青草，龙堆拥白沙。","护江盘古木，迎櫂舞神鵶。","破浪南风正，收颿畏日斜。","云山千万叠，底处上仙槎。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江","舟","园林"],"cats":{"人生":["励志"]},"theme_conf":0.65},{"uid":"c637d249-8158-48b9-98ee-a2300c0acbde","title":"赠梅处士","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["早闻声价满京城，头白江湖放旷情。","讲易自传新注义，题诗不著旧官名。","近移马迹山前住，多向牛头寺里行。","天子如今议封禅，应将束帛请先生。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","冬"],"cats":{"人生":["哲理"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"5f8937e3-49b1-4ee9-93fe-4ea590143f89","title":"孟氏","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孟氏好兄弟，养亲唯小园。","承颜胝手足，坐客强盘[飧]。","负米力葵外，读书秋树根。","卜邻惭近舍，训子学谁门。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋","园林"],"cats":{"四季":["秋天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"785ddb64-8fd9-402b-b4fc-8cb50e1469ed","title":"琴茶","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["兀兀寄形群动内，陶陶任性一生间。","自抛官后春多醉，不读书来老更闲。","琴里知闻唯渌水，茶中故旧是蒙山。","穷通行止长相伴，谁道吾今无往还。"],"theme":"闲适隐逸","theme2":[],"style":"悲慨","style2":[],"mood":"恬淡","mood2":[],"scene":["春","酒","山"],"cats":{"四季":["春天"],"人生":["读书"],"食物":["写茶"]},"theme_conf":0.94},{"uid":"6acd85a2-fea8-4875-83c5-6ef888f875bc","title":"杂曲歌辞 少年行四首 三","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["出身仕汉羽林郎，初随骠骑战渔阳。","孰知不向边庭苦，纵死犹闻侠骨香。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"人生":["青春"]},"theme_conf":1.0},{"uid":"3505ad96-c84a-4b98-a39f-14ba342b75c1","title":"中丞业深韬畧志在功名再奉长句一篇兼有咨劝","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["樯似邓林江拍天，越香巴锦万千千。","滕王阁上柘枝鼓，徐孺亭西铁轴船。","八部元侯非不贵，万人师长岂无权。","要君严重疎欢乐，犹有河湟可下鞭。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","舟","江","江南"],"cats":{"人生":["励志","梦想"]},"theme_conf":0.86},{"uid":"89948763-087c-4404-b98d-eedc526849ec","title":"同李员外贺哥舒大夫破九曲之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥传副丞相，昨日破西蕃。","作气群山动，扬军大斾翻。","奇兵邀转战，连孥绝归奔。","泉喷诸戎血，风驱死虏魂。","头飞攒万戟，面缚聚辕门。","鬼哭黄埃暮，天愁白日昏。","石城与岩险，铁骑皆云屯。","长策一言决，高踪百代存。","威棱慑沙漠，忠义感乾坤。","老将黯无色，儒生安敢论。","解围凭庙算，止杀报君恩。","唯有关河渺，苍茫空树墩。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":["愁怨"],"scene":["山","塞外"],"cats":{"抒情":["伤感"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.492},{"uid":"bd3a0a24-fd2c-4aa9-86d9-ff08f158bb61","title":"宿诚禅师山房题赠二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宴坐白云端，清江直下看。","来人望金刹，讲席绕香坛。","虎啸夜林动，鼍鸣秋涧寒。","众音徒起灭，心在净中观。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山","秋","夜"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.442},{"uid":"13b12259-3750-4c6d-87ee-35283ad63dab","title":"丹青引赠曹将军霸","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["将军魏武之子孙，于今为庶为清门。","英雄割据虽已矣，文彩风流犹尚存。","学书初学卫夫人，但恨无过王右军。","丹青不知老将至，富贵于我如浮云。","开元之中常引见，承恩数上南熏殿。","凌烟功臣少颜色，将军下笔开生面。","良相头上进贤冠，猛将腰间大羽箭。","褒公鄂公毛发动英姿飒爽来酣战。","先帝天马玉花骢，画工如山貌不同。","是日牵来赤墀下，迥立阊阖生长风。","诏谓将军拂绢素，意匠惨澹经营中。","斯须九重真龙出，一洗万古凡马空。","玉花却在御榻上，榻上庭前屹相向。","至尊含笑催赐金，圉人太仆皆惆怅。","弟子韩干早入室，亦能画马穷殊相。","干惟画肉不画骨，忍使骅骝气凋丧。","将军画善盖有神，必逢佳士亦写真。","即今飘泊干戈际，屡貌寻常行路人。","途穷反遭俗眼白，世上未有如公贫。","但看古来盛名下，终日坎𡒄缠其身。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"豪放","style2":["冲淡"],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人生":["战争"]},"theme_conf":0.399},{"uid":"e74b2d34-c0a4-4049-a02d-b2d9aa00fd80","title":"横吹曲辞 幽州胡马客歌","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽州胡马客，绿眼虎皮冠。","笑拂两只箭，万人不可干。","弯弓若转月，白雁落云端。","双双掉鞭行，游猎向楼兰。","出门不顾后，报国死何难。","天骄五单于，狼戾好凶残。","牛马散北海，割鲜若虎餐。","虽居燕支山，不道朔雪寒。","妇女马上笑，颜如赪玉盘。","飜入射鸟兽，花月醉雕鞍。","旄头四光芒，争战若蜂攒。","白刃洒赤血，流沙为之丹。","名将古谁是，疲兵良可叹。","何时天狼灭？父子得闲安。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁","绮丽"],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["鸟"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.574},{"uid":"1ba275a5-93d8-4d90-9367-7192e01dae10","title":"塞下曲","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见芳树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟守空闺。","独宿自然堪下泪，况复时闻鸟夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["塞外","鸟"],"cats":{"抒情":["伤感","孤独"],"人生":["战争"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.824},{"uid":"8a5d0a21-2700-46ec-b018-e7dc9329251e","title":"奉和御制麟德殿宴百僚应制","author":"尚宫宋氏若昭","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["垂衣临八极，肃穆四门通。","自是无为化，非关辅弼功。","修文招隐伏，尚武殄妖凶。","德炳韶光炽，恩沾雨露浓。","衣冠陪御宴，礼乐盛朝宗。","万寿称觞举，千年信一同。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","雨"],"cats":{"人生":["青春"]},"theme_conf":0.98},{"uid":"527eba4b-b35c-4d29-99e7-8f40c6f3d5b7","title":"杂曲歌辞 行路难三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["金尊清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪暗天。","闲来垂钓坐溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在？长风破浪会有时，直挂云帆济沧海。"],"theme":"咏怀抒感","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":["慷慨","惆怅"],"scene":["酒","江","舟"],"cats":{"山水":["黄河"],"人生":["励志"]},"theme_conf":0.95},{"uid":"bee2cbb1-71a9-4702-91dc-cce9446269ff","title":"徐十八晦落第","author":"欧阳詹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["嘉谷不夏熟，大器当晚成。","徐生异凡鸟，安得非时鸣。","汲汲有所为，驱驱无本情。","懿哉苍梧凤，终见排云征。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人生":["励志"]},"theme_conf":0.65},{"uid":"84b9a130-8145-4902-aac7-5779c17e3fef","title":"饮马长城窟行","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塞外悲风切，交河冰已结。","瀚海百重波，阴山千里雪。","迥戍危烽火，层峦引高节。","悠悠卷斾旌，饮马出长城。","寒沙连骑迹，朔吹断边声。","胡尘清玉塞，羌笛韵金钲。","绝漠干戈戢，车徒振原隰。","都尉反龙堆，将军旋马邑。","扬麾氛雾静，纪石功名立。","荒裔一戎衣，灵台凯歌入。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"6766b37d-23ee-41e7-8aa8-023dfe603107","title":"与独孤穆冥会诗 一","author":"临淄县主","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江都昔丧乱，阙下多搆兵。","豺虎恣吞噬，干戈日纵横。","逆徒自外至，半夜开重城。","膏血浸宫殿，刀枪倚簷楹。","今知从逆者，廼是公与卿。","白刃汚黄屋，邦家遂因倾。","疾风知劲草，世乱识忠臣。","哀哀独孤公，临死乃结缨。","天地既板荡，云雷时未亨。","今者二百载，幽怀犹未平。","山河风月古，陵寝露烟青。","君子秉祖德，方垂忠烈名。","华轩一惠顾，土室以为荣。","丈夫立志操，存没感其情。","求义若可托，谁能抱幽贞。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"沉郁","style2":["豪放","悲慨"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","悼亡"],"人生":["励志","战争"]},"theme_conf":0.639},{"uid":"7715e2f7-4e7e-4794-942e-bfbad57f953d","title":"燕歌行","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["鸟","塞外","秋"],"cats":{"抒情":["离别","思念","伤感","感恩"],"四季":["秋天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.592}];
